INSERT INTO community_messages (id, channel_id, user_id, content, created_at, updated_at, is_pinned, attachments) VALUES ('af0d4213-2bca-47c6-816d-75bf97bef20d', '140f3d60-75a8-4d89-b5ce-3387ed78ee13', NULL, 'Servicio de asistencia – 21 al 23 de noviembre/25\n\nDebido al feriado del 20/11, hemos reorganizado nuestra agenda. Informamos que:\n\n20/11 (jueves): servicio normal\n21/11 (viernes): pausa en las actividades internas (no habrá asistencia técnica y la asistencia administrativa se reducirá)\n22-23 de noviembre (fin de semana): no habrá asistencia técnica ni administrativa\n\nLas solicitudes recibidas durante estos días se responderán en los próximos días laborables.\n\n¡Les deseamos a todos un feliz feriado y fin de semana!\n\n¡Agradecemos su comprensión!', '2025-11-25 13:22:39.83982', '2025-11-25 13:22:39.83982', true, '[]') ON CONFLICT DO NOTHING;
