INSERT INTO community_posts (id, channel_id, user_id, title, content, image_url, likes, created_at, updated_at, video_url, content_blocks, display_order, is_admin_post, is_pinned) VALUES ('2dabacc0-5a75-460d-bcfb-c24849cf04ee', '340b77dc-671c-4eba-9ee9-b05e750e14be', NULL, 'Probando Lasy AI, la nueva aplicación de Ruyter: comparación completa con Lovable.', '¿Vale la pena la herramienta más comentada del momento?\n\nEn el nuevo vídeo del canal, probamos Lasy AI, la nueva herramienta de Ruyter, y Lovable, para que veas la verdad sin filtros.\n\nEn esta prueba real, verás: \n✅ Recursos, integraciones y usabilidad comparados;\n✅ Diferencias prácticas en la creación de aplicaciones simples y complejas;\n✅ Lo que nadie dice sobre las limitaciones, los precios y la experiencia real de uso;\n✅ El camino seguro para iniciarse en No Code sin caer en «trampas» o promesas milagrosas.\n\n¡Vídeo en el aire! Véalo ahora 👉 ', NULL, 0, '2025-11-22 17:17:53.10599', '2025-11-22 17:17:53.10599', ' https://youtu.be/Cw2hrcRsrNU', '[]', 0, false, false) ON CONFLICT DO NOTHING;
INSERT INTO community_posts (id, channel_id, user_id, title, content, image_url, likes, created_at, updated_at, video_url, content_blocks, display_order, is_admin_post, is_pinned) VALUES ('3d693d66-ccb2-4d85-b593-c704ce8f4106', '51a326d1-061d-4a1b-9865-aa620d9e1831', NULL, '🏰 Cómo funciona la comunidad', 'Conocer bien el entorno es el primer paso para sentirse como en casa.\n\nLa comunidad fue diseñada y estructurada para que puedas aprovecharla al máximo.\nLee esta publicación con atención para comprender cómo funciona y está estructurada.\nSección de bienvenida 🎉\n🏠 Empieza aquí: y lee todas las publicaciones de este canal.\n📢 Anuncios: Compartiremos todas las novedades y avisos importantes aquí; todas las publicaciones realizadas por el equipo de No-Code Start-Up son para que aproveches al máximo nuestro ecosistema.\n👋 Preséntate: Canal para que los miembros se presenten.\n\n📽️ Lives y Meetups: Espacio de eventos para transmisiones en vivo recurrentes. \n\nRedes 🌐\n\n🚀 Comparte tu proyecto: ¿Has lanzado o estás a punto de lanzar tu app al mundo? Recopilar retroalimentación en esta etapa es invaluable. Publica tu app, URL y enlace de descarga aquí y pide la opinión de otros miembros de la comunidad.\n🤝 Vacantes y oportunidades: ¡ Hora de hacer negocios! 🤑 Publica aquí ofertas de trabajo, solicitudes de proyectos, oportunidades de asociación y necesidades de mentoría. Si tienes alguna oportunidad con el potencial de generar ingresos para otros miembros, este es el lugar para compartirla.\n💡 Consejos y noticias: Canal dedicado a compartir consejos valiosos. Siéntete libre de publicar cualquier consejo e información que creas que será útil para otros miembros.\n\nSección de preguntas frecuentes ⁉️\nCanales para que publiques tus preguntas sobre las herramientas.\n🟣 FlutterFlow: Canal exclusivo de preguntas y respuestas para miembros de FlutterFlow Training.\n🔵 Bubble: Canal exclusivo de preguntas y respuestas para miembros del Bubble Training Program\n⚪ AppGyver: Canal exclusivo de preguntas y respuestas para miembros del AppGyver Training Program\n🟠 Xano: Canal exclusivo de preguntas y respuestas para miembros del Xano Training Program\n\n🤖 Nota: Dentro de estos canales encontrarás nuestras No-Code AIs - inteligencias artificiales de No-Code Start-Up entrenadas con un amplio conocimiento de cada plataforma.\n\n\nFormación 👨‍💻\n🎓 Cursos para principiantes: Ofrecemos varios cursos de No-Code Start-Up gratis aquí. Aprovecha, aún no estamos seguros de si los mantendremos abiertos siempre.\n📽️ Q&A Lives: Espacio para eventos de Q&A lives.\n🎁 Bonus Lives: Espacio para eventos de bonus lives en la comunidad.\n\n\nAcerca de\n❓ Preguntas frecuentes: Damos respuesta a las preguntas más frecuentes sobre cómo usar la comunidad y también sobre las suscripciones de No-Code Start-Up.\n📝 Sugerencias y Mejoras: Canal exclusivo para que sugieras mejoras para nuestra comunidad y nuestros programas de entrenamiento. ¿Tienes algún consejo o sugerencia para las clases? Publícalo aquí.\n\n\nPreguntas frecuentes:\n¿Cómo creo y edito una publicación?\n¿Por qué hay canales en los que no puedo crear ninguna publicación?', NULL, 0, '2025-11-22 20:35:25.684144', '2025-11-22 21:27:24.643', 'https://youtu.be/3cxCYwK8AaM', '[{"type": "text", "content": "Conocer bien el entorno es el primer paso para sentirse como en casa.\\n\\nLa comunidad fue diseñada y estructurada para que puedas aprovecharla al máximo.\\nLee esta publicación con atención para comprender cómo funciona y está estructurada."}, {"url": "https://youtu.be/3cxCYwK8AaM", "type": "video"}, {"type": "text", "content": "Sección de bienvenida 🎉\\n🏠 Empieza aquí: y lee todas las publicaciones de este canal.\\n📢 Anuncios: Compartiremos todas las novedades y avisos importantes aquí; todas las publicaciones realizadas por el equipo de No-Code Start-Up son para que aproveches al máximo nuestro ecosistema.\\n👋 Preséntate: Canal para que los miembros se presenten.\\n\\n📽️ Lives y Meetups: Espacio de eventos para transmisiones en vivo recurrentes. \\n\\nRedes 🌐\\n\\n🚀 Comparte tu proyecto: ¿Has lanzado o estás a punto de lanzar tu app al mundo? Recopilar retroalimentación en esta etapa es invaluable. Publica tu app, URL y enlace de descarga aquí y pide la opinión de otros miembros de la comunidad.\\n🤝 Vacantes y oportunidades: ¡ Hora de hacer negocios! 🤑 Publica aquí ofertas de trabajo, solicitudes de proyectos, oportunidades de asociación y necesidades de mentoría. Si tienes alguna oportunidad con el potencial de generar ingresos para otros miembros, este es el lugar para compartirla.\\n💡 Consejos y noticias: Canal dedicado a compartir consejos valiosos. Siéntete libre de publicar cualquier consejo e información que creas que será útil para otros miembros.\\n\\nSección de preguntas frecuentes ⁉️\\nCanales para que publiques tus preguntas sobre las herramientas.\\n🟣 FlutterFlow: Canal exclusivo de preguntas y respuestas para miembros de FlutterFlow Training.\\n🔵 Bubble: Canal exclusivo de preguntas y respuestas para miembros del Bubble Training Program\\n⚪ AppGyver: Canal exclusivo de preguntas y respuestas para miembros del AppGyver Training Program\\n🟠 Xano: Canal exclusivo de preguntas y respuestas para miembros del Xano Training Program\\n\\n🤖 Nota: Dentro de estos canales encontrarás nuestras No-Code AIs - inteligencias artificiales de No-Code Start-Up entrenadas con un amplio conocimiento de cada plataforma.\\n\\n\\nFormación 👨‍💻\\n🎓 Cursos para principiantes: Ofrecemos varios cursos de No-Code Start-Up gratis aquí. Aprovecha, aún no estamos seguros de si los mantendremos abiertos siempre.\\n📽️ Q&A Lives: Espacio para eventos de Q&A lives.\\n🎁 Bonus Lives: Espacio para eventos de bonus lives en la comunidad.\\n\\n\\nAcerca de\\n❓ Preguntas frecuentes: Damos respuesta a las preguntas más frecuentes sobre cómo usar la comunidad y también sobre las suscripciones de No-Code Start-Up.\\n📝 Sugerencias y Mejoras: Canal exclusivo para que sugieras mejoras para nuestra comunidad y nuestros programas de entrenamiento. ¿Tienes algún consejo o sugerencia para las clases? Publícalo aquí.\\n\\n\\nPreguntas frecuentes:\\n¿Cómo creo y edito una publicación?\\n¿Por qué hay canales en los que no puedo crear ninguna publicación?"}]', 0, false, false) ON CONFLICT DO NOTHING;
INSERT INTO community_posts (id, channel_id, user_id, title, content, image_url, likes, created_at, updated_at, video_url, content_blocks, display_order, is_admin_post, is_pinned) VALUES ('77e83a40-616c-4b75-aa19-99ac68a90ef3', '340b77dc-671c-4eba-9ee9-b05e750e14be', NULL, ' 🚀 ¡Atención programadores sin código! ¡Noticia sin precedentes! 🤯', 'Hemos lanzado tres módulos totalmente nuevos del curso de Cursor, con contenido que no encontrarás en ningún otro sitio, disponible exclusivamente aquí, en NoCode Startup.\nActualmente, se trata de la formación más completa, práctica y aplicada del mercado, creada para aquellos que quieren dominar el desarrollo con Cursor creando productos reales, de principio a fin.\n\n📌 Importante:\n👉 Como requisito previo, te recomendamos que realices el curso Supabase para principiantes e intermedios, ya que te proporciona toda la base necesaria para sacar el máximo partido a Cursor.\n🔗 Empieza aquí: https://flix.nocodestartup.io/m/c/fundamentos-e-backend-e-modelagem-de-dados-supabase-iniciante\n\n🎓 Módulos disponibles:\n\n1️⃣ Planificación y configuración del proyecto\n🔗 https://flix.nocodestartup.io/m/c/planejamento-e-setup-do-projeto-cursor\n\n2️⃣ Prototipado, UX y defensa de datos\n🔗 https://flix.nocodestartup.io/m/c/prototipacao-ux-e-defesa-de-dados-cursor\n\n3️⃣ Desarrollo y lógica del producto\n🔗 https://flix.nocodestartup.io/m/c/desenvolvimento-e-logica-do-produto-cursor\n\n🔥 Y lo mejor: ¡esto es solo el principio!\nYa se están preparando nuevos módulos que se lanzarán próximamente.\nAsí que aprovechad ahora, avanzad en vuestra formación y preparaos para crear productos completos desde cero utilizando Cursor + Supabase.\n\n¡Seguimos juntos, NoCoders! 🙌🚀', '/api/object-proxy/objects/post-images/post-0beae4c6-8f23-406f-9746-344884a9d456.png', 0, '2025-11-22 17:21:16.408446', '2025-11-25 19:02:26.445', NULL, '[]', 0, false, true) ON CONFLICT DO NOTHING;
INSERT INTO community_posts (id, channel_id, user_id, title, content, image_url, likes, created_at, updated_at, video_url, content_blocks, display_order, is_admin_post, is_pinned) VALUES ('53ba88ba-40dc-4662-b5b9-9c617b6ae200', '51a326d1-061d-4a1b-9865-aa620d9e1831', NULL, '🎉¡Bienvenido a la Comunidad!', 'Este es un espacio dedicado al aprendizaje, el networking, los debates y el intercambio de experiencias sobre el mundo de la IA y el no-code.\n\nVea el vídeo de bienvenida 👇\nCómo empezar:\n\n1. Regístrese respondiendo a nuestro formulario de bienvenida\n2. 👋 Preséntese a la comunidad. ¡Queremos conocerle!\n\nAprovecha al máximo este entorno: lee, aprende, participa y contribuye. Al final, serás uno de los que más se beneficie de todo esto.\n\nInformación complementaria\nLee los 📖 Acuerdos de la comunidad.\nConsulta los 🎯 Consejos y directrices para publicar. \n\n¡Te damos la bienvenida! 🎉', NULL, 0, '2025-11-22 19:53:33.236126', '2025-11-25 19:05:00.617', 'https://youtu.be/Cw2hrcRsrNU', '[{"type": "text", "content": "Este es un espacio dedicado al aprendizaje, el networking, los debates y el intercambio de experiencias sobre el mundo de la IA y el no-code.\\n\\nVea el vídeo de bienvenida 👇"}, {"url": "https://youtu.be/Cw2hrcRsrNU", "type": "video"}, {"type": "text", "content": "Cómo empezar:\\n\\n1. Regístrese respondiendo a nuestro formulario de bienvenida\\n2. 👋 Preséntese a la comunidad. ¡Queremos conocerle!\\n\\nAprovecha al máximo este entorno: lee, aprende, participa y contribuye. Al final, serás uno de los que más se beneficie de todo esto.\\n\\nInformación complementaria\\nLee los 📖 Acuerdos de la comunidad.\\nConsulta los 🎯 Consejos y directrices para publicar. \\n\\n¡Te damos la bienvenida! 🎉"}]', -2, false, true) ON CONFLICT DO NOTHING;
INSERT INTO community_posts (id, channel_id, user_id, title, content, image_url, likes, created_at, updated_at, video_url, content_blocks, display_order, is_admin_post, is_pinned) VALUES ('293e4e64-cefb-4bab-9a7b-1855c45e75b7', '94e3ea50-3ff8-44dd-a002-0debcbc2c9e0', NULL, '👋 Preséntate | Pautas', 'Este espacio se creó para ser tu primera interacción activa con la comunidad, lo cual es fundamental para que todos podamos conocerte mejor.\n\nTambién es tu primera oportunidad para presentarte a posibles futuros amigos, socios, clientes o asociados, así que tómatelo en serio. ¡Preséntate! 👇\n\nNombre:\nEstado/Ciudad:\nOcupación actual:\n¿Cuáles son sus experiencias previas con IA/sin código?:\n¿Cuál es su objetivo al aprender IA y sin código?\n', NULL, 0, '2025-11-24 13:59:04.731777', '2025-11-24 13:59:55.26', NULL, '[{"url": "/api/object-proxy/objects/post-images/image-0d770b64-3a98-4622-ab41-83b49fe6a723.png", "type": "image"}, {"type": "text", "content": "Este espacio se creó para ser tu primera interacción activa con la comunidad, lo cual es fundamental para que todos podamos conocerte mejor.\\n\\nTambién es tu primera oportunidad para presentarte a posibles futuros amigos, socios, clientes o asociados, así que tómatelo en serio. ¡Preséntate! 👇\\n\\nNombre:\\nEstado/Ciudad:\\nOcupación actual:\\n¿Cuáles son sus experiencias previas con IA/sin código?:\\n¿Cuál es su objetivo al aprender IA y sin código?\\n"}]', 0, true, false) ON CONFLICT DO NOTHING;
INSERT INTO community_posts (id, channel_id, user_id, title, content, image_url, likes, created_at, updated_at, video_url, content_blocks, display_order, is_admin_post, is_pinned) VALUES ('88641b9b-0190-48db-ad35-f7bfd13a5ce8', '67957418-d4d6-4e4e-a2c1-58eb9c892b99', NULL, '🚀 Comparte tu Proyecto/Trabajo', '¡Ojos que no ven, corazón que no siente! ¡Comparte tu proyecto o trabajo aquí!\n\nConsejos para publicar:\nIndique el objetivo del proyecto.\n¿Es un proyecto personal/startup/agente/proyecto micro-SaaS o estás desarrollando para otra persona?\nPor favor comenta qué tecnología estás utilizando y cuáles son sus principales características.\n\n¡Comparte algunas fotos si las tienes y puedes! 😁', NULL, 0, '2025-11-24 17:43:45.886445', '2025-11-24 17:44:32.8', NULL, '[{"url": "/api/object-proxy/objects/post-images/image-56f55b33-3fdb-4fe3-a986-cba85d8f1269.png", "type": "image"}, {"type": "text", "content": "¡Ojos que no ven, corazón que no siente! ¡Comparte tu proyecto o trabajo aquí!\\n\\nConsejos para publicar:\\nIndique el objetivo del proyecto.\\n¿Es un proyecto personal/startup/agente/proyecto micro-SaaS o estás desarrollando para otra persona?\\nPor favor comenta qué tecnología estás utilizando y cuáles son sus principales características.\\n\\n¡Comparte algunas fotos si las tienes y puedes! 😁"}]', 0, true, false) ON CONFLICT DO NOTHING;
INSERT INTO community_posts (id, channel_id, user_id, title, content, image_url, likes, created_at, updated_at, video_url, content_blocks, display_order, is_admin_post, is_pinned) VALUES ('bdf256d6-45c8-4394-b93b-f9d7e238ce0a', '73c3a1c4-aaa3-4c2f-9575-026005caca08', NULL, 'Agentes de IA | Directrices', '<p><strong>Utiliza este espacio para resolver tus dudas técnicas relacionadas con los cursos de Automatizaciones N8N sobre Agentes</strong> <br><br><u>Paso 1:</u> utiliza NocodeIA para resolver tu duda 👇 <br><u>Paso 2</u>: ¿No se ha resuelto? Publica tu pregunta en la comunidad. Cuantos más detalles, mejor. Publica capturas de pantalla y describe lo mejor posible el error que te está dando. ¡Así podremos ayudarte más rápidamente!<br></p><hr><p><strong>Consideraciones importantes:</strong> <br></p><ul class="prose-bullet-list"><li><p>El tiempo máximo de respuesta es de 24 horas.</p></li><li><p>Nuestro objetivo es ayudarte con las dudas de las clases. Como algo extra, también buscamos ayudar con orientaciones en dudas sobre proyectos personales. Pero no confundas el soporte de la comunidad con consultoría. </p></li><li><p>Nuestros instructores no atienden los fines de semana.</p></li></ul><p></p>', NULL, 0, '2025-11-25 18:42:21.149484', '2025-11-25 19:47:50.239', NULL, '[{"url": "/api/object-proxy/objects/post-images/image-2ea75df5-da2b-4613-9258-8beafb8b029d.png", "type": "image"}, {"type": "text", "content": "<p><strong>Utiliza este espacio para resolver tus dudas técnicas relacionadas con los cursos de Automatizaciones N8N sobre Agentes</strong> <br><br><u>Paso 1:</u> utiliza NocodeIA para resolver tu duda 👇 <br><u>Paso 2</u>: ¿No se ha resuelto? Publica tu pregunta en la comunidad. Cuantos más detalles, mejor. Publica capturas de pantalla y describe lo mejor posible el error que te está dando. ¡Así podremos ayudarte más rápidamente!<br></p><hr><p><strong>Consideraciones importantes:</strong> <br></p><ul class=\\"prose-bullet-list\\"><li><p>El tiempo máximo de respuesta es de 24 horas.</p></li><li><p>Nuestro objetivo es ayudarte con las dudas de las clases. Como algo extra, también buscamos ayudar con orientaciones en dudas sobre proyectos personales. Pero no confundas el soporte de la comunidad con consultoría. </p></li><li><p>Nuestros instructores no atienden los fines de semana.</p></li></ul><p></p>"}]', 0, true, true) ON CONFLICT DO NOTHING;
