INSERT INTO courses (id, title, description, type, category_id, difficulty, estimated_hours, has_certificate, is_published, created_at, updated_at, cover_image_url, metadata) VALUES ('workshop-1', 'Dominando los agentes de IA para el servicio al cliente con Fin', 'Aprende a usar agentes de IA para mejorar el servicio al cliente', 'workshop', 'cat-1', 'Principiante', NULL, true, true, '2025-08-22 14:33:39.422633', '2025-08-22 19:12:26.808', '/api/lesson-resources/c7e44edf-ceea-4577-b263-015c8d22581f/media-upload.jpg', '{"rating": 0, "duration": "60 min", "videoUrl": "https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh", "instructor": {"name": "Fabián Segura", "title": "Instructor", "avatar": "/api/lesson-resources/b7f5d7c4-8198-4d27-be85-b2ad543b9bbf/avatar-1755881337791.jpg"}, "timestamps": [], "participants": 0, "recordedDate": "22 de agosto de 2025"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, title, description, type, category_id, difficulty, estimated_hours, has_certificate, is_published, created_at, updated_at, cover_image_url, metadata) VALUES ('08660398-173e-4bc9-ab45-09b0fb4d6869', 'Aprenda cualquier cosa con NotebookLM y ChatGPT para una mejor retención', 'Resumen: En el tutorial de hoy, les mostraré la manera más efectiva de aprender cualquier tema con IA. Usaremos una herramienta muy poco conocida, NotebookLM, y la combinaremos con ChatGPT para maximizar la retención, la comprensión y la velocidad.\n\n🧰 ¿Para quién es útil esto?\n\nEstudiantes preparándose para los exámenes\nProfesionales que se capacitan en IA, negocios o campos técnicos\nCreadores de contenido que crean resúmenes o vídeos explicativos\nEstudiantes de por vida que quieren estudiar más rápido y de forma más inteligente\nCaptura de pantalla del 10/09/2025 a las 19:43.41.png\n\n\nPASO 1: Primeros pasos y acceso a Notebook LM\n\nEn primer lugar, dirígete a notebooklm.google.com .\n\nEn la página de inicio, haz clic en el botón "+" . Se abrirá un nuevo cuaderno donde podrás añadir tus materiales de estudio. NotebookLM admite múltiples fuentes, pero para obtener mejores resultados, usa archivos PDF .\n\nPor ejemplo, carguemos una copia en PDF de “ Ingeniería de IA: creación de aplicaciones con modelos de base” de Chip Huyen.\n\nCaptura de pantalla del 10/09/2025 a las 19:42.52.png\n\n\nPASO 2: Entra al estudio y elige tu salida preferida\n\nUna vez cargado tu PDF, NotebookLM lo procesa y te ofrece varios modos de estudio:\n\nResumen – Una descripción general concisa del texto\nMapa mental : conexiones visuales entre conceptos\nDescripción general del audio : narración del material generada por IA\nDescripción general en video : una explicación estilo podcast con elementos visuales\nCaptura de pantalla del 11/09/2025 a las 10:01:24.png\n\n\nEl Resumen en Video es una nueva función ideal para mejorar la comprensión. Crea una explicación del material con estilo de presentación, similar a una miniconferencia de YouTube.\n\nCaptura de pantalla del 10/09/2025 a las 19:42.29.png\n\n\nPASO 3: Genere guías de estudio a partir del archivo del libro cargado\n\nVisita la sección Informes → Guía de Estudio .\n\nAquí, NotebookLM genera:\n\nPreguntas y respuestas para evaluar la comprensión\nPreguntas de respuesta corta (por ejemplo, "¿Cuál es la diferencia entre los modelos de lenguaje enmascarado y los modelos autorregresivos?")\nIndicaciones de estilo ensayo\nGlosarios de términos clave\nEste enfoque estructurado le ofrece una manera paso a paso de internalizar el material, no solo de hojearlo.\n\nCaptura de pantalla del 10/09/2025 a las 19:39.57.png\n\n\nPASO 4: Profundizar la comprensión con ChatGPT\n\nAhora que tiene los resúmenes, las guías y la descripción general en video de NotebookLM, lleve su PDF a ChatGPT.\n\nAquí te explicamos cómo maximizarlo:\n\nSube tu libro (debe ser PDF - no se admiten EPUB).\nChat rápidoGPT con:\n“Lea este libro capítulo por capítulo y resalte todas las partes confusas”.\n“Extraer las ideas centrales que debo entender de este texto”.\n“Pregúntame sobre los conceptos más importantes”.\nPara obtener mejores resultados, active modos de razonamiento de mayor calidad con GPT-5 Thinking.\n\n\nPASO 5: Poniéndolo todo junto\n\nEsta combinación de inicio en NotebookLM y finalización en ChatGPT le permite:\n\nObtener contexto rápido (NotebookLM)\nAprenda interactivamente (Guía de estudio + Preguntas y respuestas)\nProfundiza y aclara las partes complicadas (ChatGPT)\n\n\nConsejo profesional: Si tu fuente está en formato EPUB o audiolibro , conviértela a PDF antes de subirla. Tanto NotebookLM como ChatGPT gestionan archivos PDF de forma óptima.\n\nEste flujo de trabajo cambia por completo tu forma de abordar el aprendizaje. Con la práctica, retendrás más, aprenderás más rápido e incluso generarás contenido de estudio de alta calidad, similar a la experiencia en el aula.', 'guide', 'cat-1', 'beginner', 1, false, true, '2025-08-23 17:17:23.235758', '2025-09-11 14:48:25.408', '/api/lesson-resources/5ff2ceb6-ed6e-49e8-8ea0-d55925c9cc50/media-upload.jpg', '{"resources": [], "instructor": {"name": "Fabián Segura", "title": "Consultor/Educador de IA", "avatar": "/api/lesson-resources/b1b760ee-ea63-477c-b180-da418bfb64ed/media-upload.jpg"}, "recordedDate": ""}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, title, description, type, category_id, difficulty, estimated_hours, has_certificate, is_published, created_at, updated_at, cover_image_url, metadata) VALUES ('bed9ee88-a19a-44ae-b667-694f1e630bf5', 'Fundamentos N8N - Domina el 80/20', 'En este módulo repasaremos los principios esenciales de n8n.\n\nVeremos:\n\n- Qué es n8n y las automatizaciones\n- Cómo funciona la instalación en un servidor propio para no pagar alojamiento\n- Módulos y nodos importantes\n-  El 20 % de conocimiento que generará el 80 % de los resultados', 'course', 'cat-2', 'intermediate', 1, false, true, '2025-11-17 19:24:47.717498', '2025-11-17 19:24:47.717498', '/api/object-proxy/objects/uploads/c270e696-4b33-4c77-a186-fd9344fa6246', '{}') ON CONFLICT DO NOTHING;
