INSERT INTO courses (id, title, description, type, category_id, difficulty, estimated_hours, has_certificate, is_published, created_at, updated_at, cover_image_url, metadata) VALUES ('5dfdeacd-6626-4106-bd92-3d4f336cca20', 'Interactúa con archivos PDF, hojas de cálculo y archivos | Agentes RAG - N8N', 'En este módulo, aprenderás a crear agentes de IA que puedan interpretar documentos personalizados, como PDF y hojas de cálculo, y responder en función de ellos. Exploraremos la integración entre los LLM y las bases de datos, utilizando Supabase para almacenar y recuperar información de manera eficiente.\n\nVerás en la práctica cómo estructurar todo el flujo, desde la conversión de archivos hasta la implementación del agente de IA. Además, comprenderemos los fundamentos de RAG (Retrieval-Augmented Generation) y cómo aplicarlo para que tu agente sea más inteligente y personalizado.\n\n¡Prepárate para una experiencia práctica e inmersiva para construir tu propio agente de IA!', 'course', 'cat-agentesia', 'beginner', 1, false, true, '2025-12-06 12:49:43.661255', '2025-12-06 12:49:43.661255', 'https://ehmihfufuufthefwrnrb.supabase.co/storage/v1/object/public/attached-assets/media-a1927db7-f3b9-4d9b-ac7a-458b81590efc.jpg', '{}') ON CONFLICT DO NOTHING;
