INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('b1904076-c64d-4f95-ba79-aeca44e0c86a', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Introducción', NULL, '<h2><strong>Bienvenido a tu paquete de inicio de IA definitivo</strong></h2><p><em>(Domine los fundamentos de la IA y aumente su productividad hoy mismo)</em></p><p></p><p>El movimiento profesional más peligroso este año no es usar mal la IA.</p><p>No utiliza IA en absoluto.</p><p>Aquí tienes tu kit de inicio de IA completo para dominar los fundamentos:</p><p>La mayoría de las personas abordan la IA al revés. Se lanzan a usar indicaciones avanzadas y herramientas complejas antes de comprender los conceptos básicos.</p><p>¿Resultado? Abrumador y frustración.</p><p>El Kit de Inicio de IA simplifica al máximo la tarea. Esto es lo que aprenderás:</p><p>Primero, comprenda qué es realmente la IA:</p><ul class="prose-bullet-list"><li><p>Una herramienta que aprende de los datos</p></li><li><p>Su asistente personal de productividad</p></li><li><p>Un multiplicador de fuerza para tus habilidades</p></li></ul><p>No es magia. No da miedo. Simplemente es increíblemente poderoso si se usa correctamente.</p><p>Aprenderás:</p><ul class="prose-bullet-list"><li><p>Fundamentos básicos de IA sin la jerga técnica</p></li><li><p>Cómo integrar la IA en su flujo de trabajo diario</p></li><li><p>Qué herramientas realmente importan (y cuáles ignorar)</p></li><li><p>Marcos simples que funcionan en todas las plataformas de IA</p></li></ul><p>El curso se divide en módulos claros:</p><ul class="prose-bullet-list"><li><p>Fundamentos de la IA</p></li><li><p>Maestría en ChatGPT</p></li><li><p>Selección avanzada de herramientas</p></li><li><p>Ingeniería rápida</p></li><li><p>Automatización del flujo de trabajo</p></li></ul><p>Cada uno diseñado para aprovechar el anterior.</p><p>Al finalizar, usted:</p><ul class="prose-bullet-list"><li><p>Ahorre más de 10 horas por semana en tareas rutinarias</p></li><li><p>Crea mejor contenido en la mitad del tiempo</p></li><li><p>Haga de la IA su ventaja competitiva</p></li><li><p>Manténgase a la vanguardia de los cambios rápidos</p></li></ul><p>La revolución de la IA no está por llegar. Ya está aquí.</p><p>Y esta es tu hoja de ruta completa para dominarlo.</p>', 1, '2025-08-20 20:35:00.688093', 'text', 10, true, false, NULL, NULL, NULL, '2025-08-20 20:35:00.688093', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('3fcdc3df-c361-4a55-82b7-205ef7f7c592', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Una guía paso a paso para ChatGPT', NULL, '<p>Ahora que ya comprendes bien qué es un modelo de lenguaje extenso, el siguiente paso es aprender más sobre el líder del mercado en IA generativa.&nbsp;</p><p>Hoy repasaremos cómo empezar a usar ChatGPT si eres nuevo en esto. Descubrirás qué es, cómo empezar y las mejores maneras de sacarle el máximo provecho.&nbsp;</p><p>Al finalizar esta sesión, contarás con una guía sencilla para crear indicaciones efectivas y sacar el máximo provecho de ChatGPT.<br><br><strong>Aprenderás lo siguiente:</strong></p><ul class="prose-bullet-list"><li><p>¿Qué es ChatGPT?</p></li><li><p>Cómo acceder</p></li><li><p>Marco de indicaciones de 6 pasos de Rundown</p></li><li><p>Caso de uso: replicar cualquier estilo de escritura</p></li></ul><h3><strong>¿Qué es ChatGPT?</strong></h3><p>ChatGPT, un chatbot de IA creado por OpenAI, se lanzó en 2022. Está impulsado por grandes modelos de lenguaje (LLM), lo que le permite responder a la entrada del usuario con una naturalidad sorprendente. ChatGPT se usa para diversas tareas: redacción de contenido, tutoría, programación e incluso para proporcionar información clara y relevante.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-21.png" alt="imagen-21.png" width="800" height="480"><p></p><h3><strong>Cómo usarlo</strong></h3><p><strong>Accediendo a ChatGPT</strong></p><p>Para acceder a ChatGPT, visita <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://chatgpt.com"><strong>https://chatgpt.com</strong></a> . Es completamente gratuito y no necesitas crear una cuenta.</p><p>Para este tutorial, quédese con el plan gratuito; cubriremos todo lo que necesita saber antes de considerar una actualización.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-22.png" alt="imagen-22.png" width="800" height="480"><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-23.png" alt="imagen-23.png" width="800" height="480"><p></p><p><strong>Precios</strong></p><ul class="prose-bullet-list"><li><p><strong>Plan gratuito:</strong> Explora las tareas cotidianas con acceso básico a GPT-5, búsqueda web en tiempo real, carga de archivos limitada, análisis de datos, generación de imágenes y modo de voz. Incluye el uso de GPT personalizados y edición de código mediante la app de escritorio ChatGPT para macOS. Ideal para usuarios ocasionales.</p></li><li><p><strong>Plan Plus – $20/mes:</strong> Desbloquea todo en el plan gratuito más:</p><ul class="prose-bullet-list"><li><p>Acceso ampliado a GPT-5 (modelo insignia de OpenAI)</p></li><li><p>Límites de uso más altos para mensajería, carga de archivos y generación de imágenes</p></li><li><p>Acceso a modos de voz estándar y avanzados (incluidos video y compartir pantalla)</p></li><li><p>Uso del agente ChatGPT</p></li><li><p>Capacidad de crear y utilizar proyectos, tareas y GPT personalizados</p></li><li><p>Acceso limitado a la generación de videos de Sora</p></li><li><p>Acceso anticipado para probar nuevas funciones</p></li></ul></li></ul><ul class="prose-bullet-list"><li><p><strong>Plan Pro:</strong></p><ul class="prose-bullet-list"><li><p>Obtén lo mejor de OpenAI con todo lo que incluye Plus, además:</p></li><li><p>Acceso ilimitado a GPT-5 y GPT-5 Pro (utiliza más recursos de procesamiento para obtener los mejores resultados de su clase)</p></li><li><p>Acceso ilimitado al modo de voz avanzado con límites más altos</p></li><li><p>Acceso a OpenAI o3-pro (computación adicional para las preguntas más difíciles)</p></li><li><p>Acceso extendido tanto al agente ChatGPT como a la generación de video de Sora</p></li><li><p>Acceso a la vista previa de investigación del agente del Codex para tareas relacionadas con el código</p></li></ul></li></ul><p><strong>Cómo utilizar la interfaz de usuario principal</strong></p><ol class="prose-ordered-list"><li><p><strong>Iniciar sesión</strong> : acceda a ChatGPT e inicie sesión con sus credenciales.</p></li><li><p><strong>Panel principal</strong> : Familiarízate con la interfaz. El panel es intuitivo y ofrece opciones para iniciar una nueva conversación, acceder a chats anteriores y ajustar la configuración.</p></li><li><p><strong>Iniciar una conversación</strong> : Inicia un nuevo chat introduciendo tu mensaje en la opción "Pregunta lo que quieras". ChatGPT responde en tiempo real, generando texto con un aspecto similar al de una persona según tus comentarios.</p></li></ol><h3><strong>El marco de 6 pasos de The Rundown</strong></h3><p>Utilizar ChatGPT de manera efectiva puede marcar una diferencia significativa en la calidad y relevancia de la herramienta.</p><p>A continuación se muestra nuestra fórmula de indicaciones de 6 pasos de clase mundial, que puede utilizar como plantilla para ayudar a guiar la redacción de sus indicaciones.</p><p>Analicemos cada paso:</p><ol class="prose-ordered-list"><li><p><strong>Tarea</strong> : Comienza con un verbo de acción que exprese tu solicitud. Define claramente el objetivo final.</p></li><li><p><strong>Contexto</strong> : Proporcionar detalles relevantes sobre la situación y los antecedentes.</p></li><li><p><strong>Ejemplos</strong> : Incluya texto de muestra para demostrar el estilo deseado.</p></li><li><p><strong>Persona (opcional)</strong> : Adopta un punto de vista o personaje específico si es necesario.</p></li><li><p><strong>Formato</strong> : especifique la estructura de salida que desee.</p></li><li><p><strong>Tono</strong> : Indica la emoción y el estilo de lenguaje preferidos.</p></li></ol><img class="prose-image" src="/api/object-proxy/objects/uploads/5154a36a-a1a0-4695-a6b7-2797b3792b13"><p>El orden es lo más importante. Con la práctica, este marco te ofrece una plantilla para guiar ChatGPT y ofrecerte exactamente lo que necesitas. ¡Sigue la lista de verificación y obtendrás excelentes resultados!</p><p><br><strong>PASO 1: Definición de la tarea</strong></p><p>Empieza con un verbo de acción. Explica con claridad y concisión lo que quieres que ChatGPT haga.</p><p><strong>Empezar con verbos de acción</strong></p><p>Usa verbos de acción claros como <strong>"generar", "escribir", "analizar",</strong> etc., para empezar. Luego, explica los detalles de la tarea que debes realizar.</p><p><strong>La tarea puede ser sencilla:</strong></p><p><em>“Genérame un plan de dieta de tres meses”.</em></p><p><strong>O más complejo:</strong></p><p><em>Resumir las conclusiones clave de los comentarios de los usuarios para mi boletín informativo, centrándose en las áreas de mejora. Luego, clasificar los comentarios restantes por orden de prioridad.</em></p><p>Definir la tarea de forma clara y concisa es crucial para que ChatGPT comprenda tus necesidades. Prepara el modelo para brindar la respuesta exacta que buscas.</p><p><em>PD: No es necesario decir por favor ni gracias a ChatGPT: ¡no tiene sentimientos!</em></p><img class="prose-image" src="/api/object-proxy/objects/uploads/c76f432e-21cf-4ce4-9114-075b8b084172"><p><strong>PASO 2: Proporcionar contexto relevante</strong></p><p>Contexto significa proporcionar a ChatGPT detalles clave para adaptar su respuesta a su situación particular.</p><p>Algunas preguntas útiles para determinar qué contexto incluir:</p><ul class="prose-bullet-list"><li><p>¿Cuáles son los antecedentes del usuario?</p></li><li><p>¿Cómo se ve el éxito?</p></li><li><p>¿Cuál es el entorno/configuración?</p></li></ul><p>Por ejemplo:</p><p><em>Soy un hombre de 113 kilos y mi objetivo es perder 9 kilos de grasa en tres meses. Solo tengo tiempo para cocinar una vez a la semana, los domingos, durante dos horas. ¿Podrían proporcionarme un plan de dieta de tres meses para ayudarme a alcanzar mis objetivos dentro de estas limitaciones?</em></p><p>El contexto aquí muestra a ChatGPT su punto de partida y sus limitaciones, lo que le permite sugerir un plan de dieta adecuado.</p><p>Proporcionar contexto relevante le da a ChatGPT lo que necesita para ofrecer respuestas útiles y personalizadas en lugar de genéricas. ¡Cuantos más detalles, mejor!</p><img class="prose-image" src="/api/object-proxy/objects/uploads/48d57fd5-eca6-4884-9cc5-d1cabab2b9d2"><p><strong>PASO 3: Proporcionar ejemplos</strong></p><p>Incluir ejemplos en tu solicitud le da a ChatGPT un modelo a <strong>seguir en cuanto a estilo, estructura y tono.</strong> Por ejemplo, puedes pegar un ejemplo de descripción de puesto al pedirle a ChatGPT que la redacte. Imitará los patrones del ejemplo que proporciones.</p><p>Ejemplo de mensaje:</p><p><em>Eres un gerente de contratación y necesitas redactar una descripción de puesto para un puesto de Gerente de Marketing centrado en el reconocimiento de marca. Usa esta descripción de puesto existente como ejemplo de formato y estilo: [pegar ejemplo]</em></p><p>Ahora, ChatGPT puede seguir la estructura de la publicación de trabajo de ejemplo para elaborar una descripción personalizada utilizando su contexto.</p><blockquote><p><em>Nota: Los ejemplos no siempre son necesarios, pero guían a ChatGPT para que se ajuste al tono y formato deseados, en lugar de ofrecer una respuesta genérica. Proporcionar ejemplos relevantes siempre que sea posible mejora los resultados de las solicitudes para que se ajusten a un estilo específico.</em></p></blockquote><img class="prose-image" src="/api/object-proxy/objects/uploads/01d3a1eb-71b6-4d19-ad97-529c848d9f40"><p><strong>PASO 4: Asignación de una Persona</strong></p><p>Persona es un paso opcional en el marco que permite a ChatGPT representar un personaje o experiencia específica. Imagina tener acceso instantáneo a un experto relevante para tu tarea. Por ejemplo, si te lesionas practicando algún deporte, este experto podría ser un fisioterapeuta con más de 20 años de experiencia. O, si buscas empleo, esa persona podría ser un gerente de contratación que busca cubrir un puesto en tu equipo.</p><p>Por ejemplo:</p><p><em>“Respondo como fisioterapeuta con 20 años de experiencia, sugiero un programa de rehabilitación de 2 meses para mi lesión de codo de tenista”.</em></p><p>O</p><p><em>“Actúa como gerente de contratación de una importante empresa y dame una lista de posibles preguntas de entrevista para las que deba prepararme”.</em></p><p><strong>Consejo útil:</strong> Incluso puedes <strong>pedirle a ChatGPT que imite a personajes famosos</strong> , usando, por ejemplo, este mensaje: <strong>"Reescribe este pasaje al estilo de Shakespeare".</strong></p><p>Adoptar una personalidad le da a ChatGPT una perspectiva desde la cual escribir. Esto puede enriquecer sus respuestas con conocimiento del dominio o una voz interesante.</p><p>Tenga en cuenta que es un elemento de solicitud opcional, pero puede llevar los resultados al siguiente nivel. La clave es proporcionar suficiente contexto y ejemplos para que ChatGPT adopte la personalidad correctamente.</p><img class="prose-image" src="/api/object-proxy/objects/uploads/24c0a7e9-7406-45a2-aafe-c20ff0ed37ef"><p><strong>PASO 5: Especificación del formato</strong></p><p>También puedes guiar la estructura de la respuesta de ChatGPT especificando un formato en tu mensaje. ¿Quieres una tabla, viñetas o un párrafo? Indícalo en tu mensaje.</p><p>Por ejemplo:</p><p><em>“Resumir los puntos clave de retroalimentación de los lectores de mi boletín en un formato de tabla con columnas para la retroalimentación original, el nivel de prioridad y la dificultad para abordarla”.</em></p><p>Esto le indica a ChatGPT que desea una salida de tabla en lugar de párrafos o viñetas.</p><p>Formatos que ChatGPT puede generar:</p><ul class="prose-bullet-list"><li><p>Correo electrónico</p></li><li><p>Mesa</p></li><li><p>Lista de viñetas</p></li><li><p>Bloques de código</p></li><li><p>Párrafo</p></li><li><p>Reducción</p></li><li><p>Diálogo</p></li><li><p>Hoja de cálculo</p></li><li><p>Código del diagrama</p></li></ul><p>Especificar un formato por adelantado garantiza que el resultado se ajuste a tus necesidades. Si no lo indicas, ChatGPT mostrará una respuesta en párrafo de forma predeterminada. ¡Ser explícito te permite ser creativo con la estructura!</p><img class="prose-image" src="/api/object-proxy/objects/uploads/26d84be7-d771-4452-ae23-f457ead6e1ac"><p><strong>PASO 6: Establecer el tono</strong></p><p>El tono define el tono del texto. Puedes especificar si quieres un tono informal, formal, ingenioso o entusiasta directamente en ChatGPT. A veces, puede ser difícil describir el tono específico que quieres incluir. Pero no te preocupes, también hay una guía si te quedas atascado.</p><p>Para obtener el tono perfecto para tu mensaje, simplemente describe tus sentimientos:</p><p><em>Estoy redactando un correo electrónico para un equipo nuevo. Quiero sonar profesional, pero sin ser demasiado formal. Sugieranme cinco tonos que pueda usar para mi borrador.</em></p><p>Ahora, selecciona tu tono favorito de la lista e ingrésalo en tu mensaje completo.</p><p>Ejemplos de indicaciones:</p><ol class="prose-ordered-list"><li><p>“Utilice un tono de voz informal”</p></li><li><p>“Utilice un tono de voz formal”</p></li><li><p>“Dame una salida ingeniosa”</p></li><li><p>“Muestra entusiasmo”</p></li><li><p>“Suena pesimista”</p></li></ol><p>Al especificar un tono, ChatGPT se adapta al contexto emocional que necesitas. Esto hace que el lenguaje sea natural y apropiado para la situación.</p><img class="prose-image" src="/api/object-proxy/objects/uploads/a3c7dd52-37ee-4578-8dfb-46910b468451"><p><span style="font-size: 18px;"><strong>Uniéndolo todo</strong></span></p><p>Después de recorrer cada paso del marco de indicaciones, aquí hay un ejemplo de indicaciones que reúne todos los elementos clave:</p><p><em>“Quiero que escribas un [TIPO DE ESCRITURA] de [NÚMERO] palabras sobre [ESTE TEMA ESPECÍFICO] para mí, escrito en un tono que sea [DESCRIBIR EL TONO].</em></p><p><em>El texto debe adaptarse a [LECTOR OBJETIVO ESPECÍFICO, PROPORCIONAR CONTEXTO].</em></p><p><em>Debe formatearse con [PROPORCIONE INSTRUCCIONES DE FORMATO]</em></p><p><em>Como esto:</em></p><p><em>[FORMATO DE EJEMPLO]</em></p><p><em>El propósito de este texto es [CUÁL ES EL RESULTADO OBJETIVO PARA USTED].</em></p><p><em>Para contextualizar, soy un [LO QUE HACES, DAR CONTEXTO] que mira hacia [TU OBJETIVO]”.</em></p><p>Con la práctica, te sentirás cómodo combinando las piezas del marco de forma creativa y adaptada a tus necesidades. Empieza con ideas sencillas y, a medida que ganes experiencia, ve aumentando la complejidad.</p><p>La clave es proporcionar instrucciones claras para que ChatGPT pueda ayudarte eficazmente. La práctica y la experimentación perfeccionarán esto.</p><p></p><h3><strong>Caso de uso de introducción: Replicar cualquier estilo de escritura</strong></h3><p>Una de las mejores características de ChatGPT es su capacidad para imitar diferentes estilos, tonos y formatos de escritura a partir de ejemplos. Esto es especialmente útil para creadores de contenido que desean mantener la coherencia en sus proyectos.</p><p><strong>En la sección de solicitud, puede agregar la siguiente solicitud:</strong></p><blockquote><p><em>Eres uno de los mejores creadores de contenido de internet. Te hemos proporcionado las publicaciones con mejor rendimiento que has creado. Tu tarea es crear una publicación sobre [cualquier tema]. Es muy importante que uses el mismo estilo de escritura, tono y estructura que los ejemplos a continuación:</em></p></blockquote><p>[Ejemplo 1: …]</p><p>[Ejemplo 2: …]"</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-31.png" alt="imagen-31.png" width="3012" height="1554"><p></p><p>Con esto, ChatGPT puede generar borradores para su nuevo contenido que coincidan perfectamente con el estilo de los ejemplos proporcionados, lo que permite consistencia y calidad en sus publicaciones.</p><p><strong>Consejo:&nbsp;</strong> También puedes hablar con ChatGPT usando la función de voz. Accede haciendo clic en el icono de los auriculares en la esquina inferior derecha de la app móvil de ChatGPT. Mantén pulsado el círculo blanco en la pantalla para evitar interrupciones.&nbsp;</p><p><strong>Has aprendido&nbsp;</strong> a usar ChatGPT para solicitar ayuda de manera efectiva y a hablarle para obtener los mejores resultados.&nbsp;</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-32.png" alt="imagen-32.png" width="800" height="480"><p><br></p>', 8, '2025-08-27 14:11:58.584202', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-08-27 14:11:58.584202', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('8ada4b1e-c843-4d19-bb77-217d587807fa', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Cómo usar la IA en tu vida diaria', NULL, '<p>Muy bien, entendemos claramente que la IA es poderosa y nos damos cuenta de la necesidad de mejorar las habilidades en IA.&nbsp;</p><p><em>¿Pero cómo?&nbsp;</em></p><p>¿Cómo cambiamos la forma en que pensamos sobre el trabajo, la vida personal y la integración de nuevas tecnologías?&nbsp;</p><p>Esto requiere un gran cambio de mentalidad. De eso tratamos aquí.&nbsp;</p><p>Aprenderá la mentalidad necesaria para prosperar en la era de la IA.&nbsp;</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Reconociendo la oportunidad de oro de la IA</p></li><li><p>Seis consejos inteligentes para adoptar la IA</p></li><li><p>Un enfoque estructurado para aprender herramientas de IA</p></li></ul><h2><strong>La mentalidad para prosperar en la era de la IA</strong></h2><h3><strong>Reconocer la oportunidad de oro</strong></h3><p>Estás a punto de descubrir una de las oportunidades más importantes de nuestro tiempo: la IA está aquí y está revolucionando la forma en que trabajamos.</p><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://slack.com/blog/productivity/maximizing-work-productivity"><strong>Un estudio</strong></a> de Slack sugiere que quienes trabajan desde una oficina dedican el 41 % de su tiempo a tareas repetitivas . Al integrar la IA, puedes recuperar ese tiempo para realizar tareas estratégicas y significativas.<strong>&nbsp;</strong></p><img class="prose-image" src="/api/object-proxy/objects/uploads/916a06c0-8804-466a-bca3-ea0e42b698ff"><p>Las tareas repetitivas, como resumir documentos e ingresar datos, pueden consumir horas, reducir la productividad y frenar la innovación. Esta ineficiencia corre el riesgo de quedarse atrás en un mercado competitivo y disminuir la satisfacción laboral.</p><p>Con la IA pretendemos solucionar estas ineficiencias.&nbsp;</p><p><strong>Por dónde empezar</strong> :&nbsp;</p><h2><strong>6 pasos que debes seguir para ganar en la era de la IA.</strong></h2><p>¿Por qué es importante aprender IA?</p><p>Es el futuro del trabajo.</p><p>En un futuro próximo, todos los trabajadores del conocimiento del mundo tendrán que integrar IA en sus flujos de trabajo.</p><p>Sam Altman <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://x.com/rowancheung/status/1787164459712073845"><strong>dijo</strong></a> recientemente que estamos "a punto de entrar en la mayor era dorada de las posibilidades humanas".</p><p>Aquí hay algunos datos del reciente estudio de Slack con 10.000 trabajadores.</p><ul class="prose-bullet-list"><li><p>En enero de 2024, 1 de cada 4 trabajadores de escritorio informaron que habían probado herramientas de IA para el trabajo.</p></li><li><p>Y alrededor del 80% dice que esta tecnología ya está mejorando su productividad.</p></li></ul><p>Si aún no has empezado, aquí te dejo mi consejo:</p><img class="prose-image" src="/api/object-proxy/objects/uploads/a45f49f8-0229-441c-b84e-58c09914d14a"><h3><strong>PASO 1: Comience poco a poco, pero comience ahora</strong></h3><p>Lo bueno de ser principiante en este momento es que el espacio se mueve muy rápido.</p><p>Se lanzan tantos avances que es posible alcanzar a los primeros usuarios con bastante rapidez.</p><p>Si empiezas ahora, aún estás pronto.</p><img class="prose-image" src="/api/object-proxy/objects/uploads/e1275dc2-2f5b-47e8-b4e9-49b5e7aa8ec7"><h3><strong>PASO 2: Piensa como un solucionador de problemas</strong></h3><p>Aquí es donde la mayoría de los principiantes cometen errores: prueban todas las nuevas y brillantes herramientas de inteligencia artificial que existen.</p><p>He estado allí, pero hay demasiadas herramientas y perderás tiempo y dinero.</p><p>Primero, encuentra el problema que quieres automatizar. Luego, encuentra la herramienta.</p><img class="prose-image" src="/api/object-proxy/objects/uploads/351b14b8-f6e2-454d-9cd7-c01b97d7f691"><ul class="prose-bullet-list"><li><p><strong>Enumera tus tareas:</strong> escribe tus tareas diarias e identifica aquellas que son repetitivas y consumen mucho tiempo.</p></li><li><p><strong>Evalúe el potencial de la IA</strong> : Pregúntese: "¿Podría una herramienta de IA ayudar con esto?". Céntrese en las tareas donde la IA pueda tener el mayor impacto.</p></li></ul><p>Cada vez que pienses: "Tiene que haber una mejor manera de hacer esto", anótalo.</p><p>Éstas son sus oportunidades de integración de IA.</p><h3><strong>PASO 3: No intentes reinventar la rueda</strong></h3><p><strong>Encuentra inspiración en los demás</strong></p><p>Este es el código de trucos para comenzar más rápido.</p><p>El mejor lugar para hacer esto es, sin lugar a dudas, Expertos NoCode IA, donde puedes encontrar más de 200 casos de uso y aprender de otros usuarios pioneros sobre cómo están integrando la IA.</p><p>Pero X también es genial.</p><p></p><h3><strong>PASO 4: No intentes dominar todas las herramientas de IA a la vez</strong></h3><p>Después de encontrar los problemas que puedes automatizar, ahora es el momento de encontrar la herramienta que pueda resolverlos.</p><p>Un sitio recomendado para encontrar las mejores herramientas de IA: <strong>Herramientas</strong> (mi base de datos de herramientas de IA gratuita)</p><p>Consejo profesional: desplázate hasta el final y haz clic en mi sección "Mejores selecciones".</p><p></p><h3><strong>PASO 5: Realice un seguimiento de su progreso</strong></h3><p><strong>Aprender haciendo</strong></p><p>La mejor manera de aprender ahora es experimentar con las herramientas y tratar de resolver aquellos problemas que tengas.</p><p>Primero inténtalo tú mismo, luego si te quedas atascado, busca tutoriales en YT, Twitter o incluso intenta preguntar en Perplexity.</p><img class="prose-image" src="https://lh7-rt.googleusercontent.com/docsz/AD_4nXcsyeS8EyXO7mTM0GwynGEgS1kzT-ZslRy3K38I8dKjLwQs9xeGAw9rLBwE93c1fU2ZV3sIxebr8171sacNmUDvbtmNlnWtmKe0op9fKymNMXzlNbrnWPfHR2Ns0bZVDuVgtL4U4A?key=whQNRL_GUd20THdzlF5GZA" width="978" height="653"><p><strong>A continuación se presenta un enfoque estructurado para aprender herramientas de IA:</strong></p><ol class="prose-ordered-list"><li><p>Establecer un problema objetivo a resolver (por ejemplo, "Usar IA para crear una campaña de marketing")</p></li><li><p>Elija una herramienta relevante</p></li><li><p>Prueba y error, o seguir un tutorial</p></li><li><p>Aplícalo a tu tarea del mundo real.</p></li><li><p>Reflexionar sobre el proceso y los resultados</p></li></ol><h3><strong>PASO 6: Crea una "hora de innovación en IA"</strong></h3><p><strong>Manténgase actualizado</strong></p><p>Podría decirse que éste es el paso más importante.</p><p>Establezca una fecha en su calendario cada semana para sentarse durante un par de horas y ponerse al día con las noticias, probar nuevas herramientas y comenzar a automatizar lentamente su trabajo.</p><p>Aquí está mi plan de acción completo:</p><img class="prose-image" src="/api/object-proxy/objects/uploads/d3c3b0c1-9aea-4e4d-ab95-5878fb58e907"><p>Al seguir este plan de acción, se asegurará de estar siempre actualizado con las últimas herramientas y flujos de trabajo de IA.</p><p>El futuro del trabajo ya está aquí, asegúrate de estar preparado.</p><p><br><strong>Consejo útil:</strong> Cuanto más tiempo inviertas ahora en aprender IA, más influencia tendrás dentro de unos años, cuando todo el mundo empiece a adoptar y usar IA a diario.</p><p><strong>Esto es lo que has aprendido:</strong><br>ahora que entiendes la enorme oportunidad que tenemos ante nosotros y los pasos necesarios para integrar la IA, pasemos a superar los desafíos que impiden que las personas adopten la IA.</p>', 5, '2025-08-21 13:48:49.324045', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-08-21 13:48:49.324045', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('f27ee8c8-2731-4021-b788-20bf7184920a', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'El impacto y los tipos de IA: por qué es importante para usted', NULL, '<p>Ahora que hemos aprendido los conceptos clave de la IA, es hora de explorar más sobre las capacidades de la IA y por qué deberíamos preocuparnos por aprender y aplicar la IA en 2025.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Comprender las capacidades y limitaciones de la IA</p></li><li><p>Aprenda a incorporar IA a su flujo de trabajo diario</p></li><li><p>Asegúrese de utilizar la IA de forma responsable en su trabajo</p></li></ul><p>¡Vamos a saltar!</p><p><strong>Capacidades de la IA</strong></p><p>La IA ha transformado las industrias al asumir tareas que requieren inteligencia humana.&nbsp;</p><img class="prose-image" src="https://lh7-rt.googleusercontent.com/docsz/AD_4nXfKV2dCykjJTxMLuLuQolqvCnoxuBJL0mkTOU3sLUKYceC1GaXcLGME4w16kSEjDoV5QeJNgGMt1wSjKkYR_VpySavKl50U7XCtUUM3QvuY38Y6fU_t-Je0g9B1559KlJPSQ14PGA?key=whQNRL_GUd20THdzlF5GZA" width="1125" height="751"><p>Las capacidades clave incluyen:</p><ul class="prose-bullet-list"><li><p><strong>Reconocimiento de patrones y análisis de datos:</strong> la IA descubre información a partir de datos complejos, lo que ayuda en el mantenimiento predictivo, la detección de fraudes y el diagnóstico.</p></li><li><p><strong>Automatización de tareas repetitivas:</strong> la IA gestiona de manera eficiente tareas rutinarias, como chatbots, generación de contenido y automatización de procesos.</p></li><li><p><strong>Procesamiento del lenguaje natural (PLN):</strong> la IA interpreta y genera lenguaje humano, potenciando los asistentes virtuales, la traducción y el resumen de textos.</p></li><li><p><strong>Generación de contenido:</strong> la IA crea artículos, imágenes, videos y más basándose en la entrada de lenguaje natural y datos existentes.</p></li><li><p><strong>Visión y detección por computadora:</strong> la IA identifica objetos y actividades en imágenes y videos, lo cual es crucial para los autos autónomos y el reconocimiento facial.</p></li><li><p><strong>Aprendizaje y adaptación continuos:</strong> la IA mejora con nuevos datos, pero la supervisión humana es vital para abordar problemas como el sesgo y la seguridad.</p></li></ul><p><strong>Limitaciones de la IA</strong></p><p>Si bien la IA es poderosa, también es fundamental comprender sus limitaciones:</p><ul class="prose-bullet-list"><li><p><strong>Transparencia:</strong> los modelos de IA, especialmente el aprendizaje profundo, a menudo actúan como "cajas negras", lo que dificulta la comprensión de su proceso de toma de decisiones.</p></li><li><p><strong>Creatividad:</strong> la IA tiene dificultades para ser verdaderamente creativa y original, y a menudo carece de los matices que aportan los humanos.</p></li><li><p><strong>Dependencia de los datos:</strong> la precisión de la IA depende de datos imparciales y de alta calidad; los datos de mala calidad pueden generar resultados incorrectos.</p></li><li><p><strong>Inteligencia emocional:</strong> la IA no puede comprender completamente las emociones humanas, lo que limita su eficacia en áreas como la salud mental y el servicio personalizado.</p></li><li><p><strong>Amplificación de sesgos:</strong> la IA puede reforzar involuntariamente los sesgos existentes a partir de datos históricos, lo que exacerba las desigualdades sociales.</p></li></ul><p>Incorpore la IA a su flujo de trabajo diario</p><p>Ahora que ha explorado las capacidades y limitaciones de la IA, quizá se pregunte cómo incorporarla a su flujo de trabajo. Aquí tiene una guía paso a paso:</p><img class="prose-image" src="https://lh7-rt.googleusercontent.com/docsz/AD_4nXdJIFxLPHINQ8AqCL6W39bTBs8P3LXa7tLlZL7wgem3q6zZ6SFQcoH4XOHoHjgHf_Tn5DT7Ut2BajSewj2Ab3NvGPNPHqjhdz7TWQBtNUaAMC0sv1QTivANGb26z7xOBofJdi8rEQ?key=whQNRL_GUd20THdzlF5GZA" width="978" height="653"><ul class="prose-bullet-list"><li><p><strong>Identifique tareas para la automatización de IA:</strong> concéntrese en tareas repetitivas como creación de documentos, análisis de datos, programación y atención al cliente.</p></li><li><p><strong>Investigue las herramientas de IA adecuadas:</strong> elija herramientas de IA que se ajusten a sus necesidades, centrándose en las capacidades, la integración y la seguridad de los datos.</p></li><li><p><strong>Implementar gradualmente:</strong> comience con herramientas simples, capacite a su equipo y recopile comentarios para perfeccionar su uso.</p></li><li><p><strong>Fomentar la colaboración entre humanos e IA:</strong> utilizar la IA para mejorar, no reemplazar, las capacidades humanas, manteniendo la supervisión de las tareas críticas.</p></li><li><p><strong>Aprendizaje continuo:</strong> manténgase actualizado sobre los avances de la IA y ajuste los flujos de trabajo a medida que la IA evoluciona.</p></li></ul><p>Exploremos dos escenarios prácticos:</p><h2><strong>✍️ Escenario 1: IA para marketing</strong></h2><p>Conozca a Sarah, una gerente de marketing que busca optimizar el proceso de creación de contenido de su equipo.</p><p><strong>Paso 1: Identificar tareas para la automatización de la IA</strong>&nbsp;</p><p>Sarah, gerente de marketing, identifica tareas como redactar publicaciones de blogs, títulos para redes sociales y boletines informativos por correo electrónico como áreas en las que la IA podría ahorrar tiempo.</p><p><strong>Paso 2: Investigar y seleccionar herramientas de IA adecuadas</strong>&nbsp;</p><p>Ella selecciona herramientas de escritura de IA como <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://Jasper.ai"><strong>Jasper.ai</strong></a> o <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://Copy.ai"><strong>Copy.ai</strong></a> por sus capacidades de generación de lenguaje y personalización de marca.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-6.png" alt="imagen-6.png" width="1920" height="532"><p></p><p><strong>Paso 3: Implementar herramientas de IA gradualmente</strong>&nbsp;</p><p>Sarah comienza con borradores generados por IA para publicaciones de blog, capacita a su equipo, recopila comentarios y gradualmente amplía el uso de IA a otras tareas de contenido.</p><p><strong>Paso 4: Fomentar la colaboración entre humanos e IA</strong>&nbsp;</p><p>Ella enfatiza que la IA es un asistente, no un reemplazo, y que su equipo perfecciona los borradores de IA con su propia creatividad y conocimientos.</p><p><strong>Paso 5: Aprendizaje continuo y adaptación</strong>&nbsp;</p><p>El equipo de Sarah se mantiene actualizado sobre los avances de la IA, adaptando los flujos de trabajo y explorando nuevas herramientas para mejorar la creación de contenido.</p><h2><strong>📽️ Escenario 2: IA para la creación de vídeos</strong></h2><p>Conozca a Paul, un director que adopta nuevas tecnologías para mejorar su flujo de trabajo de producción.</p><p>Paul es un director que adopta las nuevas tecnologías. Utiliza herramientas de IA como Notion AI y Midjourney para agilizar la comunicación con su equipo, visualizar escenas y optimizar el flujo de trabajo de producción.</p><p><strong>Paso 1: Identificar tareas para la automatización de la IA</strong>&nbsp;</p><p>Paul, un director, identifica tareas como la escritura de guiones, la creación de guiones gráficos y la visualización de escenas que podrían beneficiarse de la asistencia de la IA.</p><p><strong>Paso 2: Investigar y seleccionar herramientas de IA adecuadas</strong>&nbsp;</p><p>Elige Notion AI para generar pautas y esquemas de historias, y Midjourney para crear guiones gráficos visuales y arte conceptual a partir de descripciones de texto.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-7.png" alt="imagen-7.png" width="1920" height="980"><p></p><p><strong>Paso 3: Implementar herramientas de IA gradualmente</strong>&nbsp;</p><p>Paul comienza con Notion AI para obtener ideas de guiones, luego perfecciona el proceso y usa Midjourney para visualizar escenas y crear marcos de guiones gráficos.</p><p><strong>Paso 4: Fomentar la colaboración entre humanos e IA</strong>&nbsp;</p><p>Paul ve a la IA como un asistente que perfecciona sus resultados con su aporte creativo mientras colabora con su equipo para mantener el control artístico.</p><p><strong>Paso 5: Aprendizaje continuo y adaptación</strong>&nbsp;</p><p>Se mantiene actualizado sobre los avances de IA asistiendo a talleres y cursos, adaptando su flujo de trabajo y explorando herramientas como RunwayML para mejorar su proceso creativo.</p><p><strong>Flujos de trabajo de IA esenciales para el trabajo</strong></p><p>Más allá de estos escenarios, también puedes considerar estos flujos de trabajo comunes impulsados por IA (profundizaremos en ellos en las próximas lecciones):</p><ol class="prose-ordered-list"><li><p><strong>Asistencia para la redacción:</strong> utilice herramientas de inteligencia artificial como ChatGPT, Jasper y <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://Copy.ai">Copy.ai</a> para redactar, delinear y generar ideas de contenido para blogs, artículos, correos electrónicos y redes sociales.</p></li><li><p><strong>Automatización de tareas:</strong> Automatice tareas como la programación, la entrada de datos y las comunicaciones masivas con herramientas de flujo de trabajo de IA como Zapier y Make. Optimice los procesos y monitoree el progreso con información en tiempo real.</p></li><li><p><strong>Análisis de datos:</strong> aproveche la IA para analizar grandes conjuntos de datos y realizar predicciones, pronósticos y recomendaciones precisas.</p></li><li><p><strong>Generación de contenido visual:</strong> optimice el arte conceptual y la lluvia de ideas con herramientas de inteligencia artificial como DALL-E, Midjourney y Stable Diffusion.</p></li><li><p><strong>Gestión de la productividad:</strong> utilice asistentes virtuales de IA para administrar notas de reuniones, correos electrónicos, cronogramas y listas de tareas pendientes de manera eficiente.</p></li></ol><blockquote><p><em>¿Conoces algún flujo de trabajo de IA que nadie haya descubierto aún? Compártelo en redes sociales y etiqueta a </em><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://twitter.com/TheRundownAI"><strong><em>@especialistasnocode.</em></strong></a></p></blockquote><p><br><strong>Garantizar un uso responsable de la IA</strong></p><p>Para utilizar la IA de forma eficaz y responsable, siga estos pasos:</p><ul class="prose-bullet-list"><li><p><strong>Adoptar enfoques centrados en el ser humano:</strong> utilizar la IA como una herramienta de asistencia con objetivos claros, no como un reemplazo de la inteligencia humana.</p></li><li><p><strong>Revisar los resultados de la IA:</strong> garantizar la supervisión humana para verificar la precisión y evitar errores de la IA.</p></li><li><p><strong>Divulgar el uso de IA:</strong> sea transparente sobre la participación de la IA, distinguiendo el contenido generado por IA del trabajo humano.</p></li><li><p><strong>Considere la privacidad y la seguridad:</strong> evalúe y proteja la privacidad y seguridad de los datos, implementando prácticas éticas.</p></li><li><p><strong>Utilice la IA para el bien:</strong> céntrese en aplicaciones de IA socialmente beneficiosas, evaluando y mitigando cualquier posible impacto negativo.</p></li></ul><p><strong>Esto es lo que has aprendido:</strong><br>ahora que comprendes las capacidades de la IA y cómo se utiliza en el lugar de trabajo, pasemos a estudiar y adoptar la mentalidad necesaria para integrar la IA en nuestra vida personal y profesional.</p>', 4, '2025-08-21 13:47:13.425974', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-08-21 13:47:13.425974', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('3e747f63-46df-4d3d-9b4c-4ed838c00aef', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Investigue eficazmente con citas precisas utilizando Perplexity AI', NULL, '<p>Google ha sido el motor de búsqueda predilecto durante gran parte de las últimas dos décadas. A diferencia de ChatGPT o Claude, cuando buscamos, buscamos resultados y fuentes de información relevantes.&nbsp;</p><p>Perplexity AI es el motor de búsqueda del futuro. Funciona como un motor de búsqueda tradicional similar a Google, con un amplio modelo de lenguaje integrado, similar a ChatGPT, para una mayor funcionalidad de IA.</p><p>En esta lección, cubriremos cómo usar Perplexity AI para realizar una investigación efectiva y usarlo como Google 2.0.</p><p>Al final, sabrás qué es Perplexity, cómo acceder a ella y comenzarás a obtener mejores resultados de búsqueda.&nbsp;</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>¿Qué es la perplexity?</p></li><li><p>Principales casos de uso</p></li><li><p>Cómo acceder a Perplexity AI</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-84.png" alt="imagen-84.png" width="800" height="480"><p></p><h3><span style="font-size: 28px;"><strong>1. ¿Qué es Perplexity?</strong></span></h3><p>Perplexity va más allá de las simples búsquedas de palabras clave. Utiliza modelos de lenguaje de vanguardia como GPT-4 Omni y Claude 3 para comprender el contexto y los matices de la consulta. A continuación, se detalla el proceso:</p><ol class="prose-ordered-list"><li><p>Perplexity utiliza IA para comprender tu pregunta con precisión.</p></li><li><p>Busca en la web, extrayendo información de fuentes confiables como artículos y revistas, e incluso puede proporcionar actualizaciones en vivo.</p></li><li><p>Luego resume los puntos clave en una respuesta clara.</p></li><li><p>Las fuentes se citan con notas a pie de página para facilitar su verificación y lectura adicional.</p></li></ol><p>Perplexity tiene como objetivo hacer que el descubrimiento de información sea más intuitivo y conversacional, yendo más allá de las limitaciones de los motores de búsqueda tradicionales.</p><p>Los usuarios están reemplazando su motor de búsqueda Google con Perplexity y sólo en el verano el LLM ha respondido más de mil millones&nbsp; <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://x.com/AravSrinivas/status/1828431343480668523"><strong>de consultas</strong></a> .</p><h3><span style="font-size: 28px;"><strong>2. Principales casos de uso:</strong></span></h3><ul class="prose-bullet-list"><li><p>Investigación y recopilación de información: investigación académica, investigación de mercado, verificación de datos.</p></li><li><p>Creación de contenido: generar ideas, crear esquemas de contenido, optimizar el SEO.</p></li><li><p>Aprendizaje continuo: tutoriales educativos, conocimientos de la industria.</p></li></ul><img class="prose-image" src="/api/lesson-resources/bc6c94db-0855-4c90-b586-c0203f1b94d6/image-1756774153439-27cuai.jpg"><h2><span style="font-size: 28px;"><strong>3. Aquí te explicamos cómo acceder:</strong></span><strong><br><br></strong><span style="font-size: 24px;"><strong>1. Primeros pasos con </strong></span><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://Perplexity.AI"><span style="font-size: 24px;"><strong>Perplexity.AI</strong></span></a></h2><p>A menudo se lo conoce como Google 2.0 y está ganando popularidad como alternativa de Google en muchos navegadores.</p><p>Visita <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://Perplexity.AI"><strong>Perplexity.AI</strong></a> y crea una cuenta. Ofrecen una prueba gratuita, suficiente para la mayoría de los usuarios, pero también puedes optar por la versión Pro por $20 al mes.</p><h3><span style="font-size: 24px;"><strong>2. Navegación por la interfaz</strong></span></h3><p>Una vez que te hayas registrado e iniciado sesión, podrás explorar tanto la app móvil como la versión de escritorio. En la barra lateral, verás pestañas como "Inicio" y "Descubrir".</p><p>La pestaña "Inicio" es donde comenzará su búsqueda, mientras que la pestaña "Descubrir" ofrece una amplia gama de los artículos más recientes para fines de investigación. Esta función es perfecta para quienes desean profundizar en diversos temas.</p><h3><strong><br></strong><span style="font-size: 24px;"><strong>3. Realizar una búsqueda</strong></span></h3><p>Perplexity destaca por ofrecer fuentes al final de cada resultado de búsqueda, lo que facilita la verificación de la información. En comparación con otras herramientas de IA como ChatGPT, Perplexity presenta menos alucinaciones.</p><p>Para iniciar una búsqueda, simplemente escribe tu consulta en la barra "Preguntas". Por ejemplo, podrías comparar los chips M2 y M3 de Apple para ver cuál es mejor y dónde comprarlo.</p><h3><span style="font-size: 24px;"><strong>4. Restringir su búsqueda</strong></span></h3><p>Lo que hace única a Perplexity es su capacidad para enfocar tu búsqueda en segmentos específicos. Puedes buscar en redes sociales, videos de YouTube, artículos académicos y más.</p><p>Por ejemplo, si desea centrarse en la investigación académica, puede filtrar su búsqueda según sus necesidades. Esto le ayudará a limitar los resultados a la información más relevante.</p><h3><span style="font-size: 24px;"><strong>5. Revisión y uso de resultados</strong></span></h3><p>Una vez que tengas los resultados, verás varias fuentes como The Verge, MacRumors y más. Puedes hacer clic en cualquiera de estas fuentes para leer los artículos completos.</p><p>Perplexity también ofrece preguntas relacionadas, que te ayudan a pensar en aspectos que quizás no hayas considerado. Puedes hacer preguntas adicionales, como preguntar si la MacBook Air M3 es mejor que la Mac Pro M2.</p><h3><span style="font-size: 24px;"><strong>6. Creación de contenido a partir de su investigación</strong></span></h3><p>Perplexity es ideal para generar contenido. Puedes convertir tu investigación en un tuit o una publicación, ideal para administradores de redes sociales. Por ejemplo, después de comparar chips, podrías pedirle a Perplexity que cree una publicación de Twitter de menos de 180 caracteres.</p><p>Si tienes la cuenta Pro, incluso puedes generar imágenes utilizando la integración de Perplexity con Flux, un generador de imágenes de IA avanzado.</p><p><strong>Consejo:</strong> Ve a la pestaña "Descubrir" a la izquierda y encontrarás todas las noticias más recientes en un solo lugar. Puedes chatear con el artículo seleccionando "Solicitar seguimiento".</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-86.png" alt="imagen-86.png" width="1400" height="840"><p></p><p><strong>Esto es lo que has aprendido.</strong><br>Ya sabes cómo será el motor de búsqueda del futuro y cómo usarlo. Permíteme mostrarte cómo cambiar tu motor de búsqueda predeterminado a Perplexity AI.&nbsp;</p>', 20, '2025-09-02 00:46:29.054454', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 00:46:29.054454', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('fc52402e-b653-4c77-b958-f2807c154ae1', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Organice reuniones más eficientes con Grain', NULL, '<p><span style="font-family: Satoshi, sans-serif;">Antes, la mayoría de las empresas asignaban a un miembro de su equipo para que tomara notas de las reuniones y las compartiera posteriormente con todos mediante correos electrónicos manuales.<br><br>Este proceso ahora está totalmente automatizado.</span></p><p><span style="font-family: Satoshi, sans-serif;">En esta lección, veremos cómo usar Grain para obtener información valiosa de tus reuniones. Esta capacidad de recibir un resumen con marca de tiempo, grabaciones de calidad y notas de la reunión enviadas directamente a tu CRM es fantástica.</span></p><p><span style="font-family: Satoshi, sans-serif;">Al final, sabrás qué es Grain, cómo acceder a él y comenzar a grabar tus reuniones.&nbsp;</span></p><p><span style="font-family: Satoshi, sans-serif;"><strong>En esta lección, cubriremos:</strong></span></p><ul class="prose-bullet-list"><li><p><span style="font-family: Satoshi, sans-serif;">Introducción a los asistentes de reuniones de IA y sus diferencias</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">¿Qué es el grano?</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Cómo acceder</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Utilice Grain para recopilar información de las reuniones</span></p></li></ul><h2><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>¿Por qué asistentes de reuniones con inteligencia artificial?</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Necesitas un asistente de reuniones con IA. <em>¿Por qué?&nbsp;</em></span></p><p><span style="font-family: Satoshi, sans-serif;">Para asegurarnos de que nunca más tengas reuniones improductivas.<br>Porque en la era de la IA, podemos:</span></p><ul class="prose-bullet-list"><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Automatice las transcripciones, en lugar de escribir notas y distraerse.</strong></span></p></li><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Obtenga información y pasos de acción resumidos y enviados por correo electrónico.</strong></span></p></li><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Lluvia de ideas sobre los próximos pasos después de una reunión con IA.</strong></span></p></li><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Reducir el desgaste mental de las reuniones diarias.</strong></span></p></li><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Ejecute reuniones en piloto automático.</strong></span></p></li></ul><p><span style="font-family: Satoshi, sans-serif;"><br>Hay una variedad de asistencia de reuniones con inteligencia artificial en el mercado, a saber, <strong>Grain, Otter y Fireflies.</strong>&nbsp;</span></p><h2><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>A continuación se muestran algunas diferencias clave entre ellos:</strong></span></h2><h3><span style="font-family: Satoshi, sans-serif;"><strong>Tabla comparativa</strong></span></h3><img class="prose-image" src="/api/lesson-resources/abe2ebcf-8841-4c66-bba4-508e09dd69c1/image-1756770668937-1ghgq8.jpg"><h3><span style="font-family: Satoshi, sans-serif; font-size: 24px;"><strong>Nuestro favorito:&nbsp;</strong></span></h3><h3><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://grain.com/"><span style="font-family: Satoshi, sans-serif; font-size: 24px;"><strong>Grain</strong></span></a></h3><p><span style="font-family: Satoshi, sans-serif;">Grain es un increíble asistente de reuniones con IA que automatiza tus reuniones, captura notas perfectas y las genera para ofrecerte la mejor información, para que puedas concentrarte en la reunión sin tener que recordar todos los detalles.<br><br>El plan gratuito es bastante generoso y te ofrece 20 reuniones. Puedes crear nuevas franjas horarias simplemente eliminando tus reuniones antiguas.</span></p><p><span style="font-family: Satoshi, sans-serif;">Dime que no te ha pasado lo siguiente: asistes a una reunión y te parece productiva, se te ocurren muchas ideas, pero al día siguiente no recuerdas nada.<br><br>El otro extremo es que odias las reuniones, no quieres asistir y simplemente desearías poder automatizar el proceso.&nbsp;</span></p><p><span style="font-family: Satoshi, sans-serif;">En ambos escenarios, Grain es la solución perfecta.&nbsp;</span></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-79.png" alt="imagen-79.png" width="1996" height="1248"><p></p><h3><span style="font-family: Satoshi, sans-serif;"><strong>Aquí te explicamos cómo acceder:</strong></span></h3><h2><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>1. Introducción de Grain</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Para empezar a usar Grain, visita </span><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://grain.com/"><span style="font-family: Satoshi, sans-serif;"><strong>su sitio web</strong></span></a><span style="font-family: Satoshi, sans-serif;"> y crea una cuenta gratuita. La versión gratuita incluye hasta 20 reuniones gratuitas, lo que te da la oportunidad de probar sus funciones.</span></p><h2><span style="font-family: Satoshi, sans-serif;"><strong><br></strong></span><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>2. Grabación y transcripción de sus reuniones</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Una vez iniciada la sesión, Grain se unirá automáticamente a tus reuniones virtuales o puede configurarse para grabar el audio en reuniones presenciales. Grain captura toda la conversación y crea una transcripción completa a la que puedes acceder en cualquier momento.</span></p><p><span style="font-family: Satoshi, sans-serif;"><strong>Ejemplo:</strong></span></p><ul class="prose-bullet-list"><li><p><span style="font-family: Satoshi, sans-serif;">Ve al panel de reuniones y selecciona una reunión grabada de la lista. El video aparecerá a la derecha y la transcripción a la izquierda.</span></p></li></ul><h2><span style="font-family: Satoshi, sans-serif;"><strong><br></strong></span><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>3. Resumir y extraer puntos clave</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Grain no solo graba tus reuniones, sino que también genera un resumen conciso y enumera los puntos clave de discusión junto con los pasos a seguir. Esta función te ahorra tiempo, permitiéndote revisar y actuar rápidamente sobre los aspectos importantes de tus reuniones.</span></p><p><span style="font-family: Satoshi, sans-serif;">Puede personalizar el formato de su resumen eligiendo entre plantillas, como "Descubrimiento de ventas", para obtener una descripción general centrada en los resultados y adaptada a sus necesidades.</span></p><img class="prose-image" src="/api/lesson-resources/c9662242-422a-4fef-8f0c-044b701c8924/image-1756770983174-n3h52k.jpg"><h2><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>4. Integración con su CRM y otras herramientas</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Una de las características destacadas de Grain es su perfecta integración con CRM como Salesforce, HubSpot y herramientas de comunicación como Slack. Después de una reunión, puedes enviar resúmenes, puntos clave y acciones a tomar directamente a tu CRM o Slack para facilitar el seguimiento.</span></p><p><span style="font-family: Satoshi, sans-serif;">Después de revisar su reunión, haga clic en el botón "Enviar a CRM" para enviar automáticamente la información relevante a su CRM, garantizando así que se realice un seguimiento de todos los elementos de acción.</span></p><img class="prose-image" src="/api/lesson-resources/446e338e-9342-41f2-9175-cfe2cafcc4c6/image-1756771172945-fvx8s6.jpg"><h2><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>5. Administrar las grabaciones de sus reuniones</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Si te quedas sin espacio libre para reuniones, ¡no te preocupes! Grain te permite eliminar reuniones antiguas para liberar espacio para nuevas. Simplemente descarga las reuniones antiguas y elimínelas de tu panel para desbloquear más espacio de grabación.</span></p><h2><span style="font-family: Satoshi, sans-serif;"><strong><br></strong></span><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>6. Maximizar las características del grano</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Además de la grabación y el resumen básicos, Grain ofrece funciones adicionales como cambiar el idioma de la transcripción, compartir grabaciones con los miembros del equipo y configurar estilos de resumen específicos.<br><br>Estas opciones ofrecen flexibilidad y garantizan que aproveches al máximo cada reunión.</span></p><p><span style="font-family: Satoshi, sans-serif;">Si no puedes asistir a una reunión, deja que Grain te sustituya. Informa a los participantes que permitan el acceso a tu asistente de IA y Grain se encargará del resto, asegurándote de que no te pierdas nada.</span></p><p><span style="font-family: Satoshi, sans-serif;"><strong>Consejo útil:&nbsp;</strong> una vez que alcance el umbral de 20 reuniones gratuitas, descargue las grabaciones antiguas y elimínelas para crear espacio para nuevas reuniones.&nbsp;</span></p><p><span style="font-family: Satoshi, sans-serif;"><strong>Esto es lo que has aprendido.</strong><br>Ahora comprendes la necesidad de un asistente de reuniones con IA, los diferentes tipos y cómo usarlo eficazmente. A continuación, optimizamos tu calendario con ChatGPT.</span></p>', 18, '2025-09-01 23:21:09.785823', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-01 23:21:09.785823', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('5775a185-27fb-4ac7-8d88-10b79d55ddd4', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'La fórmula del prompt ideal de 6 pasos', NULL, '<p>Para obtener respuestas de IA mejores y más consistentes, es fundamental usar un mensaje bien pensado y estructurado. En este tutorial, aprenderá una fórmula sencilla para obtener los mejores resultados de ChatGPT de forma consistente.</p><p><strong>Lo que aprenderás:</strong></p><ul class="prose-bullet-list"><li><p>La fórmula de 6 pasos para obtener respuestas precisas, relevantes y de alta calidad de ChatGPT.</p></li></ul><img class="prose-image" src="/api/lesson-resources/5ffe7911-aebd-4916-b5de-5ac9797c5c0f/image-1756755091154-3vrqe.jpg"><p><strong>La fórmula de los 6 pasos</strong></p><p>ChatGPT puede ser impredecible: si bien a veces puede brindarte el resultado exacto que deseas, otras veces te brinda respuestas genéricas que suenan como de IA.</p><p>Esta es la fórmula que debes usar al escribir tus indicaciones para obtener los mejores resultados posibles de ChatGPT.</p><ul class="prose-bullet-list"><li><p>En primer lugar, es importante tener en cuenta que algunos pasos son más importantes que otros. Centrarse en los pasos más importantes debe ser una prioridad.</p></li></ul><img class="prose-image" src="/api/lesson-resources/e54a3d6d-6e7f-46d9-a82a-6be9483b110b/image-1756755198216-ccj597.jpg"><ul class="prose-bullet-list"><li><p>Al crear su mensaje, trate estos pasos como una lista de verificación, en orden de importancia.</p></li></ul><h3><strong>1. Tarea</strong></h3><p>La tarea es el corazón de su mensaje y le dice a ChatGPT lo que desea que haga.</p><ul class="prose-bullet-list"><li><p>Para obtener resultados óptimos, comience siempre con un verbo de acción como "generar", "escribir" o "analizar", etc.</p></li><li><p>Define claramente tu objetivo final, ya sea una simple solicitud o una instrucción compleja de varios pasos.</p></li></ul><p>Ejemplos:</p><p><em>Simple:</em></p><p><em>“Generar un programa de dieta de tres meses”.</em></p><p><em>Complejo:</em></p><p><em>Analice los comentarios de los usuarios de mi boletín informativo, resuma las 3 conclusiones principales, centrándose en la mejora, y clasifique el resto según su importancia.</em></p><img class="prose-image" src="/api/lesson-resources/fbb30b4f-668b-4ea9-9f3f-0cfcb142071a/image-1756755207632-b69hh8.jpg"><h3><strong>2. Context</strong></h3><p>El contexto proporciona a ChatGPT la información relevante para optimizar los resultados. Proporcionar el mayor contexto posible ayudará a ChatGPT a comprenderte mejor a ti y a tus necesidades.</p><ul class="prose-bullet-list"><li><p>Estas tres preguntas pueden ayudarle a orientarse sobre qué contexto específico proporcionar a ChatGPT:</p></li></ul><ol class="prose-ordered-list"><li><p>¿Cuáles son los antecedentes del usuario <strong>?</strong></p></li><li><p>¿Cómo se ve <strong>el éxito</strong> ?</p></li><li><p>¿En qué <strong>entorno</strong> se encuentran?</p></li></ol><p></p><p><em>Ejemplo:</em></p><p><em>Soy un hombre de 113 kg que busca perder 9 kg de grasa en tres meses. Solo tengo tiempo para cocinar una vez a la semana, dos horas los domingos. Necesito un programa de dieta de tres meses para ayudarme.</em></p><img class="prose-image" src="/api/lesson-resources/f6a436d8-1d3b-4974-97ef-14b5990eb0ad/image-1756755218584-9g4vv8j.jpg"><p><strong>3. Ejemplos</strong></p><p>Los ejemplos son frameworks que permiten a ChatGPT estructurar mejor los resultados. Permiten a ChatGPT imitar el estilo, la estructura y el tono de prácticamente cualquier cosa.</p><p>Las investigaciones muestran que incluir ejemplos en las indicaciones puede mejorar significativamente la calidad del resultado y evitar que suene genérico como "ChatGPT".</p><p><strong><em>Ejemplo:</em></strong></p><p><em>“Usted es un gerente de contratación en un equipo de marketing responsable de redactar la descripción del puesto para una vacante de gerente de marketing.</em></p><p><em>Su equipo se centra principalmente en aumentar el conocimiento de la marca de la plataforma publicitaria de Netflix para adquirir nuevos socios.</em></p><p><em>Redacte la descripción del puesto utilizando el formato de esta descripción de puesto existente a continuación: [pegar ejemplo]”.</em></p><ul class="prose-bullet-list"><li><p>Desde aquí, puedes pegar la descripción de una oferta de trabajo de LinkedIn cuyo tono, estructura, estilo y encabezados te hayan gustado. ChatGPT hará su trabajo e imitará la redacción de la oferta, pero usando tu contexto.</p></li></ul><p><strong>Nota:&nbsp;</strong> No son <em>&nbsp;necesarios</em> para cada indicación, pero incluir un ejemplo relevante mejora drásticamente la calidad del resultado.</p><img class="prose-image" src="/api/lesson-resources/a7febbdb-032f-402d-9edf-c69e5ff9d92d/image-1756755229465-tgnk0o.jpg"><p><strong>4. Persona</strong></p><p>Persona consiste en representar un personaje o experiencia específica en ChatGPT. Imagina tener acceso instantáneo a un experto relevante para tu tarea.</p><p>Este paso es menos importante en la fórmula de 6 pasos, pero es una poderosa técnica de ChatGPT.</p><p><br>Ejemplos:</p><p><em>Para la rehabilitación de lesiones:</em></p><p><em>Eres fisioterapeuta especializado en recuperación de deportistas. Generáme un programa de dos meses que me ayude a recuperarme del codo de tenista.</em></p><p><em>Para quienes buscan empleo:</em></p><p><em>Eres gerente de contratación en una empresa de Fortune 500. Hazme 20 preguntas que me ayudarán a prepararme para mis futuras entrevistas de trabajo.</em></p><p><strong>Consejo profesional:&nbsp;</strong> puedes hacer que ChatGPT responda como personas famosas específicas.</p><p><em>Por ejemplo:</em></p><p><em>“Reescribe esta entrada del blog al estilo de Eminem”.</em></p><img class="prose-image" src="/api/lesson-resources/36edc4b4-fe01-4622-bbbd-00ee81838099/image-1756755239407-aepyw28.jpg"><p><strong>5. Formato</strong></p><p>Visualiza el resultado deseado. Declarar el formato en ChatGPT te ayudará a estructurar tus resultados de forma única.</p><ul class="prose-bullet-list"><li><p>¿Quieres una tabla, viñetas o un párrafo? Indícalo en la solicitud.</p></li></ul><p><br><em>Ejemplo:</em></p><p><em>“He recopilado comentarios de los lectores para mi boletín informativo después de docenas de respuestas para mejorar.</em></p><p><em>Salida en una tabla con encabezados: retroalimentación original, prioridad y nivel de dificultad.</em></p><p><em>Aquí están los comentarios: [pegue los comentarios aquí]”</em></p><p><br>Además de <strong>las tablas</strong> , otros formatos comunes que ChatGPT puede generar sin problemas son <strong>viñetas, formato de correo electrónico, bloques de código, párrafos&nbsp;</strong> y <strong>&nbsp;rebajas.</strong></p><img class="prose-image" src="/api/lesson-resources/fcddeeb5-a235-4382-b50b-fb2c36a2e0a3/image-1756755248470-gjvss.jpg"><p><strong>6. Tono</strong></p><p>El tono establece el estado de ánimo de la salida.</p><ul class="prose-bullet-list"><li><p>Especifique si desea un resultado informal, formal, ingenioso o entusiasta.</p></li></ul><p><br>A veces, puede ser difícil describir el tono específico que quieres incluir. Pero no te preocupes, hay una guía si también te quedas atascado.</p><ul class="prose-bullet-list"><li><p>Para obtener el tono perfecto para tu mensaje, simplemente describe tus sentimientos:</p></li></ul><p><em>Ejemplo:</em></p><p><em>Estoy redactando un correo electrónico para un equipo nuevo. Quiero sonar profesional, pero sin ser demasiado formal. Sugiéranme cinco tonos que pueda usar para mi borrador.</em></p><ul class="prose-bullet-list"><li><p>Ahora, selecciona tu tono favorito de la lista e ingrésalo en tu mensaje completo.</p></li></ul><p><br><em>Ejemplos:</em></p><p>“<br><em>Utilice un tono de voz informal</em></p><p><em>Utilice un tono de voz formal</em></p><p><em>Dame una salida ingeniosa</em></p><p><em>Mostrar entusiasmo</em></p><p><em>Suena pesimista</em><br>”</p><img class="prose-image" src="/api/lesson-resources/8fa89dc4-538d-48ee-988c-ef94d32f4e58/image-1756755255776-t58sl.jpg"><p>¡Listo! Ahora puedes llevar tus mensajes de ChatGPT al siguiente nivel y mejorar la calidad y precisión de sus resultados.</p><p><strong>Consejo:&nbsp;</strong> Da órdenes a la IA con palabras clave como "dar", "crear" o "investigar". No le hagas preguntas como "¿Puedes...?". Por último, recuerda decir "por favor" y "gracias".</p><p><strong>Esto es lo que has aprendido:</strong><a target="_blank" rel="noopener noreferrer" class="prose-link" href="http://learned.now/"><strong><br></strong></a>ahora que comprendes el marco de solicitud básico, pero efectivo, para garantizar respuestas precisas, pasemos a mostrarte cómo crear tus propias instrucciones ChatGPT personalizadas para casos de uso específicos.</p>', 13, '2025-09-01 16:43:14.762102', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-01 16:43:14.762102', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('c2a01bc7-01c2-42d9-adde-307fcf6b019f', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Competidor principal a la vista: guía para principiantes sobre Claude', NULL, '<p>Ahora ya sabes qué es ChatGPT. Sabemos que un gran progreso conlleva competencia. Veamos algunos de los principales competidores de ChatGPT.&nbsp;</p><p>Actualmente, la contraparte más formidable es Claude de Anthropic.</p><p>En esta lección, le explicaremos los conceptos básicos del uso de Claude, qué es, cómo acceder a él y cómo aprovechar al máximo sus funciones.&nbsp;</p><p>Al final podrás decidir si vale la pena invertir en actualizar a Claude Pro.</p><p>¡Vamos!</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-33.png" alt="imagen-33.png" width="800" height="480"><p></p><h3><strong>¿Por qué elegir Claude?</strong></h3><p>Claude se destaca en varias áreas, particularmente en lo que respecta a redacción publicitaria, imitación de diversos estilos de escritura y producción de contenido original.&nbsp;</p><p>Una de sus características destacadas es Artifacts, que permite implementar el proyecto en tiempo real mientras se programa, una ventaja increíble para los desarrolladores. De hecho, muchos programadores están combinando Claude Sonnet 4.0 con Cursor AI para revolucionar la forma en que escriben código usando lenguaje natural.</p><p>A continuación te explicamos cómo empezar con Claude:</p><p>Visita <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://Claude.ai"><strong>Claude.ai</strong></a> para empezar. Crea una cuenta o inicia sesión con Google. Una vez iniciada la sesión, estarás listo para empezar a generar contenido.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/Screenshot%202025-08-07%20at%202.03.54%E2%80%AFPM.png" alt="Captura de pantalla del 7 de agosto de 2025 a las 14:03.54.png" width="754" height="520"><p></p><p><em>Nota: La versión gratuita tiene un uso limitado. Veamos si vale la pena actualizar a Claude Pro.</em></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-35.png" alt="imagen-35.png" width="800" height="480"><p></p><h2><strong>El resumen de Claude Pro: cómo sacarle el máximo partido</strong></h2><p>En esta sección, exploraremos las características principales de Claude Pro y te ayudaremos a decidir si vale la pena actualizarlo por $20. Cubriremos el análisis de documentos, la lectura de imágenes y compararemos Claude con modelos como el GPT-4o.</p><img class="prose-image" src="/api/lesson-resources/1c42a773-a084-49aa-9a96-cf1e782a0d9b/image-1756742652335-5rw3uo.jpg"><img class="prose-image" src="data:image/svg+xml;base64,"><h3><strong>1. Introducción a Claude Pro</strong></h3><p>Para actualizar a Claude Pro, ve a la configuración de tu cuenta. Encontrarás tres pestañas principales:</p><ul class="prose-bullet-list"><li><p>Información del usuario: Su perfil y preferencias.</p></li><li><p>Facturación: Donde puedes suscribirte al plan Pro por CA$24/mes (facturado anualmente).</p></li><li><p>Uso de la nube: supervisa el uso y el historial de sesiones.</p></li></ul><p>Claude Pro ofrece varios beneficios clave:</p><ul class="prose-bullet-list"><li><p>Mayor uso en comparación con el plan gratuito</p></li><li><p>Accede a Claude Code en tu terminal</p></li><li><p>Proyectos ilimitados para organizar chats y documentos</p></li><li><p>Capacidades de investigación</p></li><li><p>Integración con Google Workspace (correo electrónico, calendario, documentos)</p></li><li><p>Pensamiento extendido para trabajos complejos</p></li><li><p>Uso de más modelos de Claude, incluido Claude 3.5 Sonnet</p></li><li><p>Conecte herramientas de terceros a través de integraciones MCP remotas</p></li></ul><h3><strong>2. Características principales y limitaciones de Claude Pro</strong></h3><ul class="prose-bullet-list"><li><p>Sin generación de imágenes: A diferencia del DALL-E de GPT-4o, Claude no puede generar imágenes. Si le pides que cree una imagen, te explicará que no puede.</p></li><li><p>Selección de modelo: Claude Pro permite cambiar entre versiones como Claude 4.1 Opus, Sonnet o Haiku. Para obtener los mejores resultados, utilice Claude 4 Sonnet, cuyo rendimiento es similar al de GPT-4.</p></li><li><p>Sin navegación por Internet: Claude no puede navegar por la web ni buscar información en línea como otros modelos.</p></li><li><p>Artefactos: Claude 4 Sonnet ofrece un espacio de trabajo para ver, editar y crear contenido de IA en tiempo real, lo que facilita su integración en proyectos.</p></li></ul><h3><strong>3. Carga y análisis de archivos</strong></h3><p>Una de las características destacadas de Claude Pro es su capacidad para analizar imágenes y documentos:</p><ul class="prose-bullet-list"><li><p>Reconocimiento de imágenes: Claude puede analizar fotos y describir su contenido. Por ejemplo, si subes la foto de un perro, Claude la describirá junto con su entorno, lo cual resulta útil para extraer datos de contenido visual como facturas o notas.</p></li><li><p>Análisis de PDF y documentos: Sube archivos PDF para que Claude los analice. Por ejemplo, sube un trabajo de investigación y Claude extraerá estadísticas, resúmenes o datos clave.</p></li><li><p>Análisis de Excel: Claude no puede leer archivos de Excel directamente, pero sí analizar capturas de pantalla. Sube una captura de pantalla y Claude te ayudará a extraer y calcular datos como comparaciones de precios de productos.</p></li></ul><h3><strong><br>4. Escritura, codificación y más</strong></h3><p>Claude ayuda a redactar correos electrónicos, informes y generar código, lo que facilita tareas como redactar artículos, correos electrónicos o codificar un sitio web.</p><h3><strong>5. ¿Vale la pena actualizar a Claude Pro por $20 al mes?</strong></h3><p>Claude Pro es ideal para el análisis de documentos y la extracción de datos por $20 al mes. Pero si necesitas generar imágenes o navegar por la web, GPT-4o podría ser una mejor opción.</p><p><strong>Consejo:&nbsp;</strong> Claude destaca por su escritura con un tono casi humano, lo que lo hace perfecto para trabajos editoriales o de escritura creativa. Pruébalo en tu próximo proyecto de escritura.</p><p><strong>Aprendió&nbsp;</strong> las diferencias clave entre Claude y ChatGPT, exploró sus fortalezas y descubrió cómo comenzar.&nbsp;</p><p>¿Listo para avanzar? Aprendamos más sobre el programa estrella de Google, LLM: Gemini, en la siguiente lección.</p>', 9, '2025-09-01 15:01:12.021172', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-01 15:01:12.021172', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('c38efbf5-149e-4c77-aa80-6e25ee8141b3', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Esto es lo que ganarás', NULL, '<h2><strong>Bienvenido a tu paquete de inicio de IA definitivo</strong></h2><p>Antes de comenzar con el Kit de inicio de IA, no olvides acceder a todos los recursos adicionales gratuitos descargándolos en la lección "Usa IA para ahorrar tiempo y vivir mejor".</p><p>Encontrarás nuestro:</p><ul class="prose-bullet-list"><li><p>Guía de indicaciones de Expert ChatGPT</p></li><li><p>Hojas de referencia sobre terminología esencial de IA</p></li><li><p>Lista de verificación para el uso responsable de la IA</p></li><li><p>Certificación de herramientas de IA en el trabajo (disponible al finalizar el curso)</p></li></ul><p>¡Después de continuar y descargar esos recursos, comencemos a trabajar!</p><p></p><p>Si has estado sintiendo el revuelo en torno a la IA y el miedo a perderse algo (FOMO) que conlleva, estás en el lugar correcto. Quizás hayas probado algunas herramientas, pero aún te preguntas:</p><p>¿Qué es exactamente la IA? ¿Qué hace? Y, lo más importante, ¿cómo transformará tu vida, desde hoy y en el futuro?</p><h3><strong>Esta es la realidad:</strong></h3><p>La IA es la tecnología más transformadora que los seres humanos hayamos creado jamás, y cada vez está mejor.</p><p>En este momento, estamos presenciando la <em>peor</em> versión de IA que jamás veremos, lo que significa que la oportunidad de salir adelante es enorme.</p><p>¿Evitar la IA? No es una opción. Ya sea en tu trabajo, tu negocio o tu vida personal, la IA está a punto de convertirse en tu mejor aliada, o en tu mayor competidor.</p><p>En 2030, el panorama empresarial se dividirá en dos grupos:</p><ul class="prose-bullet-list"><li><p><strong>Empresas que adoptaron la IA</strong></p></li><li><p><strong>Negocios que ya no existen</strong></p></li></ul><p>Es así de simple.</p><h3><strong>Pero aquí están las buenas noticias:</strong></h3><p>No necesitas profundizar en los tecnicismos del entrenamiento ni del ajuste de modelos de IA. Tu misión es simple: aprender lo que la IA puede hacer y cómo usarla para alcanzar tus objetivos diarios.</p><p>Ya sea que te lleve unas semanas o unos meses sentirte cómodo con la IA, no te preocupes: estás en el camino correcto y puedes lograrlo.</p><p>Este curso está aquí para ayudarte a superar la brecha de conocimiento con la teoría justa para que te sientas preparado, pero ¿el verdadero enfoque? <strong>Flujos de trabajo prácticos, directos y directos que transformarán tu día a día.</strong></p><p>Aprenderás a:</p><ul class="prose-bullet-list"><li><p>Piensa mejor</p></li><li><p>Trabaje de forma más inteligente</p></li><li><p>Ahorra horas cada semana</p></li><li><p>Producir un trabajo de mayor calidad que resulte más satisfactorio</p></li></ul><img class="prose-image" src="https://lh7-rt.googleusercontent.com/docsz/AD_4nXc6xVCyefETTyh8Ttb_3HcuY0kJfFykRIkkfh2R7Hc5uPfedVlptlKg_CbqD5hmVVGwp-9vpLPK4eTqy1H0iq48KzRBKooac0AeA4kbQ9TWJb0BHKOJzV-jOGOwnCqi0QLmipdV4Q?key=whQNRL_GUd20THdzlF5GZA" width="719" height="479"><p><br><strong>Qué ofrece este curso</strong></p><p>Este curso en video a su propio ritmo está dirigido a quienes se inician en el mundo de la IA y reconocen el valor que esta puede aportar, ayudándoles a trabajar de forma más inteligente y a ahorrar tiempo valioso que puede dedicarse a una mejor calidad de vida.<br><br>Aprenderá los fundamentos de la IA y flujos de trabajo efectivos para ahorrar tiempo, energía y dinero. Aprenderá a identificar y utilizar eficazmente las herramientas de IA más populares en situaciones reales.</p><p>Al finalizar, dominarás valiosas habilidades de IA que te harán más productivo y sentarán las bases para flujos de trabajo más avanzados.</p><p>💡 ¡ <strong>Buenas noticias! No se requiere experiencia previa en inteligencia artificial (IA) ni programación.</strong><br><br><br><strong>Lista de verificación del curso.</strong></p><p>El curso de certificación del kit de inicio de IA de Rundown consta de los siguientes módulos:</p><ol class="prose-ordered-list"><li><p><strong>Fundamentos de IA:&nbsp;</strong><br>Aprenda los conceptos básicos de la IA: qué es, sus tipos y su impacto. También explorará estrategias para integrar la IA y afrontar los retos de su adopción.</p></li><li><p><strong>Fundamentos de los chatbots de IA:</strong><br>Aprende a usar los mejores chatbots de IA, como ChatGPT, para tareas como investigación, redacción y programación. También hablaremos de competidores como Claude, Gemini y opciones de código abierto.</p></li><li><p><strong>Dominando las conversaciones con IA (Prompting):</strong><br>Aprende a crear prompts de IA efectivos. Cubriremos técnicas básicas, una fórmula de seis pasos y estrategias avanzadas. También aprenderás a personalizar ChatGPT y a crear GPT personalizados.</p></li><li><p><strong>Casos de uso esenciales de IA:</strong><br>Practique con flujos de trabajo de IA para tareas del mundo real. Aprenda herramientas como Grain para reuniones, TextBlaze para automatización, Perplexity para investigación, Gamma para presentaciones, MidJourney para imágenes, HeyGen para videos y más, todo con guías prácticas. Y mucho más...</p></li><li><p><strong>Examen de revisión y certificación:</strong><br>Completa los módulos y realiza el examen del Kit de inicio de IA. Aprobéselo para obtener una certificación que podrás compartir en redes sociales y en tu currículum para demostrar tus habilidades en IA.</p></li></ol><p>Al finalizar este curso, contarás con sólidas habilidades para empezar a integrar la IA en tu trabajo diario. Ya sea al escribir, investigar, crear contenido o automatizar tareas, notarás un aumento considerable en tu eficiencia.</p><p>Una vez que tengas una comprensión básica sólida de la IA, aunque el campo avance muy rápido, podrás adaptarte fácilmente ya que estas habilidades te serán útiles tanto ahora como en el futuro.&nbsp;</p><p><strong>¿Listo para mejorar tu IA? ¡Comencemos!</strong></p>', 2, '2025-08-20 22:17:06.894774', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-08-20 22:17:06.894774', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('a46fa556-2a92-4b13-a1b4-c307f24f69fd', 'e432692a-7d0a-4e10-846f-ba57c041e96c', '¿Qué es un chatbot de IA?', NULL, '<p>Desde que se lanzó ChatGPT en noviembre de 2022, los chatbots de IA han transformado la forma en que usamos la tecnología en nuestra vida cotidiana.</p><p>En este módulo, profundizarás en los principales chatbots de IA, empezando por ChatGPT. Al finalizar, sabrás cómo usar estas herramientas para todo, desde la investigación y la escritura hasta la programación.&nbsp;</p><p>También analizaremos otras opciones importantes como Claude y Gemini, junto con algunas excelentes alternativas de código abierto.</p><p>Pasarás de principiante a profesional y dominarás la forma de crear indicaciones que obtengan los mejores resultados con ChatGPT.</p><p><strong>En esta lección, cubriremos:</strong></p><ol class="prose-ordered-list"><li><p>¿Qué es un chatbot de IA?</p></li><li><p>Casos de uso comunes</p></li><li><p>Los chatbots de IA más populares en 2025</p></li><li><p>Pros y contras de cada herramienta</p></li><li><p>Nuestro favorito en todos los aspectos</p></li></ol><p>¡Vamos a empezar!</p><p><strong>¿Qué es un chatbot de IA?</strong></p><p>Un chatbot de IA funciona como un asistente virtual, utilizando inteligencia artificial para mantener conversaciones similares a las humanas y responder a sus preguntas en un lenguaje cotidiano.</p><p><strong>Casos de uso comunes para chatbots de IA</strong></p><img class="prose-image" src="/api/object-proxy/objects/uploads/0fada423-8523-4e7c-bf14-38e026de442a"><ul class="prose-bullet-list"><li><p><strong>Creación de contenido:&nbsp;</strong> redacte artículos académicos, informes o propuestas rápidamente, ahorrando tiempo valioso.</p></li><li><p><strong>Servicio al cliente:&nbsp;</strong> gestione preguntas rutinarias y resolución de problemas, reduciendo la carga de los agentes humanos.</p></li><li><p><strong>Investigación académica:&nbsp;</strong> Resumir estudios, responder consultas especializadas y sugerir nuevas direcciones de investigación.</p></li><li><p><strong>Traducción:&nbsp;</strong> Facilitar la comunicación entre idiomas, traduciendo materiales sin problemas.</p></li><li><p><strong>Asistente personal:&nbsp;</strong> ayuda con la programación, recordatorios y búsqueda de recursos para estudiantes y profesores.</p></li><li><p><strong>Educación:&nbsp;</strong> Actuar como tutores virtuales, ofreciendo aprendizaje interactivo y respondiendo preguntas.</p></li></ul><p><strong>Los chatbots de IA más populares en 2025</strong></p><ol class="prose-ordered-list"><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://chatgpt.com/"><strong>ChatGPT</strong></a> (OpenAI)<strong> :&nbsp;</strong> una IA versátil para generar respuestas similares a las humanas, adecuadas para conversaciones casuales y consultas detalladas.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://gemini.google.com/"><strong>Gemini</strong></a> (Google)<strong> :&nbsp;</strong> ofrece interacciones inteligentes y conscientes del contexto, y se destaca por brindar respuestas precisas al aprovechar los datos de Google.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://claude.ai/"><strong>Claude</strong></a> (Antrópico)<strong> :&nbsp;</strong> Prioriza las consideraciones éticas, proporcionando interacciones de IA seguras y confiables alineadas con los valores humanos.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://perplexity.ai/"><strong>Perplejidad</strong></a><strong> :&nbsp;</strong> se centra en mejorar las funciones del motor de búsqueda, ofreciendo respuestas precisas y completas para una recuperación de información eficiente.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://meta.ai/"><strong>Meta AI</strong></a><strong> :&nbsp;</strong> Meta AI integra información de redes sociales (Facebook, Instagram, WhatsApp) para ofrecer interacciones personalizadas y atractivas. Utiliza la información de las redes sociales para ofrecer interacciones personalizadas y atractivas, mejorando la experiencia del usuario con respuestas personalizadas.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://copilot.microsoft.com/"><strong>Microsoft Copilot</strong></a><strong> :&nbsp;</strong> integrado en los productos de Microsoft, aumenta la productividad al ayudar con tareas como la creación y codificación de documentos.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://grok-ai.app/"><strong>Grok</strong></a><strong> :&nbsp;</strong> Grok, un chatbot con IA de xAI de Elon Musk. Optimiza las conversaciones en redes sociales en X, ofreciendo interacciones dinámicas basadas en IA.</p></li></ol><p><br><strong>Ventajas y desventajas de los chatbots de IA</strong></p><img class="prose-image" src="/api/object-proxy/objects/uploads/6a655e5d-43a3-4f29-be89-8be3388e8864"><img class="prose-image" src="/api/object-proxy/objects/uploads/4a36213e-a45f-4a2b-8225-9b47163ed446"><h2><strong>Así es como se ve la interfaz de usuario:&nbsp;</strong></h2><p>De izquierda a derecha: ChatGPT - Claude - Géminis</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-19.png" alt="imagen-19.png" width="1668" height="600"><p></p><h3><strong>Nuestro chatbot de IA favorito</strong></h3><p>Nuestra mejor opción para un chatbot de IA versátil es <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://chatgpt.com/"><strong>ChatGPT</strong></a> . Pero, ¿por qué?, te preguntarás.</p><p>ChatGPT destaca por su:</p><ul class="prose-bullet-list"><li><p><strong>Versatilidad</strong> : puede gestionar una amplia gama de tareas, desde escritura creativa hasta asistencia en la codificación.</p></li><li><p><strong>Mejoras constantes</strong> : OpenAI actualiza periódicamente el modelo, lo que garantiza que siempre trabaje con tecnología de vanguardia.</p></li><li><p><strong>Ecosistema sólido</strong> : con GPT personalizados y una comunidad próspera, siempre hay algo nuevo para explorar y aprender.</p></li></ul><p><strong>Aquí te explicamos cómo puedes acceder:&nbsp;</strong></p><p><strong>a. Acceder a ChatGPT</strong></p><p>Para acceder a ChatGPT, visita <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://chatgpt.com"><strong>https://chatgpt.com</strong></a> . Es <em>completamente gratuito</em> y no necesitas crear una cuenta, aunque se recomienda para acceder a tu historial de chat o a <strong>tus GPT personalizados</strong> .</p><ul class="prose-bullet-list"><li><p><em>Registrarse es fácil y puedes elegir entre diferentes planes según tus necesidades.</em></p></li></ul><p><strong>b. Cómo utilizar la interfaz de usuario principal</strong></p><ul class="prose-bullet-list"><li><p><strong>Iniciar sesión:</strong> Acceda a ChatGPT e inicie sesión con sus credenciales.</p></li><li><p><strong>Panel principal:</strong> Familiarízate con la interfaz. El panel es <em>intuitivo</em> y ofrece opciones para iniciar una nueva conversación, acceder a chats anteriores y ajustar la configuración.</p></li><li><p><strong>Iniciar una conversación:</strong> Inicia un nuevo chat ingresando tu mensaje en el campo " <em>Mensaje ChatGPT</em> ". ChatGPT responde en tiempo real, generando texto con un sonido similar al de una persona según lo que escribas.</p></li></ul><p>ChatGPT puede proporcionar referencias de fuentes si se solicita. Utilice esta función incluyendo una pregunta cómo "¿Me puedes recomendar algunas ciudades japonesas que merezcan la pena visitar en verano<em>?</em> " .</p><p><strong>Consejo útil:&nbsp;</strong> esta <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://chathub.gg/"><strong>herramienta</strong></a> le permite ejecutar todos estos LLM al mismo tiempo para comparar el resultado.&nbsp;</p><img class="prose-image" src="/api/object-proxy/objects/uploads/ea510213-9502-402f-98c7-982c753924b0"><p><strong>Esto es lo que has aprendido.</strong><br>Ahora que comprendes los diferentes tipos de chatbots populares, veamos cómo se compara cada uno con ChatGPT y sus respectivas fortalezas.</p>', 7, '2025-08-24 15:02:17.091473', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-08-24 15:02:17.091473', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('2d1918be-4711-46af-a764-175e3957bc5d', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Utilice la IA para ahorrar tiempo y vivir mejor', NULL, '<p>Comprender cómo funciona la IA y usarla a diario son dos desafíos diferentes. Pero cuanto más la comprendemos, más fácil resulta ponerla en práctica.</p><p>Esto nos acerca a nuestro objetivo principal: utilizar la IA para ahorrar tiempo y mejorar nuestra vida diaria.</p><p>Por supuesto, incluso con un enfoque sólido, todavía habrá desafíos que tendremos que superar.</p><p>En esta lección, abordaremos algunos desafíos comunes del uso de IA en sus tareas diarias, exploraremos cómo crear un flujo de trabajo de IA fluido y veremos ejemplos reales de IA en acción.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Desafíos de la incorporación de IA</p></li><li><p>Cree un flujo de trabajo de IA eficaz</p></li><li><p>Un enfoque estructurado para aprender herramientas de IA</p></li></ul><p>¡Vamos!</p><p><strong>Desafíos de la integración de la IA</strong></p><p>Hay varias razones por las que las personas podrían dudar en adoptar herramientas de IA, entre ellas:</p><ul class="prose-bullet-list"><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://www.digitalsmiles.tv/marketersoverwhelmedbyaiintegration3a7025surveyed"><strong>Abrumado</strong></a> por las nuevas herramientas de IA</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://www.bbc.com/worklife/article/20230418-ai-anxiety-artificial-intelligence-replace-jobs"><strong>Ansiedad</strong></a> por la seguridad laboral a medida que mejora la IA</p></li><li><p>Justificar los costos <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://itrexgroup.com/blog/how-much-does-artificial-intelligence-cost/"><strong>financieros</strong></a> de implementar la IA</p></li><li><p>Dando sentido al complejo panorama de <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://www.whitecase.com/insight-our-thinking/ai-watch-global-regulatory-tracker-united-states"><strong>las regulaciones de la IA</strong></a></p></li><li><p>Preocupaciones válidas sobre la privacidad y protección <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://demistifai.com/the-ethical-implications-of-ai-what-are-the-ethical-considerations-when-developing-and-deploying-ai-systems/"><strong>de datos con IA</strong></a></p></li><li><p>Conceptos erróneos y prejuicios generalizados contra la IA en general</p></li></ul><p>Por eso nuestra misión es ayudar a promover la comprensión de la IA, para que las personas tengan menos miedo de probar e implementar herramientas de IA.</p><p>Un buen consejo para superar estos desafíos en la adopción de la IA es experimentar con las herramientas y flujos de trabajo de IA más populares utilizando datos no confidenciales.<br><br>Una vez que vea los beneficios, se convencerá y su hábito de integrar la IA se fortalecerá.</p><h3><strong>Estrategia para superar estos desafíos:</strong></h3><ul class="prose-bullet-list"><li><p><strong>Aprenda de los casos de uso de la competencia</strong> : si los competidores se benefician de la IA, utilice esos mismos flujos de trabajo en su empresa.&nbsp;</p></li><li><p><strong>Comience cada proyecto como piloto</strong> : cree un entorno de pruebas de bajo riesgo para cada proyecto de IA.&nbsp;</p></li><li><p><strong>Demuestre a sus colegas flujos de trabajo de IA probados</strong> : una vez que un flujo de trabajo muestre resultados, compártalo con sus colegas y obtenga comentarios.&nbsp;</p></li><li><p><strong>Determinar un ROI positivo</strong> : compare los resultados del flujo de trabajo de IA con el tradicional y determine si vale la pena adoptarlo.&nbsp;</p></li></ul><h3><strong>Construyendo un flujo de trabajo de IA eficaz:</strong></h3><p>La solución es crear un flujo de trabajo de IA estructurado que integre perfectamente las herramientas de IA en su rutina diaria.</p><img class="prose-image" src="/api/object-proxy/objects/uploads/d218545d-786d-4e92-960c-8ac1465e581c"><ul class="prose-bullet-list"><li><p><strong>Planifica tu rutina:</strong> Comienza detallando tus tareas diarias y semanales, incluyendo reuniones y otros compromisos. Esto te ayudará a identificar dónde la IA puede ser más beneficiosa.</p></li><li><p><strong>Identifique oportunidades de IA:</strong> busque tareas en las que la IA pueda mejorar la eficiencia o la calidad, como la programación, la creación de contenido o el análisis de datos.</p></li><li><p><strong>Integración del plan:</strong> utilice las herramientas de IA identificadas en lecciones anteriores y planifique cómo incorporar cada una a su rutina.</p></li><li><p><strong>Cree un diagrama de flujo de trabajo visual:</strong> desarrolle una representación visual de su nuevo flujo de trabajo para que sea fácil de seguir y optimizar.</p></li></ul><p><br>Siguiendo estos pasos, las herramientas de IA se pueden integrar perfectamente en las rutinas diarias, transformándolas de usos aislados y esporádicos en soluciones integradas que mejoran la productividad y agilizan los flujos de trabajo.</p><p><strong>Para ver cómo funciona esto en la práctica, considere los siguientes ejemplos:</strong></p><p><strong>Gerente de Marketing</strong></p><p>Automatiza la programación de contenido y el análisis de datos con IA, liberando horas cada semana para la estrategia y la creatividad.</p><p><strong>Propietario de una pequeña empresa</strong></p><p>Mejora el servicio al cliente utilizando chatbots de IA y herramientas de datos para marketing personalizado, lo que genera clientes más felices y mayores ventas.</p><p><strong>Profesional sanitario</strong></p><p>Utiliza IA para analizar rápidamente imágenes médicas, mejorando la precisión del diagnóstico y acelerando los planes de tratamiento personalizados.</p><p><strong>Gerente de la cadena de suministro</strong></p><p>Aprovecha la IA para pronosticar con precisión la demanda, optimizar el inventario, reducir el desperdicio y mantener la disponibilidad de los productos.</p><p><strong>Analista financiero</strong></p><p>Emplea IA para analizar datos, descubrir oportunidades de inversión y tomar decisiones informadas, mejorando el rendimiento de la cartera.</p><p><strong>Consejo clave</strong> : Crea un piloto para probar nuevos proyectos de IA en tu empresa. Cuando los resultados muestren una mejora en la eficiencia, compártelos con tus compañeros y superiores, y aplícalos en pilotos de prueba más amplios.<br><br><strong>Esto es lo que has aprendido.</strong><br>Ahora que comprendes los diferentes desafíos que presenta la adopción de la IA y tienes un enfoque claro para abordarlos, profundicemos en los modelos reales que impulsan nuestras aplicaciones de IA generativa.</p>', 6, '2025-08-21 13:49:46.154826', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-08-21 13:49:46.154826', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('0b2a3e56-9aa3-46dd-8259-a73105382066', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Líderes en Open Source o código abierto', NULL, '<p>Los modelos de código cerrado son potentes, pero muchos usuarios dudan por cuestiones de seguridad. Buscan mayor transparencia, control de datos y personalización, lo que los lleva a explorar opciones de código abierto.</p><p>La comunidad de código abierto ha respondido ofreciendo modelos de lenguaje potentes con bases de código a las que cualquiera puede acceder y modificar.&nbsp;</p><p>El código abierto ofrece a los usuarios más control y flexibilidad para adaptar las herramientas a sus necesidades.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Beneficios del código abierto</p></li><li><p>Llama 4 de Meta</p></li><li><p>Mistral Medium 3 de Mistral</p></li></ul><p>¡Vamos!</p><h3><strong>Principales beneficios de los LLM de código abierto:</strong></h3><ul class="prose-bullet-list"><li><p><strong>Personalización</strong> : modifique y ajuste los modelos para adaptarlos a necesidades o aplicaciones específicas.</p></li><li><p><strong>Seguridad</strong> : Mantenga el control total sobre sus datos e infraestructura.</p></li><li><p><strong>Innovación comunitaria</strong> : benefíciese de las mejoras continuas y los avances compartidos por una comunidad global.</p></li></ul><h3><strong>LLM líderes en código abierto</strong></h3><p><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://www.llama.com/"><strong>Llama</strong></a><strong> de Meta&nbsp; 4</strong></p><p>Meta (anteriormente Facebook) se ha convertido en un referente en la investigación de IA gracias a su laboratorio, FAIR. Desarrollaron modelos avanzados como&nbsp; <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://www.llama.com/"><strong>Llama 4</strong></a> , diseñados para ser versátiles. A diferencia de otros gigantes tecnológicos como OpenAI y Anthropic, Meta adopta el código abierto, poniendo sus modelos a disposición del público.</p><p>Parámetros: Scout (17&nbsp;000 millones de parámetros activos, 109&nbsp;000 millones en total), Maverick (17&nbsp;000 millones de parámetros activos, 400&nbsp;000 millones en total), con el futuro Behemoth (288&nbsp;000 millones de activos/~2&nbsp;000 millones en total) aún en formación.</p><ul class="prose-bullet-list"><li><p>Ventana de contexto: Scout ofrece una ventana de alrededor de 10 millones de tokens; Maverick admite hasta 1 millón de tokens</p></li><li><p>Mejor caso de uso: Tareas de razonamiento de entrada de texto e imágenes multimodales, asistentes conversacionales de contexto largo y generación multimodal eficiente</p></li></ul><p>Para acceder a Llama 4, visita <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://Meta.ai">Meta.ai</a>, inicia sesión y comienza seleccionando "Pregúntale cualquier cosa a Meta AI".</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-39.png" alt="imagen-39.png" width="800" height="480"><p></p><p><strong>Mistral </strong><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://docs.mistral.ai/getting-started/models/models_overview/#premier-models"><strong>Medium 3</strong></a></p><p>Mistral, empresa de inteligencia artificial con sede en París, está captando la atención por sus modelos especializados de alto rendimiento, conocidos por su precisión y razonamiento avanzado. Una ronda de financiación de 600 millones de euros en junio de 2024 ha impulsado su crecimiento, pero aún se enfrentan a una dura competencia de los gigantes tecnológicos estadounidenses centrados en modelos de propósito general.</p><p>Parámetros: Mistral Medium 3 (tamaño exacto no revelado, pero ubicado entre Pequeño y Grande)</p><ul class="prose-bullet-list"><li><p>Ventana de contexto: No se indica oficialmente, pero se alinea con la tendencia de Mistral hacia contextos grandes: Small 3.1 ofrece 128 000 tokens</p></li><li><p>Mejor caso de uso: Tareas de propósito general que requieren un alto rendimiento de razonamiento y valor; sólido rendimiento de API a un costo competitivo: “igual o superior al 90 %” de Claude Sonnet 3.7</p></li></ul><p>Para probar Mistral <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://docs.mistral.ai/getting-started/models/models_overview/#premier-models"><strong>Medium 3</strong></a> , visita&nbsp; <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://mistral.ai"><strong>mistral.ai</strong></a> , inicia sesión con tu cuenta de Google o correo electrónico y selecciona "Probar Le Chat". Elige el modelo "Large 2" y empieza a explorar sus capacidades.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-40.png" alt="imagen-40.png" width="800" height="480"><p></p><p><strong>Consejo</strong> : Para velocidades de inferencia ultrarrápidas, visita <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://Groq.com"><strong>Groq.com</strong></a> . La velocidad de inferencia es el tiempo que transcurre entre el envío de tu solicitud y la entrega del resultado por parte de la IA. Cuanto más rápida sea la entrega del resultado por parte de la IA, mayor será la velocidad de inferencia. Su infraestructura garantiza resultados ultrarrápidos.</p><p><strong>Lo que has aprendido</strong><br>Ahora has explorado el poder de los LLM de código abierto como Llama 4 y Mistral Medium 3, y cómo se puede acceder a ellos.</p>', 11, '2025-09-01 16:09:14.090979', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-01 16:09:14.090979', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('655879d8-98fe-4f79-bbd3-15f5ea1cafa0', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Técnicas avanzadas de incitación', NULL, '<p>La ingeniería rápida es tanto un arte como una ciencia.<br><br>Puede ser sencilla o increíblemente compleja. La clave del éxito reside en cómo se guía la IA.&nbsp;</p><p>En esta lección, aprenderemos las técnicas de solicitud avanzadas que pueden transformar ChatGPT en una herramienta poderosa, ayudándole a lograr resultados más precisos, detallados y útiles.</p><p><strong>Lo que aprenderás:</strong></p><ul class="prose-bullet-list"><li><p>Impulso de cadena de pensamiento</p></li><li><p>Impulso progresivo</p></li><li><p>Formato</p></li><li><p>Impulso emocional</p></li><li><p>Impulsando las mejores prácticas</p></li><li><p>Ejemplos de indicaciones avanzadas</p></li></ul><img class="prose-image" src="/api/lesson-resources/fb872a13-08a4-45dd-a972-67bfb6c576ba/image-1756756345894-twre.jpg"><h3><strong>Impulso de cadena de pensamiento</strong></h3><p>El método CoT utiliza un proceso de razonamiento paso a paso que ayuda a guiar las decisiones y dar forma al resultado final.</p><p>Por ejemplo, si estás orientando a un propietario de un negocio, podrías:</p><ul class="prose-bullet-list"><li><p>Identifique los desafíos específicos que enfrenta la empresa.</p></li><li><p>Incluir perspectivas de diferentes partes interesadas.</p></li><li><p>Asegúrese de que la estrategia esté alineada con los objetivos del departamento.</p></li><li><p>Reflexione sobre el proceso general.</p></li></ul><p>Al guiar a la IA a través de este tipo de proceso reflexivo, la ayuda a reflejar la misma profundidad de razonamiento, lo que hace que este enfoque sea ideal para consultores, estrategas o cualquier persona que resuelva problemas complejos de varios pasos.</p><h3><strong>Impulso progresivo</strong></h3><p>Con la Guía Progresiva, en lugar de sobrecargar la IA con demasiadas preguntas a la vez, se dividen las consultas complejas en indicaciones más pequeñas y conectadas. De esta manera, cada paso recibe la atención necesaria antes de pasar al siguiente.</p><p>Ejemplo: Al crear una estrategia de salida al mercado para una startup:</p><ol class="prose-ordered-list"><li><p>Investigue la posición actual del mercado y los competidores.</p></li><li><p>Identificar los factores clave de entrada a la industria.</p></li><li><p>Segmenta el mercado y define tu Perfil de Cliente Ideal (PCI).</p></li><li><p>Planifique una campaña de lanzamiento que resuene con el PCI.</p></li><li><p>Recopilar comentarios y evaluar el éxito de la campaña.</p></li></ol><p>Este enfoque permite que la IA se centre en una sola pregunta a la vez, basándose en respuestas anteriores para lograr una respuesta más reflexiva y completa.</p><h3><strong>Técnicas de formato</strong></h3><p>Para garantizar que sus resultados sean fáciles de entender y estén bien organizados, aplique los siguientes consejos de formato:</p><ul class="prose-bullet-list"><li><p><strong>Utilice Markdown</strong> : solicite resultados estructurados con encabezados, viñetas o tablas para mayor claridad.</p></li><li><p><strong>Lenguaje sencillo</strong> : Mantenga la respuesta clara y concisa.</p></li><li><p><strong>Formato de tabla</strong> : utilice tablas para salidas con gran cantidad de datos y agregue encabezados para una mejor legibilidad.</p></li><li><p><strong>Elimine lo superfluo</strong> : omita introducciones o conclusiones innecesarias y concéntrese en contenido práctico.</p></li></ul><p><strong>Ejemplo de pregunta:</strong><br><em>"Resuma las ventajas y desventajas de las energías renovables. Utilice un formato de tabla con columnas separadas para cada una </em><strong>" .</strong></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-53.png" alt="imagen-53.png" width="800" height="480"><p></p><h3><strong>Impulso emocional</strong></h3><p>A veces, apelar a las emociones puede mejorar la calidad de la respuesta de la IA. Añadir intereses personales o urgencia puede influir sutilmente en el tono del resultado.</p><p><strong>Ejemplo 1:</strong><br><em>«Si este proyecto tiene éxito, significará mucho para mi carrera. ¿Pueden ayudarme a asegurar que la estrategia sea sólida?»</em></p><p>Si bien la IA no tiene sentimientos, estas frases pueden guiarla para que adopte un tono más reflexivo y considerado.</p><p>Ejemplo 2:<br><em>"Te daré una propina de $200" o "esto es muy importante para mi carrera"&nbsp;</em></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-54.png" alt="imagen-54.png" width="800" height="480"><p></p><h3><strong>Impulsando las mejores prácticas</strong></h3><p><strong>Qué hacer</strong></p><ul class="prose-bullet-list"><li><p>Sea <strong>claro, conciso y específico</strong> con sus indicaciones.</p></li><li><p>Proporcione siempre <strong>contexto y ejemplos</strong> para garantizar que la IA comprenda el alcance.</p></li><li><p><strong>Exprese su objetivo claramente</strong> para ayudar a centrar la respuesta.</p></li><li><p><strong>Asigna un rol</strong> a la IA (por ejemplo, “Eres un experto en marketing”) para dar forma al resultado.</p></li></ul><p><strong>Qué NO HACER</strong></p><ul class="prose-bullet-list"><li><p>No <strong>confíe demasiado en la IA</strong> : verifique siempre si hay alucinaciones o imprecisiones.</p></li><li><p>Evite confiar en datos confidenciales sin <strong>verificar dos veces</strong> los hechos.</p></li><li><p>Abstenerse de utilizar <strong>indicaciones vagas</strong> ; tenga una agenda clara y un plan de lo que quiere.</p></li></ul><p></p><h3><strong>Ejemplos de indicaciones avanzadas</strong></h3><p><strong>Estructura y contenido del mensaje:</strong></p><ul class="prose-bullet-list"><li><p><strong>Restricciones explícitas</strong> : <em>"Resumir el Renacimiento en 50 palabras".</em></p></li><li><p><strong>Restricciones negativas</strong> : <em>"Describe la historia de Y sin mencionar X".</em></p></li><li><p><strong>Preguntas múltiples</strong> : <em>"¿Qué es la fotosíntesis? ¿Cómo afecta al crecimiento de las plantas?"</em></p></li><li><p><strong>Formato especificado</strong> : <em>"Enumere los pasos de la fotosíntesis en viñetas".</em></p></li></ul><p><strong>Técnicas creativas:</strong></p><ul class="prose-bullet-list"><li><p><strong>Juego de rol</strong> : <em>"Imagina que eres un historiador del año 2200. Describe Internet".</em></p></li><li><p><strong>Giro de escenario</strong> : " <em>Imagina un mundo sin tecnología. Ahora, propone tres posibles giros a ese escenario".</em></p></li></ul><p><strong>Exploración y sondeo en profundidad:</strong></p><ul class="prose-bullet-list"><li><p><strong>Encadenamiento de indicaciones</strong> : " <em>Describe el Renacimiento" y luego continúa con "Cuéntame más sobre sus artistas".</em></p></li><li><p><strong>Refinamiento iterativo</strong> : « <em>Explica el sistema solar». Luego, «Ahora concéntrate específicamente en la función del sol».</em></p></li></ul><p><strong>Técnicas estilísticas y creativas:</strong></p><ul class="prose-bullet-list"><li><p><strong>Estilo basado en ejemplos</strong> : " <em>Describe una puesta de sol al estilo de un soneto de Shakespeare".</em></p></li><li><p><strong>Cambio de género</strong> : " <em>Explica Internet en el estilo de una novela de fantasía".</em></p></li></ul><h3><strong>Comportamiento del modelo y análisis avanzado</strong></h3><p><strong>Predicción de tokens:</strong><br><br>Consultar la predicción de la siguiente palabra probable basándose en una frase dada puede ayudarle a comprender mejor cómo funciona el modelo.<br><br><strong>Ejemplo:</strong> " <em>El sol es... [¿qué palabra podría seguir?]</em> "</p><p><strong>Bucles de retroalimentación.</strong><br><br>Tras recibir un resultado, proporcione retroalimentación para mejorar los resultados en las indicaciones posteriores.<br><br><strong>Ejemplo:</strong> " <em>Su última respuesta fue un poco técnica. ¿Podría simplificarla?</em> "</p><p></p><p>Reflexiones finales: Esta guía te explicará todo lo que necesitas saber sobre la ingeniería de avisos, desde los conceptos básicos hasta las técnicas más avanzadas. El secreto para obtener los mejores resultados es seguir probando, perfeccionando y ajustando tu enfoque mientras trabajas con IA.&nbsp;</p><p>Consejo útil: agregue estas técnicas avanzadas a sus instrucciones personalizadas de ChatGPT para obtener resultados consistentemente mejores.</p><p>Ahora que comprende las técnicas de indicaciones avanzadas, ¡pasemos a crear sus propios GPT personalizados para obtener resultados aún más efectivos!</p>', 14, '2025-09-01 19:35:43.966344', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-01 19:35:43.966344', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('028a9a88-65fc-48bf-8145-ff839267fdd1', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'El arte de hablar con la IA', NULL, '<p>Para que la IA haga su magia, necesitas hablar su idioma. Como en cualquier buena conversación, el éxito depende de la claridad. Cuanto mejor sea tu aporte, mejor será el resultado.</p><p>Nuestra forma de hablar con la IA es bastante similar a la de hablar con los humanos. Nos comunicamos mediante <strong>indicaciones</strong> . Se trata de una instrucción o comando específico que le damos a la IA para obtener un resultado específico.</p><h3><strong>Introducción a la incitación</strong></h3><p>En esta lección, aprenderás a crear indicaciones que guíen a la IA para obtener los resultados exactos que buscas. Al dominar los conceptos básicos, podrás convertir respuestas vagas en respuestas precisas y significativas.</p><p><em>¿Alguna vez te preguntaste por qué la IA a veces acierta con tu solicitud y otras no?</em><br><br>El secreto está en cómo la solicitas.</p><p><strong>Esto es lo que cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>¿Qué es un mensaje?</p></li><li><p>Por qué son esenciales los buenos mensajes</p></li><li><p>Cómo crear indicaciones que conduzcan a mejores resultados</p></li></ul><p>Al final, sabrás cómo comunicarte con IA como un profesional y obtener constantemente excelentes respuestas.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-41.png" alt="imagen-41.png" width="1200" height="630"><p></p><h3><strong>¿Qué es un mensaje?</strong></h3><p>Una indicación es la instrucción que le das a un modelo de IA para guiar su respuesta. Piensa en ella como si le dieras instrucciones: solo unas pocas palabras o frases que le indican a la IA exactamente qué tipo de resultado buscas.</p><p>La calidad de la respuesta de la IA depende de la precisión con la que se elabore la instrucción. Una instrucción clara y específica proporciona respuestas precisas y concretas. ¿Una instrucción vaga? No tanto.</p><p>La IA puede generar de todo, desde texto e imágenes hasta vídeo, sonido y más. Esta versatilidad se llama <strong>multimodalidad</strong> , y todo comienza con una consigna bien elaborada.</p><h3><strong>Por qué son importantes las indicaciones</strong></h3><p>Tu mensaje determinará el resultado que te proporcionará la IA. Esta modela la respuesta, haciéndola relevante, coherente y adaptada a tus necesidades.</p><p>El principio “basura que entra = basura que sale” es increíblemente relevante aquí, por lo que es importante dar instrucciones de alta calidad.&nbsp;</p><p>Consideremos estos dos ejemplos:</p><ul class="prose-bullet-list"><li><p><strong>Indicación básica</strong> : " <em>Cuéntame un chiste</em> ".</p><ul class="prose-bullet-list"><li><p>Resultado de IA: "¿Por qué ganó un premio el espantapájaros? ¡Porque destacó en su campo!"</p></li></ul></li></ul><ul class="prose-bullet-list"><li><p><strong>Indicación específica</strong> : " <em>Cuéntame un chiste infantil relacionado con la ciencia</em> " .</p><ul class="prose-bullet-list"><li><p>Resultado de IA: "¿Por qué el libro de física se separó del de matemáticas? ¡Porque lo consideraba demasiado formalista!"</p></li></ul></li></ul><p>Las indicaciones vagas conducen a resultados irrelevantes o inútiles, lo que supone una pérdida de tiempo y frustración. Por otro lado, una indicación bien elaborada te acerca al resultado deseado.</p><p>A continuación, se muestra un ejemplo de una indicación eficaz frente a una ineficaz.<br><br>Esta indicación asigna un rol, proporciona contexto y especifica la tarea y el formato de salida deseado. Finalmente, incluye una restricción.</p><img class="prose-image" src="/api/lesson-resources/12abacd4-c26b-4a0f-84de-505eb0fb413f/image-1756744067813-gxqjys.jpg"><p>He aquí un mensaje ineficaz.</p><img class="prose-image" src="/api/lesson-resources/4a314285-f727-4035-b05c-7768abd24100/image-1756744663744-o7rdzf.jpg"><h3><strong>Vamos a practicar la indicación</strong></h3><p>¡Es hora de poner la teoría en práctica! Compara estas dos propuestas y observa la diferencia de calidad:</p><ul class="prose-bullet-list"><li><p><strong>Indicación básica</strong> : " <em>Cuéntame un chiste</em> ".</p><ul class="prose-bullet-list"><li><p>Resultado de IA: "¿Por qué ganó un premio el espantapájaros? ¡Porque destacó en su campo!"</p></li></ul></li></ul><ul class="prose-bullet-list"><li><p><strong>Indicación específica</strong> : " <em>Cuéntame un chiste infantil relacionado con la ciencia</em> " .</p><ul class="prose-bullet-list"><li><p>Resultado de IA: "¿Por qué el libro de física se separó del de matemáticas? ¡Porque lo consideraba demasiado formalista!"</p></li></ul></li></ul><p>¿Observas cómo la segunda indicación genera una respuesta más relevante y personalizada? <strong>La especificidad</strong> es tu mejor herramienta para perfeccionar los resultados de la IA.</p><p><strong>Consejo útil:</strong> al dar indicaciones, piense en la IA como si fuera un pasante entusiasta: funciona mejor cuando le da instrucciones claras y precisas.</p><p><strong>Lo que has aprendido</strong></p><p>La forma en que formule su mensaje tiene un gran impacto en su resultado. Céntrese en la claridad y la especificidad de sus aportaciones para obtener mejores resultados. Cuanto más contexto proporcione, más precisa y útil será la respuesta.</p><p>Ahora que entiendes cómo funcionan las indicaciones, intenta crear algunas propias. Experimenta con diferentes niveles de detalle y observa cómo afectan las respuestas de la IA.</p><p>¿Listo para el siguiente paso? Pasemos a aprender un marco de incitación eficaz.</p>', 12, '2025-09-01 16:12:53.415091', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-01 16:12:53.415091', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('dd6d73e4-8bff-4fdc-8b28-c762dffb869d', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Aumente su productividad con las mejores herramientas de IA', NULL, '<p><span style="font-family: Satoshi, sans-serif;">Con tantas herramientas de IA disponibles, es fácil sentirse abrumado. En lugar de intentar estar al día con todas, concéntrese en encontrar la adecuada para la tarea en cuestión.&nbsp;</span></p><p><span style="font-family: Satoshi, sans-serif;">En esta lección, obtendrás una visión general de las </span><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://a16z.com/100-gen-ai-apps-3/"><span style="font-family: Satoshi, sans-serif;"><strong>herramientas de IA más efectivas</strong></span></a><span style="font-family: Satoshi, sans-serif;"> disponibles en la actualidad. Nos centraremos en herramientas que pueden ayudarte con la escritura, las reuniones, la programación y más, brindándote una visión amplia de lo que es posible.</span></p><p><span style="font-family: Satoshi, sans-serif;"><strong>En esta lección, cubriremos:</strong></span></p><ul class="prose-bullet-list"><li><p><span style="font-family: Satoshi, sans-serif;">Una instantánea de las herramientas de IA más populares</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Cómo elegir qué herramientas utilizar y cuándo</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Esté abierto a probar nuevas herramientas</span></p></li></ul><h2><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>Las herramientas de IA más populares de 2025</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Es fácil sentirse abrumado por el volumen de herramientas de IA que existen.</span></p><p><span style="font-family: Satoshi, sans-serif;">Pero seamos sinceros: actualmente, la mayoría son divertidas y engañosas, sin valor práctico. En <strong>Expertos NoCodeIA&nbsp;</strong>, las hemos probado todas, y nuestro objetivo con este curso no es intimidarte con todo lo que hay, sino compartir únicamente herramientas que puedan tener un uso práctico en tu trabajo.</span></p><p><span style="font-family: Satoshi, sans-serif;">Por eso, en esta lección, le presentaremos las principales herramientas de IA disponibles actualmente en el mercado. Para cada herramienta, le proporcionaremos:</span></p><ul class="prose-bullet-list"><li><p><span style="font-family: Satoshi, sans-serif;">Una descripción de sus funciones</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Información de precios</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Casos de uso del mundo real</span></p></li></ul><p><span style="font-family: Satoshi, sans-serif;">Puede pensar en esta primera lección como una descripción general completa, mientras que en lecciones posteriores profundizaremos y le mostraremos cómo usar y aprovechar de manera efectiva las herramientas en su trabajo.</span></p><h2><span style="font-family: Satoshi, sans-serif;"><strong>Tipos de herramientas de IA generativa</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Las herramientas de IA generativa utilizan el poder del procesamiento del lenguaje natural y el aprendizaje profundo para crear diversos tipos de contenido basados ​​en indicaciones de lenguaje natural. En pocas palabras, ¡pueden convertir texto en prácticamente cualquier cosa!</span></p><p><span style="font-family: Satoshi, sans-serif;">Exploremos las categorías más populares:</span></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-65.png" alt="imagen-65.png" width="1920" height="339"><p></p><h2><span style="font-family: Satoshi, sans-serif;"><strong>🧠 Texto para responder: ChatGPT</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Impulsado por las últimas LLM de OpenAI, ChatGPT se ha convertido en un chatbot de IA popular y poderoso desde su lanzamiento en 2022. Procesa estas indicaciones y genera respuestas contextualmente relevantes en cuestión de segundos, lo que lo convierte en una herramienta altamente eficiente y versátil para diversos escenarios laborales diarios.</span></p><p><span style="font-family: Satoshi, sans-serif;">Los Modelos de Lenguaje Grande (LLM) pueden comprender sus preguntas, generar respuestas, resumir los documentos subidos y facilitar la escritura creativa y la programación. Una de las principales ventajas de los LLM es su integración con interfaces de chatbot, como </span><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://chatgpt.com/"><span style="font-family: Satoshi, sans-serif;"><strong>ChatGPT</strong></span></a><span style="font-family: Satoshi, sans-serif;"> , que permite a los usuarios interactuar con el modelo mediante indicaciones en lenguaje natural.</span></p><img class="prose-image" src="/api/lesson-resources/e267e2e9-0a92-433c-b94d-109451521dbb/image-1756765087441-bggevm.jpg"><h3><span style="font-family: Satoshi, sans-serif; font-size: 24px;"><strong>Algunos casos de uso de ChatGPT</strong></span></h3><ol class="prose-ordered-list"><li><p><span style="font-family: Satoshi, sans-serif;">Creación de contenido: ChatGPT genera artículos, publicaciones de blogs, correos electrónicos, textos de marketing y textos creativos como historias o guiones.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Traducción: Traduce texto en más de 50 idiomas, lo que facilita las tareas de comunicación y escritura.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Asistencia de codificación: ChatGPT ayuda con la codificación, la depuración y la explicación de conceptos, ahorrando tiempo a los desarrolladores.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Investigación y análisis: resume documentos y trabajos de investigación, proporcionando información clave.</span></p></li></ol><h3><span style="font-family: Satoshi, sans-serif; font-size: 24px;"><strong>Precios de ChatGPT</strong></span></h3><p><span style="font-family: Satoshi, sans-serif;">ChatGPT funciona con el modelo GPT-4o y es gratuito, pero las funciones avanzadas como la creación de GPT personalizados requieren una suscripción Plus de $20 al mes.</span></p><h2><span style="font-family: Satoshi, sans-serif;"><strong>🎨</strong> </span><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>Texto a imagen: Midjourney</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Los modelos de texto a imagen utilizan grandes conjuntos de datos para crear imágenes a partir de indicaciones, fusionar estilos, ampliar y ajustar regiones de la imagen. Midjourney, lanzado en 2019, es popular por producir imágenes fotorrealistas de alta calidad para usos creativos.</span></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-67.png" alt="imagen-67.png" width="1920" height="974"><p></p><h3><span style="font-family: Satoshi, sans-serif; font-size: 24px;"><strong>Algunos casos de uso de Midjourney</strong></span></h3><ol class="prose-ordered-list"><li><p><span style="font-family: Satoshi, sans-serif;">Activos de marketing: genere imágenes para campañas, sitios web y redes sociales, ahorrando tiempo y recursos.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Diseño de producto: Midjourney ayuda en la lluvia de ideas generando rápidamente variaciones de diseño.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Exploración artística: los artistas utilizan Midjourney para explorar nuevos estilos y conceptos, ampliando los límites creativos.</span></p></li></ol><h3><span style="font-family: Satoshi, sans-serif; font-size: 24px;"><strong>Precios de Midjourney</strong></span></h3><p><span style="font-family: Satoshi, sans-serif;">Desde 2023, Midjourney dejó de ofrecer un plan gratuito. Los planes de pago ahora cuestan desde $8 al mes.</span></p><h2><span style="font-family: Satoshi, sans-serif;"><strong>📄 </strong></span><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>Texto de presentación: Gamma</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Gamma AI se especializa en crear documentos, presentaciones y sitios web visualmente atractivos a partir de un simple texto o una entrada de mensaje.</span></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-68.png" alt="imagen-68.png" width="1920" height="925"><p></p><h3><span style="font-family: Satoshi, sans-serif;"><strong>Algunos casos de uso de Gamma</strong></span></h3><ol class="prose-ordered-list"><li><p><span style="font-family: Satoshi, sans-serif;">Creación de presentaciones comerciales: Gamma genera rápidamente presentaciones profesionales, como presentaciones de ventas, demostraciones de productos y presentaciones para inversores.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Diseño de páginas web: la función Sitio de Gamma permite a los usuarios crear páginas de destino de marca o sitios web completos, ideales para pequeñas empresas y nuevas empresas.</span></p></li></ol><h3><span style="font-family: Satoshi, sans-serif;"><strong>Precios de Gamma</strong></span></h3><p><span style="font-family: Satoshi, sans-serif;">Gamma ofrece 400 créditos de IA a los usuarios al registrarse. Estos créditos no se recargarán una vez agotados. Para desbloquear créditos de IA ilimitados, los usuarios deben suscribirse a los planes Plus, que empiezan desde $8 al mes.</span></p><h2><span style="font-family: Satoshi, sans-serif;"><strong>🚀</strong></span><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong> Texto a automatización: Zapier</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Zapier es una herramienta de automatización web que permite la integración y conexión fluida de diversas aplicaciones y servicios web. Se trata de un flujo de trabajo automatizado conocido como Zaps.</span></p><p><span style="font-family: Satoshi, sans-serif;">Recientemente, han integrado flujos de trabajo de IA en sus productos, brindando a los usuarios un método más intuitivo para ejecutar la automatización: Textos a Zaps.</span></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-69.png" alt="imagen-69.png" width="1920" height="925"><p></p><h3><span style="font-family: Satoshi, sans-serif;"><strong>Algunos casos de uso de Zapier</strong></span></h3><ol class="prose-ordered-list"><li><p><span style="font-family: Satoshi, sans-serif;">Flujo de trabajo de texto a automatización: el generador de Zap impulsado por IA de Zapier simplifica la creación de automatizaciones complejas a partir de indicaciones para usuarios no técnicos.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Integración de aplicaciones y modelos de IA: Zapier conecta más de 6000 aplicaciones, lo que permite flujos de trabajo con pasos de IA como generación de contenido o análisis de CRM.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Creación de chatbots de IA personalizados: los usuarios pueden crear chatbots de IA personalizados con Zapier Chatbots (Beta) e integrarlos con Zaps para tareas automatizadas.</span></p></li></ol><h3><span style="font-family: Satoshi, sans-serif;"><strong>Precios de Zapier</strong></span></h3><p><span style="font-family: Satoshi, sans-serif;">Con el plan gratuito, los usuarios pueden crear un número ilimitado de Zaps de dos pasos y ejecutar hasta 100 tareas de automatización al mes. Para más de 100 tareas, existen planes de pago desde $19.99 al mes.</span></p><h2><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>¿Cómo se utilizan las herramientas de automatización de IA en la fuerza laboral del mundo real?</strong></span></h2><img class="prose-image" src="/api/lesson-resources/57fae203-7d4a-43f4-84f2-d731e4153880/image-1756766323242-8zylfn.jpg"><p><span style="font-family: Satoshi, sans-serif;">A continuación se muestran algunos casos de uso comunes de herramientas de automatización de IA:</span></p><ul class="prose-bullet-list"><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Gestión de proyectos:</strong> cree tareas automáticamente en herramientas como Trello o Asana a partir de correos electrónicos o eventos del calendario para mantener los proyectos organizados.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Entrada de datos:</strong> Automatice las actualizaciones de hojas de cálculo con datos de formularios o entradas de CRM, reduciendo errores y ahorrando tiempo.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Atención al cliente:</strong> la IA gestiona consultas rutinarias, liberando agentes para problemas complejos y acelerando las resoluciones.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Marketing:</strong> Automatice campañas de correo electrónico, publicaciones en redes sociales y segmentación de clientes para una comunicación oportuna y personalizada.</span></p></li></ul><h2><span style="font-family: Satoshi, sans-serif;"><strong>Las herramientas de automatización de IA más populares en 2025</strong></span></h2><ol class="prose-ordered-list"><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://zapier.com/"><span style="font-family: Satoshi, sans-serif;"><strong>Zapier:&nbsp;</strong></span></a><span style="font-family: Satoshi, sans-serif;"> Una herramienta de automatización líder que se conecta con más de 5000 aplicaciones para automatizar flujos de trabajo, llamada "Zaps". Permite a los usuarios configurar activadores y acciones sin necesidad de programar, agilizando tareas como la sincronización de datos, las notificaciones por correo electrónico y las publicaciones en redes sociales, lo que aumenta la productividad.</span></p></li><li><p><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://n8n.io/"><span style="font-family: Satoshi, sans-serif;"><strong>n8n:</strong></span></a><span style="font-family: Satoshi, sans-serif;"><strong> </strong>es una plataforma de automatización de flujo de trabajo nativa de IA y de código abierto que permite a los usuarios diseñar y automatizar visualmente procesos complejos en más de 500 integraciones, combinando la simplicidad sin código con la flexibilidad del código personalizado y las opciones de autohospedaje.</span></p></li><li><p><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://Make.com"><span style="font-family: Satoshi, sans-serif;"><strong>Make.com</strong></span></a><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://make.com/"><span style="font-family: Satoshi, sans-serif;"><strong> ,</strong></span></a><span style="font-family: Satoshi, sans-serif;"> una plataforma de automatización avanzada similar a Zapier, se centra en la creación de escenarios con una interfaz visual para flujos de trabajo complejos. Admite amplias integraciones, lo que permite una automatización sofisticada que incluye manipulación de datos, interacciones con API y lógica condicional, ideal para necesidades de automatización personalizadas.</span></p></li></ol><h2><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>Ventajas y desventajas de las herramientas de automatización de IA</strong></span></h2><img class="prose-image" src="/api/lesson-resources/134b7c04-b866-46ff-bd0f-e1dfcc6bacbb/image-1756767082164-wvwav.jpg"><h2><span style="font-family: Satoshi, sans-serif;"><strong><br></strong></span><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>📹 Imagen a Vídeo: HeyGen</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">Las herramientas de video con inteligencia artificial generan videos a partir de texto o imágenes, incluidos avatares de inteligencia artificial que sincronizan los labios en más de 40 idiomas y acentos.</span></p><p><span style="font-family: Satoshi, sans-serif;">HeyGen, una herramienta popular, combina la voz de IA con avatares para crear videos explicativos y promocionales de alta calidad, eliminando la necesidad de cámaras, actores o locutores.</span></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-72.png" alt="imagen-72.png" width="1920" height="1008"><p></p><h3><span style="font-family: Satoshi, sans-serif;"><strong>Algunos casos de uso de HeyGen</strong></span></h3><ol class="prose-ordered-list"><li><p><span style="font-family: Satoshi, sans-serif;">Vídeos explicativos: HeyGen utiliza avatares de IA y voces en off para simplificar temas complejos, lo que hace que los vídeos explicativos sean más atractivos.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Capacitación corporativa: HeyGen crea videos de capacitación para la incorporación, el desarrollo de habilidades y el intercambio de conocimientos.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Vídeos de marketing: las pequeñas empresas pueden producir rápidamente contenido de marketing, demostraciones y testimonios con los avatares y elementos visuales de inteligencia artificial de HeyGen.</span></p></li></ol><h3><span style="font-family: Satoshi, sans-serif;"><strong>Precios de HeyGen</strong></span></h3><p><span style="font-family: Satoshi, sans-serif;">El plan gratuito de HeyGen ofrece a los usuarios un crédito (1 minuto) al mes, muy limitado. Pueden elegir entre varios planes de pago según sus necesidades. Los planes de pago empiezan desde $24 al mes.</span></p><h2><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>🎵 Texto a audio: Suno</strong></span></h2><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://suno.com/"><span style="font-family: Satoshi, sans-serif;"><strong>Suno AI</strong></span></a><span style="font-family: Satoshi, sans-serif;"> , lanzado a finales de 2023, genera canciones de alta calidad de géneros como pop, EDM y rock a partir de indicaciones de texto. También crea letras completas y amplía las canciones.</span></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-73.png" alt="imagen-73.png" width="1920" height="974"><p></p><h3><span style="font-family: Satoshi, sans-serif;"><strong>Algunos casos de uso de Suno</strong></span></h3><ol class="prose-ordered-list"><li><p><span style="font-family: Satoshi, sans-serif;">Creación musical: Suno AI genera canciones completas, incluidas voces, instrumentales y letras, basadas en indicaciones de texto que describen el estilo, el género y el estado de ánimo.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Generación de bandas sonoras instrumentales: cree bandas sonoras personalizadas para vídeos, películas, podcasts y comerciales con Suno AI.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Exploración artística: los músicos pueden utilizar Suno AI para componer canciones, generando canciones completas a partir de letras originales o creando variaciones.</span></p></li></ol><h3><span style="font-family: Satoshi, sans-serif;"><strong>Precios</strong></span></h3><p><span style="font-family: Satoshi, sans-serif;">Suno ofrece 50 créditos diarios (10 canciones). Para uso comercial, los usuarios deben suscribirse al plan Pro o superior, desde $8 al mes.</span></p><h3><span style="font-family: Satoshi, sans-serif;"><strong>Fin 🎉&nbsp;</strong></span></h3><p><span style="font-family: Satoshi, sans-serif;">Con esto concluye nuestro resumen de las herramientas de IA más populares en 2024.&nbsp;</span></p><h2><span style="font-family: Satoshi, sans-serif; font-size: 28px;"><strong>¿Cómo puedo beneficiarme con herramientas de IA?</strong></span></h2><p><span style="font-family: Satoshi, sans-serif;">En pocas palabras, las herramientas de productividad de IA ayudan a realizar más trabajo en menos tiempo. Se trata de eficiencia, eficacia y la capacidad de obtener resultados con un mínimo desperdicio de esfuerzo o gasto.</span></p><p><span style="font-family: Satoshi, sans-serif;">Dependiendo de su industria y experiencia, diferentes tareas requieren diferentes fortalezas:</span></p><ul class="prose-bullet-list"><li><p><span style="font-family: Satoshi, sans-serif;">Entornos de oficina con tareas administrativas repetitivas como ingreso de datos, programación y documentación.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">En campos creativos como la escritura, el diseño y la creación de contenidos, la velocidad de ideación y ejecución son importantes.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Proyectos de desarrollo y codificación de software que requieren colaboración eficiente y creación rápida de prototipos.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Las tareas de investigación y análisis implican grandes conjuntos de datos que deben procesarse rápidamente.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Operaciones de servicio y soporte al cliente que manejan grandes volúmenes de consultas y solicitudes.</span></p></li></ul><p><span style="font-family: Satoshi, sans-serif;"><strong>Si quieres ver qué herramientas de IA son las más populares por visitas mensuales únicas:</strong></span></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-74.png" alt="imagen-74.png" width="800" height="480"><p></p><h3><span style="font-family: Satoshi, sans-serif; font-size: 20px;"><strong>¿Cuándo uso qué herramienta?</strong></span></h3><p><span style="font-family: Satoshi, sans-serif;">Saber qué herramienta de IA usar puede ser abrumador, pero quizás quieras empezar a mejorar tu productividad analizando tus tareas diarias y viendo qué te ocupa la mayor parte del tiempo durante tu jornada laboral. Aquí tienes un enfoque estructurado:&nbsp;</span></p><ol class="prose-ordered-list"><li><p><span style="font-family: Satoshi, sans-serif;">Establecer un problema objetivo a resolver (por ejemplo, "Usar IA para crear una campaña de marketing")</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Elija una herramienta relevante</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Prueba y error, o seguir un tutorial</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Aplícalo a tu tarea del mundo real.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;">Reflexionar sobre el proceso y los resultados</span></p></li></ol><h3><span style="font-family: Satoshi, sans-serif; font-size: 20px;"><strong>¿Cómo se utilizan las herramientas de productividad de IA en la fuerza laboral del mundo real?</strong></span></h3><ul class="prose-bullet-list"><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Gestión de proyectos mejorada</strong> : las herramientas de IA automatizan la asignación de tareas, establecen recordatorios y sugieren mejoras en el flujo de trabajo para una gestión de proyectos más eficiente.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Transcripciones y resúmenes de reuniones</strong> : la IA captura y transcribe reuniones en tiempo real, generando resúmenes y elementos de acción para ahorrar tiempo.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Recuperación de información</strong> : los asistentes de IA indexan la actividad de la pantalla, lo que permite a los usuarios recordar fácilmente información de reuniones o discusiones pasadas.</span></p></li><li><p><span style="font-family: Satoshi, sans-serif;"><strong>Impulsar la creatividad</strong> : las herramientas de diseño y presentación con inteligencia artificial agilizan la creación de materiales de marketing, informes y sesiones de intercambio de ideas.</span></p></li></ul><p></p><h3><span style="font-family: Satoshi, sans-serif; font-size: 20px;"><strong>Esté abierto y preparado para adaptarse</strong></span></h3><p><span style="font-family: Satoshi, sans-serif;">Es posible que uses ciertas herramientas porque te resultan familiares o fáciles de usar, pero como la IA avanza tan rápido, siempre se lanzan mejores herramientas.&nbsp;</span></p><p><span style="font-family: Satoshi, sans-serif;">Esté abierto al cambio y preparado para experimentar con nuevas herramientas que sean más efectivas para resolver su flujo de trabajo específico.</span></p><p><span style="font-family: Satoshi, sans-serif;">Encuentra todas tus herramientas favoritas clasificadas aquí en Expertos NoCodeIA </span></p><p><span style="font-family: Satoshi, sans-serif;"><strong>Consejo:</strong> La mayoría de estas herramientas de IA ofrecen generosos periodos de prueba o créditos gratuitos para probar antes de suscribirse. Si eres un usuario avanzado, puedes solicitar un generoso descuento directamente a la empresa.&nbsp;</span></p><p><span style="font-family: Satoshi, sans-serif;"><strong>Esto es lo que has aprendido.</strong><br>Ahora que tienes una visión general de todas las herramientas de IA disponibles, cuáles son populares y cómo elegir cuál usar, pasemos a las herramientas esenciales y sus flujos de trabajo que te permitirán trabajar de forma más inteligente y rápida.</span></p>', 17, '2025-09-01 22:15:09.789824', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-01 22:15:09.789824', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('fade9238-6974-43ed-9879-42b8d3adaea2', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Descubra el poder de los GPT personalizados: personalice su productividad', NULL, '<p>Incluso si el progreso de la IA se detuviera (muy improbable) en este preciso instante, seguiríamos estando increíblemente agradecidos por la eficiencia y los beneficios que hemos obtenido de la IA generativa en los últimos dos años.<br><br>ChatGPT ha cambiado nuestra forma de trabajar y, en muchos casos, también de vivir. La actualización de noviembre de 2023 introdujo GPT personalizados, chatbots personalizados que se adaptan a tus necesidades específicas.</p><p>En esta lección, exploraremos qué son los GPT personalizados y cómo puedes crearlos para automatizar tus tareas más repetitivas e importantes.</p><p><strong>En esta lección aprenderás:</strong></p><ul class="prose-bullet-list"><li><p>¿Qué son los GPT personalizados?</p></li><li><p>Ventajas clave de los GPT personalizados</p></li><li><p>Ejemplos de GPT personalizados populares</p></li><li><p>Guía paso a paso para crear tu propio GPT</p></li><li><p>Cómo decidir qué GPT crear para su flujo de trabajo</p></li></ul><p>Como siempre, vayamos directo al grano.</p><h3><strong>¿Qué son los GPT personalizados?</strong></h3><p>Las tareas repetitivas o la necesidad de respuestas especializadas pueden ralentizar el proceso y generar resultados inconsistentes al usar herramientas genéricas. Tener que explicar o ajustar repetidamente cada nueva consulta se vuelve rápidamente frustrante e ineficiente.</p><p>Los GPT personalizados ofrecen una solución que te permite crear chatbots adaptados a tus necesidades. Considéralos como mini-ChatGPT que pueden automatizar tareas, dar respuestas precisas y garantizar la coherencia en cada interacción.</p><h3><strong>Ventajas de los GPT personalizados</strong></h3><ul class="prose-bullet-list"><li><p><strong>Múltiples GPT para diferentes tareas</strong> : no está limitado a un solo bot, cree diferentes GPT para diversas tareas, como escritura, análisis de datos o investigación.</p></li><li><p><strong>Archivos de origen de conocimiento</strong> : cargue documentos a los que su GPT pueda hacer referencia, lo que lo hará más preciso e informado.</p></li><li><p><strong>Compartir fácilmente</strong> : comparta sus GPT personalizados a través de enlaces privados o publíquelos en la biblioteca GPT pública.</p></li></ul><h3><strong>Ejemplos populares de GPT personalizados</strong></h3><ul class="prose-bullet-list"><li><p><strong>ScholarGPT</strong> : Acceda e interactúe con una biblioteca de investigación académica.</p></li><li><p><strong>Canva GPT</strong> : diseña cualquier cosa, desde contenido de redes sociales hasta logotipos.</p></li><li><p><strong>Logo Creator</strong> : un asistente de primer nivel para crear logotipos profesionales.</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-55.png" alt="imagen-55.png" width="800" height="480"><p></p><h3><strong>Cómo crear GPT personalizados: guía paso a paso</strong></h3><p>¿Una de las mejores partes? ¡No necesitas saber programar para crear un GPT personalizado! Aquí te explicamos cómo empezar:</p><ol class="prose-ordered-list"><li><p><strong>Iniciar sesión en OpenAI</strong> : Inicia sesión o crea una cuenta en la plataforma ChatGPT. Selecciona el modelo GPT-4.</p></li><li><p><strong>Crea tu GPT</strong> : En la interfaz de ChatGPT, haz clic en "Explorar GPT" en la barra lateral y luego en "Crear" para abrir el generador de GPT. El generador tiene una pantalla dividida: una para introducir las indicaciones y otra para previsualizar las respuestas.</p></li></ol><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-56.png" alt="imagen-56.png" width="800" height="480"><p></p><ol class="prose-ordered-list"><li><p><strong>Configura tu GPT</strong> : Personaliza el nombre, la descripción, la foto de perfil, las instrucciones y los temas de conversación de tu GPT. También puedes habilitar funciones avanzadas como:</p></li></ol><ul class="prose-bullet-list"><li><p>Carga de archivos de conocimiento</p></li><li><p>Capacidades de navegación web</p></li><li><p>Generación de imágenes</p></li><li><p>Ejecución de código</p></li><li><p>Análisis de datos</p></li><li><p>Integraciones de API de terceros</p></li></ul><ol class="prose-ordered-list"><li><p><strong>Guardar y compartir</strong> : Una vez satisfecho con los resultados, guarde su GPT. Puede compartirlo de forma privada mediante un enlace o hacerlo público agregándolo a la tienda de GPT.</p></li></ol><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-57.png" alt="imagen-57.png" width="800" height="480"><p></p><h3><strong>Características adicionales:</strong></h3><ul class="prose-bullet-list"><li><p><strong>Foto de perfil:</strong> sube una imagen o usa DALL·E para generar una.</p></li><li><p><strong>Instrucciones:</strong> ajuste el comportamiento de GPT agregando instrucciones personalizadas específicas.</p></li><li><p><strong>Capacidades:</strong> Los GPT personalizados pueden navegar por la web, generar imágenes, ejecutar código y analizar datos, según la configuración elegida.</p></li><li><p><strong>Acciones:</strong> Las integraciones con API de terceros, como Zapier, permiten que GPT interactúe con aplicaciones y servicios externos.</p></li></ul><h3><strong>Administrar sus GPT</strong></h3><p>Si necesita editar, compartir o eliminar su GPT personalizado, aquí le mostramos cómo hacerlo:</p><p><strong>Editar</strong> :</p><ol class="prose-ordered-list"><li><p>Seleccione el GPT que desea modificar desde la barra lateral.</p></li><li><p>Haga clic en su nombre en la parte superior izquierda de la ventana de conversación.</p></li><li><p>Seleccione "Editar GPT", realice los cambios y luego haga clic en "Actualizar".</p></li></ol><p><strong>Compartir</strong> :</p><ol class="prose-ordered-list"><li><p>Seleccione GPT desde la barra lateral.</p></li><li><p>Haga clic en su nombre en la parte superior izquierda.</p></li><li><p>Haga clic en "Compartir" y luego seleccione "Crear enlace" para compartirlo de forma privada o pública.</p></li></ol><p><strong>Borrar</strong> :</p><ol class="prose-ordered-list"><li><p>Seleccione GPT desde la barra lateral.</p></li><li><p>Haga clic en su nombre en la parte superior izquierda.</p></li><li><p>Haga clic en "Editar GPT", luego haga clic en los puntos suspensivos (...) junto a "Compartir" y seleccione "Eliminar GPT".</p></li></ol><h3><strong>Cómo decidir qué GPT crear</strong></h3><p>Piensa en las tareas que más te consumen. Divídelas en tres categorías:</p><ol class="prose-ordered-list"><li><p><strong>Investigación</strong> : para tareas como recopilación de datos o análisis de grandes conjuntos de datos.</p></li><li><p><strong>Estrategia</strong> : Para proyectos que requieran colaboración, codificación o creación de prototipos.</p></li><li><p><strong>Creación</strong> : Para trabajos de ideación, creación de contenidos o diseño donde la velocidad y la creatividad son esenciales.</p></li></ol><p><strong>Consejo</strong> : ¡Encadena GPT! En lugar de alternar entre GPT, simplemente escribe "@" para llamar a otra GPT y ayudarte con tu flujo de trabajo actual. Esto mantiene todo integrado y sin interrupciones.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-58.png" alt="imagen-58.png" width="800" height="480"><p></p><p>Ahora está listo para crear GPT personalizados para automatizar sus tareas que consumen más tiempo y optimizar sus flujos de trabajo.</p>', 15, '2025-09-01 20:07:09.405715', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-01 20:07:09.405715', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('60f240da-415e-4bfc-b1e4-71042ea9f20c', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Mejore su experiencia ChatGPT con instrucciones personalizadas', NULL, '<p>Muchos usuarios están cansados ​​de las respuestas genéricas que proporciona la IA, ya que no se alinean ni siguen sus indicaciones específicas.</p><p>Las instrucciones personalizadas te acercan un paso más a tener el asistente de inteligencia artificial perfecto que comprende tus preferencias, contexto y estilo de comunicación.</p><p>En esta lección, exploraremos cómo las instrucciones personalizadas pueden adaptar las respuestas de ChatGPT a sus necesidades, haciendo que las interacciones sean más relevantes, específicas y eficientes.</p><p>Porque cuando la IA habla <em>tu</em> idioma, todo se vuelve más fácil.</p><p><strong>En esta lección, cubriremos:&nbsp;</strong></p><ul class="prose-bullet-list"><li><p>¿Qué son las instrucciones personalizadas?</p></li><li><p>Ejemplos de instrucciones personalizadas efectivas</p></li><li><p>Cómo configurar instrucciones personalizadas</p></li><li><p>Mejores prácticas para optimizar su experiencia con IA</p></li></ul><p>Como siempre, vayamos directo al grano.</p><h3><strong>¿Qué son las instrucciones personalizadas?</strong></h3><p>Las instrucciones personalizadas te permiten personalizar la respuesta de ChatGPT, brindándole información sobre ti y tus preferencias. Esto elimina respuestas aleatorias o fuera de lugar y crea una experiencia de IA más fluida y relevante.</p><p>Una vez que configures tus Instrucciones Personalizadas, ChatGPT generará respuestas adaptadas a tu contexto y en el formato que especifiques. Se acabaron las explicaciones repetitivas y los resultados impredecibles: solo respuestas específicas que se adaptan a ti.</p><h3><strong><br>Cómo acceder a las instrucciones personalizadas de ChatGPT</strong></h3><p>Para usuarios web:</p><ul class="prose-bullet-list"><li><p>Haga clic en su nombre de usuario en la esquina superior derecha, luego seleccione "Personalizar ChatGPT".</p></li></ul><img class="prose-image" src="/api/lesson-resources/f3a5a773-a56f-4041-ae55-9c02ac78c899/image-1756757691697-fnnshp.jpg"><ul class="prose-bullet-list"><li><p>Para usuarios de iOS y Android:</p><ul class="prose-bullet-list"><li><p>Vaya a Configuración → Cuenta → Personalización y active "Personalizar ChatGPT".</p></li></ul></li><li><p>Encontrarás dos cuadros de texto clave para personalizar tu experiencia:</p><ul class="prose-bullet-list"><li><p>" <strong>¿Qué le gustaría que ChatGPT supiera sobre usted?</strong> ": Aquí, proporciona detalles sobre su puesto, industria o preferencias.</p></li><li><p>"¿ <strong>Cómo le gustaría que ChatGPT responda?</strong> " – Especifique el tono, el estilo, el formato y la longitud de las respuestas que prefiera.</p></li></ul></li></ul><p></p><h3><strong>Por qué son útiles las instrucciones personalizadas</strong></h3><p>Las instrucciones personalizadas mejoran la capacidad de ChatGPT para proporcionar:</p><ul class="prose-bullet-list"><li><p>Relevancia: Respuestas adaptadas a su función o tarea específica.</p></li><li><p>Tono y estilo: Tono consistente que se adapta a sus preferencias de comunicación.</p></li><li><p>Longitud: Control sobre qué tan breves o detalladas serán las respuestas.</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-60.png" alt="imagen-60.png" width="800" height="480"><p></p><p>Aquí están mis instrucciones personalizadas actuales:</p><img class="prose-image" src="/api/lesson-resources/c1739adc-bf73-4b13-ac4a-536f8b532921/image-1756758570382-aowxw7.jpg"><h3><strong>Ejemplos de instrucciones personalizadas para roles específicos</strong></h3><p>Gerente de Marketing</p><ul class="prose-bullet-list"><li><p>Cuadro 1: “Soy un profesional de marketing con [X] años de experiencia en gestión de marca y marketing digital”.</p></li><li><p>Cuadro 2: "Ofrezca estrategias de marketing concisas y prácticas con estudios de casos reales que respalden cada recomendación".</p></li></ul><p>Por qué funciona: Garantiza que la IA brinde asesoramiento práctico basado en el éxito del mundo real.</p><p>Desarrollador de software</p><ul class="prose-bullet-list"><li><p>Cuadro 1: "Me especializo en desarrollo full-stack con foco en aplicaciones web escalables".</p></li><li><p>Cuadro 2: "Proporcione fragmentos de código detallados, mejores prácticas y referencias a los marcos actuales".</p></li></ul><p>Por qué funciona: Ofrece soluciones de código precisas y actualizadas con los estándares de la industria.<br><br><br>Gerente de Proyecto</p><ul class="prose-bullet-list"><li><p>Cuadro 1: “Gestiono equipos multifuncionales en la industria tecnológica, especializándome en la metodología Agile”.</p></li><li><p>Cuadro 2: “Proporcionar planes paso a paso con cronogramas y factores de riesgo, alineados con los principios ágiles”.</p></li></ul><p>Por qué funciona: Ayuda a garantizar planes de proyecto bien organizados con expectativas claras.<br><br><br>Redactor de contenido.</p><ul class="prose-bullet-list"><li><p>Cuadro 1: "Creo contenido optimizado para SEO para blogs y artículos enfocados en aumentar la interacción".</p></li><li><p>Cuadro 2: "Proporcione ideas de contenido, esquemas e incluya recomendaciones de palabras clave SEO".</p></li></ul><p>Por qué funciona: Garantiza que el contenido sea atractivo y esté optimizado para los motores de búsqueda.</p><p>Especialista en RRHH</p><ul class="prose-bullet-list"><li><p>Cuadro 1: “Me especializo en adquisición de talento corporativo y desarrollo de empleados”.</p></li><li><p>Cuadro 2: “Proporcionar preguntas de entrevista estructuradas y planes de desarrollo, enfatizando la diversidad y la inclusión”.</p></li></ul><p>Asesor financiero</p><ul class="prose-bullet-list"><li><p>Cuadro 1: “Ofrezco planificación financiera a largo plazo y asesoramiento en gestión patrimonial”.</p></li><li><p>Cuadro 2: “Desglose las opciones de inversión con pros y contras, y proporcione proyecciones futuras y evaluaciones de riesgos”.</p></li></ul><p>Diseñador gráfico</p><ul class="prose-bullet-list"><li><p>Cuadro 1: "Creo contenido visual para branding y marketing digital utilizando Adobe Creative Suite".</p></li><li><p>Cuadro 2: "Proporcione inspiración visual, pautas de diseño detalladas e incluya esquemas de color y sugerencias tipográficas".</p></li></ul><h3></h3><h3><strong>Plantilla genérica para instrucciones personalizadas:</strong></h3><p><strong>Profesional genérico:</strong></p><p>Casilla 1: Tengo [X] años de experiencia en [industria/profesión, por ejemplo, consultoría, gestión, diseño creativo], especializándome en [área específica de especialización, por ejemplo, operaciones, estrategia, innovación].</p><ul class="prose-bullet-list"><li><p>Recuadro 2: Proporcione respuestas bien estructuradas que incluyan información práctica, ejemplos relevantes y un resumen de los puntos clave.<br>¿Por qué es útil? Garantiza que el asesoramiento sea claro, práctico y de aplicación inmediata a las necesidades profesionales, lo que facilita una mejor toma de decisiones.</p></li></ul><h3><strong>Instrucciones personalizadas para una interacción divertida con amigos</strong></h3><p>1. ¿Qué le gustaría que ChatGPT supiera sobre usted para brindarle mejores respuestas?</p><p><em>Me encanta el humor, sobre todo el humor sutil. Busco valor en cada respuesta, pero siéntete libre de incluir un chiste y un tono divertido para alegrarme el día.</em></p><p>2. ¿Cómo le gustaría que ChatGPT responda?</p><p><em>Mantén un tono divertido, ligero y positivo en cada respuesta. Empieza con un chiste, usa el humor constantemente y haz que incluso los temas serios sean divertidos con analogías divertidas y juegos de palabras. Evita el sarcasmo o las bromas insensibles. Busca un ambiente amigable e ingenioso, como si estuvieras charlando con un amigo divertido. Termina con una pregunta original para mantener el humor y siempre equilibra el humor con información útil y clara.</em></p><img class="prose-image" src="/api/lesson-resources/559e0316-374c-43e5-b573-c4da61f98f86/image-1756763601919-ywwb4.jpg"><h3><strong>Estudio de caso: Con y sin instrucciones personalizadas</strong></h3><p>Este es el mensaje ingresado en ChatGPT: <em>"Mi empresa ofrece servicios de consultoría. El personal no ha aprendido a usar la IA en nuestros flujos de trabajo. Siguen registrando datos y utilizando procesos manuales que les llevan 3 horas diarias. Tardan 4 horas en crear una presentación. Creo que esto se puede mejorar con la IA, ¿podrían aconsejarme?"</em></p><ul class="prose-bullet-list"><li><p>Sin instrucciones personalizadas: una respuesta genérica con sugerencias prácticas limitadas.</p></li><li><p>Con instrucciones personalizadas: un resultado detallado y estructurado que ofrece áreas de mejora clave, cambios propuestos en el flujo de trabajo, resultados esperados y próximos pasos procesables.</p></li></ul><p>¿El resultado? Una respuesta mucho más completa y útil, adaptada a tu situación.</p><img class="prose-image" src="/api/lesson-resources/94e40960-c80a-44e2-850e-d9fd8d3d7e6b/image-1756763586517-lvyszi.jpg"><h3><strong>Crear accesos directos con instrucciones personalizadas</strong></h3><p><em>Ejemplo 1:</em></p><p><strong>Ejemplos útiles de instrucciones personalizadas</strong></p><p>Caja 1:</p><ul class="prose-bullet-list"><li><p>"Responda de manera concisa y directa."</p></li><li><p>Me gusta usar atajos</p></li></ul><p>Caja 2:&nbsp;</p><ul class="prose-bullet-list"><li><p>"W": Proporcionar un contexto más amplio.</p></li><li><p>"A": Ofrecer una visión alternativa.</p></li><li><p>"S": Simplifica la respuesta.</p></li><li><p>"D": Proporcionar información detallada.</p></li><li><p>"I": Ignorar la afirmación anterior.</p></li><li><p>"Q": Hacer una consulta para aclarar algo.</p></li></ul><img class="prose-image" src="/api/lesson-resources/bf5d5b31-222c-4f64-8e8b-cd437038df96/image-1756764611245-aqhz6f.jpg"><p>Al configurar y ajustar las Instrucciones Personalizadas, puede garantizar que cada interacción con ChatGPT sea más eficiente, relevante y esté alineada con sus objetivos personales y profesionales. Experimente con diferentes configuraciones para aprovechar al máximo el potencial de su asistente de IA.</p><p><strong>Consejo</strong> : Continúa actualizando tus instrucciones personalizadas a medida que evolucionen tus necesidades. Cuanto más contexto tenga ChatGPT sobre ti, mejor podrá adaptar sus respuestas.</p><p><strong>Lo que has aprendido</strong><br>Ahora sabes cómo configurar instrucciones personalizadas para garantizar respuestas consistentes y de alta calidad de ChatGPT.</p>', 16, '2025-09-01 20:09:49.498736', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-01 20:09:49.498736', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('62da2816-d7b3-465e-8019-fd4ef0a2fd8c', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Acelere su trabajo con fragmentos de Text Blaze', NULL, '<p>¿Cansado de escribir repetidamente?&nbsp;</p><p>Escribir es increíblemente lento cuando estás redactando correos electrónicos, activando la IA o redactando un documento: tiene que haber una mejor manera.&nbsp;</p><p>Perdemos mucho tiempo escribiendo contenido similar, y podrías pensar que son solo unos minutos, pero estos minutos se suman e impactan en tu productividad y creatividad.&nbsp;</p><p>En esta lección, veremos cómo usar&nbsp; <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://blaze.today/"><strong>Textblaze</strong></a> &nbsp;para crear atajos. Esta capacidad de crear atajos para fragmentos puede ahorrarte horas al día.</p><p>Al final, sabrás qué es Textblaze, cómo acceder a él y comenzar a crear plantillas de fragmentos.&nbsp;</p><p>¡Vamos!</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>¿Qué es Text Blaze?</p></li><li><p>Empezando</p></li><li><p>Creación y uso de fragmentos de texto</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-82.png" alt="imagen-82.png" width="800" height="480"><p></p><h2><strong>¿Qué es Blaze?</strong></h2><p>Básicamente, creas un fragmento de texto en Text Blaze como plantilla y le asignas un atajo de teclado. Por ejemplo, podrías usar "/ca" para enviar nuestra invitación de calendario a alguien.</p><h2><strong>1. Introducción a Blaze</strong></h2><p>Si valoras tu tiempo y quieres minimizar el esfuerzo que dedicas a escribir correos electrónicos repetitivos o instrucciones largas, Blaze es una herramienta esencial que debes añadir a tu conjunto de herramientas. Blaze te permite crear fragmentos de texto personalizables que puedes insertar rápidamente en cualquier campo de texto de Chrome.</p><ol class="prose-ordered-list"><li><p>Regístrate: Visita <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://blaze.today"><strong>blaze.today</strong></a> y crea una cuenta gratuita. El plan gratuito ofrece 20 fragmentos diferentes, perfectos para empezar. Si necesitas más, el plan Pro está disponible por solo $3 al mes.</p></li><li><p>Agregue Blaze a su navegador: después de registrarse, agregue Blaze a su navegador Chrome siguiendo las instrucciones en pantalla.</p></li></ol><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-83.png" alt="imagen-83.png" width="800" height="480"><p></p><h3><strong>2. Crea tu primer fragmento</strong></h3><p>Una vez que haya iniciado sesión, es momento de crear su primer fragmento:</p><ol class="prose-ordered-list"><li><p>Haga clic en el signo más: en su panel de Blaze, haga clic en el signo más para iniciar un nuevo fragmento.</p></li><li><p>Define tu fragmento:</p></li></ol><ul class="prose-bullet-list"><li><p>Etiqueta: Este es el título de tu fragmento. Por ejemplo, "Respuesta a la solicitud de reunión".</p></li><li><p>Atajo: Este es el texto que activará el fragmento. Por ejemplo, podría usar /reunión para insertar una respuesta estándar a una reunión.</p></li><li><p>Contenido: Escribe el mensaje o texto que quieres que se inserte al activar el acceso directo. Por ejemplo, "¡Gracias por contactarme! Consulta mis horarios disponibles aquí: [Enlace de Calendly]".</p></li></ul><h3><strong>3. Usa tus fragmentos</strong></h3><p>Blaze funciona a la perfección con Chrome, lo que lo convierte en una herramienta potente para redactar correos electrónicos rápidamente, completar formularios o generar contenido extenso. Así es como se usa:</p><ol class="prose-ordered-list"><li><p>En acción (ejemplo de Gmail): Supongamos que responde a un correo electrónico. En lugar de escribir el mensaje completo, simplemente escriba el acceso directo (p. ej., /reunión) en el cuerpo del correo. Su fragmento predefinido aparecerá al instante, lo que le ahorrará tiempo y esfuerzo.</p></li><li><p>Versatilidad: Blaze funciona no solo en Gmail, sino también en otras plataformas basadas en Chrome, como Google Docs, ChatGPT e incluso en redes sociales. Tenga en cuenta que Blaze podría no funcionar en aplicaciones sin conexión como Microsoft Word o Excel.</p></li></ol><p>Utilice estos fragmentos en su trabajo diario buscando todos los mensajes más comunes que envía y creando atajos de teclado para ellos.</p><p><strong>Consejo</strong> : Actualiza y optimiza periódicamente tus fragmentos para que coincidan con tus tareas más frecuentes. Elimina los fragmentos antiguos o que no uses para dar cabida a los nuevos, garantizando así que tu flujo de trabajo se mantenga eficiente y ordenado.</p><p><strong>Esto es lo que has aprendido.</strong><br>Aprendiste sobre Text Blaze y cómo crear fragmentos efectivos para ahorrarte horas de escritura y frustración.</p>', 19, '2025-09-02 00:12:49.925963', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 00:12:49.925963', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('cb408fef-d0ac-419b-8d4b-64c1e51eac64', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'La respuesta de Google a ChatGPT: una guía para principiantes sobre Gemini', NULL, '<p>Ahora que ya conoces mejor a Claude, veamos la respuesta de Google al mundo de los grandes modelos lingüísticos. Comenzó con un modelo llamado "Bard", pero rápidamente evolucionó a "Gemini", y desde entonces Google ha lanzado impresionantes productos de IA.</p><p>En esta lección, le mostraremos cómo usar Gemini, desde comprender qué es hasta acceder a él y usarlo de manera efectiva para tareas con las que otros modelos de lenguaje podrían tener dificultades.&nbsp;</p><p>Al finalizar, estará listo para usar Gemini para tareas especializadas que requieren gran precisión.</p><p>¡Vamos!</p><h3><strong>Aspectos destacados clave:</strong></h3><p><strong>Rendimiento superior en contextos largos</strong></p><p>Gemini 2.5 Pro sigue destacando en tareas que requieren mucha investigación, al comprender documentos extensos y complejos con una precisión excepcional. Actualmente admite una ventana de contexto de 1 millón de tokens, con planes de ampliarla próximamente a 2 millones.</p><p><strong>Razonamiento de “pensamiento profundo” de nivel superior</strong></p><p>Basándose en métodos de cadena de pensamiento anteriores, Gemini 2.5 Pro introduce un razonamiento paso a paso mejorado, lo que mejora los resultados en desafíos matemáticos, científicos y de codificación.</p><p><strong>Multimodalidad nativa</strong></p><p>Al igual que Gemini 1.5 Pro, 2.5 Pro maneja de forma nativa texto, audio, imágenes, videos e incluso repositorios de código.</p><p><strong>Puntos de referencia y rendimiento excepcionales</strong></p><p>Según pruebas y benchmarks oficiales, Gemini 2.5 Pro lidera en razonamiento, programación, matemáticas y ciencias, con excelentes resultados en GPQA, AIME 2025, SWE-Bench y Humanity''s Last Exam. En LMArena, mantiene una ventaja de aproximadamente 39 puntos ELO sobre los modelos anteriores.</p><h3><strong>Cómo acceder y usar Gemini 1.5 Pro: guía paso a paso</strong></h3><p><strong>1. Accede a Google AI Studio</strong></p><ul class="prose-bullet-list"><li><p>Visita el sitio web <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://ai.google.dev/aistudio"><strong>de Google AI Studio</strong></a> .</p></li><li><p>Haga clic en el botón "Iniciar sesión en Google AI Studio" e inicie sesión con su cuenta de Google.</p></li><li><p>Si no tienes una cuenta de Google, crea una primero.</p></li><li><p>Una vez que haya iniciado sesión, será llevado a la interfaz principal de Google AI Studio.</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-36.png" alt="imagen-36.png" width="800" height="480"><p></p><p><strong>2. Seleccione Gemini 2.5 Pro</strong></p><ul class="prose-bullet-list"><li><p>En la esquina superior derecha, busque el menú desplegable denominado "Modelos".</p></li><li><p>Desplácese por la lista y seleccione "gemini-2.5-pro".</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/Screenshot%202025-08-07%20at%202.00.05%E2%80%AFPM.png" alt="Captura de pantalla del 7 de agosto de 2025 a las 14:00.05.png" width="1173" height="627"><p></p><p><strong>3. Personaliza la configuración de tu carrera</strong></p><ul class="prose-bullet-list"><li><p>En el lado derecho de la interfaz, verá un panel llamado "Configuración de ejecución". Aquí puede ajustar el modelo según sus necesidades específicas:</p></li></ul><ul class="prose-bullet-list"><li><p>Temperatura: Controla la aleatoriedad de las respuestas. Los valores más bajos producen respuestas más precisas, mientras que los más altos aumentan la creatividad.</p></li><li><p>Recuento de tokens: ajuste la longitud del texto generado según el nivel de detalle que desee que tenga la respuesta.</p></li><li><p>Configuración de seguridad: establezca límites de contenido para garantizar que la IA se alinee con sus preferencias.</p></li></ul><p>Experimente con estas configuraciones para encontrar la mejor combinación para sus tareas.</p><p><strong>4. Agregar instrucciones del sistema (opcional)</strong></p><ul class="prose-bullet-list"><li><p>Para un control más específico, puede proporcionar instrucciones del sistema para guiar el comportamiento de la IA.</p></li><li><p>Busque el campo "Instrucciones del sistema" en la parte superior de la interfaz e introduzca instrucciones claras y concisas. Por ejemplo:<br><em>"Usted es un asistente de IA especializado en simplificar conceptos científicos complejos para el público general".</em></p></li><li><p>Estas instrucciones persistirán durante las interacciones a menos que se modifiquen.</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-38.png" alt="imagen-38.png" width="800" height="480"><p></p><p><strong>5. Comience a generar con Gemini 2.5 Pro</strong></p><ul class="prose-bullet-list"><li><p>Ingrese su consulta, solicitud o tarea en el área de entrada principal.</p></li><li><p>Haga clic en Ejecutar para generar respuestas.</p></li><li><p>Revise el resultado, refine sus indicaciones o ajuste la configuración para optimizar.</p></li></ul><p><strong>Consejo</strong> : Puedes subir libros completos a Gemini 2.5 Pro y hacer preguntas detalladas sobre el contenido. El modelo es excelente para recuperar información precisa de grandes conjuntos de datos, lo que lo hace perfecto para investigaciones exhaustivas.</p><p><strong>Lo que has aprendido</strong></p><p>Ahora que comprende cómo acceder y utilizar Gemini 2.5 Pro, incluidas sus funciones y configuraciones avanzadas, está preparado para abordar tareas que exigen gran precisión y comprensión de amplios contextos.</p><p>A continuación, exploraremos los líderes de LLM de código abierto como Llama 4 y Mistral Medium 3 de Meta, y cómo se comparan en el panorama de la IA.</p>', 10, '2025-09-01 16:07:20.984169', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-01 16:07:20.984169', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('ec9a65df-416d-4db0-8a42-9368297337c6', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Convierta documentos en presentaciones atractivas con Gamma', NULL, '<p>Una de las mayores pérdidas de tiempo es reunir los materiales de presentación y luego crear una presentación en PowerPoint o diapositivas para presentar y visualizar los hallazgos.&nbsp;</p><p>Gamma está aquí para ayudarnos a crear presentaciones increíbles en segundos utilizando el poder de la IA.</p><p>En esta lección, veremos cómo usar herramientas de IA para presentaciones. Esta capacidad te permite crear presentaciones increíbles en segundos sin experiencia previa. Aprenderás qué es, cómo acceder a ella y cómo usarla eficazmente.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>¿Qué es Gamma?</p></li><li><p>Cómo acceder</p></li><li><p>Cómo usarlo de manera efectiva</p></li></ul><p>Al final, sabrás cómo generar tu próxima presentación usando IA, a partir de un único mensaje de texto.</p><p>¡Vamos!</p><h3><strong>1. ¿Qué es Gamma?</strong></h3><p>Gamma es una herramienta de presentación con IA que se incluye en la categoría de herramientas de IA para productividad. Permite generar presentaciones, documentos y sitios web visualmente atractivos a partir de la entrada de texto, lo que facilita la creación de contenido profesional sin necesidad de conocimientos de diseño.</p><img class="prose-image" src="/api/lesson-resources/0e9a6daa-092a-482c-8a3f-3ff64fb5eb36/image-1756774378957-cgefp.jpg"><h3><strong>2. ¿Cómo acceder?</strong></h3><p>Para utilizar Gamma AI, dirígete a <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://gamma.app/"><strong>Gamma</strong></a> y haz clic en el botón " <em>Registrarse</em> " para registrarte gratis.</p><p>El plan gratuito ya te permite usar casi todas sus funciones, pero si planeas usarlo extensamente o quieres más, puedes actualizar al plan Plus. Estos son los diferentes planes disponibles:</p><p>Una vez que te hayas registrado, serás dirigido a tu panel de Gamma.</p><img class="prose-image" src="/api/lesson-resources/c2995ea4-dcbf-4c14-8465-aa36c8638f29/image-1756774440301-su23vd.jpg"><h3><strong>3. ¿Cómo usarlo?</strong></h3><h2><strong>a) Primeros pasos</strong></h2><p>Haz clic en " <em>Crear nuevo (AI) </em><strong>"</strong> para crear una nueva presentación. Se te presentarán tres opciones:</p><ul class="prose-bullet-list"><li><p>Pegar en texto: crear a partir de notas, un esquema o contenido existente</p></li><li><p>Generar: crear a partir de un mensaje de una línea en unos segundos</p></li><li><p>Importar un archivo: transformar o mejorar documentos y presentaciones existentes</p></li></ul><p>Seleccionar “ <em>Generar</em> ” para este tutorial.&nbsp;</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-89.png" alt="imagen-89.png" width="800" height="480"><p></p><h2><strong>b) Describe tu presentación</strong></h2><p>Se le pedirá que proporcione detalles sobre la presentación que desea crear. Esto incluye el tema, el propósito, el público objetivo, la duración deseada y cualquier requisito o sección específica que desee incluir. Proporcione la mayor cantidad de detalles posible.</p><p>Haga clic en " <em>Generar esquema</em> " y Gamma lo creará automáticamente. Edite el contenido de las tarjetas/diapositivas según sea necesario. También puede eliminar o añadir diapositivas.</p><p>Desplácese hacia abajo para ajustar la cantidad de texto y el estilo de las imágenes generadas por IA para su presentación y haga clic en <em>"Continuar"</em> .</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-90.png" alt="imagen-90.png" width="800" height="480"><p></p><h2><strong>c) Seleccione un tema para generar</strong></h2><p>Gamma ofrece una selección de plantillas prediseñadas. Explore las opciones y seleccione la que mejor se adapte al tema y estilo de su presentación.</p><p>Después de proporcionar los detalles necesarios y seleccionar un tema, haga clic en el botón " <em>Generar</em> ".</p><p>Espere unos segundos hasta que se cargue la presentación de diapositivas completa.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-91.png" alt="imagen-91.png" width="800" height="480"><p></p><h2><strong>d) Personalizar y descargar</strong></h2><p>Tras la generación inicial, Gamma le presentará el borrador de su presentación. Dedique un tiempo a revisar cada diapositiva para comprobar su precisión y calidad general.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-92.png" alt="imagen-92.png" width="800" height="480"><p></p><p>Luego puedes usar el asistente de IA para ajustar el texto de la diapositiva o agregar más tarjetas generadas por IA.</p><p>En el menú de herramientas de la derecha, consulte las herramientas de edición integradas para personalizar aún más las diapositivas, ajustando el contenido, el formato y los elementos de diseño según sea necesario.</p><p>Cuando esté listo, haga clic en los tres puntos “…” y exporte su presentación en el formato deseado (por ejemplo, PowerPoint, PDF) para compartir o presentar.</p><p>Con esto, Gamma ahora puede generar presentaciones de diapositivas completas para usted a partir de un único mensaje de texto, y usted puede editar y agregar más detalles desde el borrador de la presentación perfectamente diseñada (si es necesario).&nbsp;</p><p><strong>Consejo útil:&nbsp;</strong> puedes crear carruseles de LinkedIn increíbles utilizando la orientación de vista amplia y exportando tu presentación como un archivo PDF.&nbsp;</p><p><strong>Esto es lo que has aprendido.</strong><br>Ahora puedes crear presentaciones increíbles en segundos.</p>', 21, '2025-09-02 00:50:28.213152', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 00:50:28.213152', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('869c2488-8846-48dc-acda-aabd892a2353', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Hable en lugar de escribir con Voice In', NULL, '<p>Escribir es increíblemente lento: solemos hablar tres veces más rápido que escribir. Nuestro mundo se encamina hacia una etapa en la que pasamos del pensamiento al habla y a la acción.&nbsp;</p><p>Si utilizas constantemente el navegador Chrome para escribir, hay una forma de recuperar tiempo escribiendo mucho más rápido con tu voz.&nbsp;</p><p>En esta lección, veremos cómo usar herramientas de IA para la traducción de voz a texto. Esta capacidad de dictar tus pensamientos mientras trabajas puede ayudarte a automatizar tus tareas diarias incluso si eres principiante.</p><p>Al final, sabrás qué son "In Voice" y "BetterDictation", cómo acceder a ellos y comenzar a escribir con tu voz.&nbsp;</p><p>¡Vamos!</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Extensión de Chrome para convertir voz a texto</p></li><li><p>Cómo dictar tu discurso: paso a paso</p></li><li><p>BetterDictation: paso a paso</p></li></ul><h2><strong><br></strong><span style="font-size: 28px;"><strong>Dictado de voz a texto para Chrome</strong></span></h2><p>Ahorra tiempo y aumenta tu eficiencia dictando texto con tu voz directamente en Google Chrome con la extensión de dictado de voz a texto. Ya sea que estés redactando correos electrónicos, chateando con IA o trabajando en documentos, esta herramienta es la solución de voz a texto más precisa que he encontrado.</p><h3><strong>1. Instalar la extensión de Chrome</strong></h3><p>Para empezar a usar Voice-in Speech-to-Text, primero ve a la Chrome Web Store. Busca " <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://chromewebstore.google.com/detail/voice-in-speech-to-text-d/pjnefijmagpdjfhhkpljicbbpicelgko"><strong>Voice-in Speech-to-Text Dictation</strong></a> ". Es una extensión muy bien valorada, con casi 2000 valoraciones y un promedio de 4,4 estrellas.</p><p>Haz clic en el botón "Añadir a Chrome" y confirma haciendo clic en "Añadir extensión". Una vez instalada, ancla la extensión a la barra de herramientas de Chrome para acceder fácilmente. Para ello, haz clic en el icono del rompecabezas en la esquina superior derecha de Chrome y selecciona el icono de la chincheta junto a "Convertir voz a texto".</p><h3><strong>2. Activar la extensión</strong></h3><p>Una vez instalada, activa la extensión haciendo clic en el icono de entrada de voz en la barra de herramientas. La extensión empezará a captar tu voz y a convertirla en texto.</p><h3><strong><br>3. Dicte su texto</strong></h3><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-93.png" alt="imagen-93.png" width="800" height="480"><p></p><p>Ahora puedes dictar cualquier texto en Google Chrome. Por ejemplo, abre un documento o una ventana de chat y empieza a hablar. Aquí tienes un ejemplo:</p><p><em>Eres un excelente curador de arte y experto en marcas. Busco renovar mi marca con ideas originales y creativas. Mis colores son el morado y el azul, y mi logo dice "Lyle" como apodo. ¿Podrías proponerme un par de ideas y enumerarlas en viñetas, incluyendo también una imagen que represente esta nueva visión de marca?</em></p><p>Una vez que haya terminado de dictar, simplemente deje de hablar y la herramienta dejará de escribir.</p><p>Lo que me gusta de Voice In es que el texto se escribe a medida que hablas, por lo que puedes hablar y adaptarte sobre la marcha.&nbsp;</p><h3><strong><br>4. Revisar y editar</strong></h3><p>Después de dictar, revise la precisión del texto. La función de voz a texto es bastante precisa, pero puede que se requieran pequeños cambios, como ajustes de mayúsculas y puntuación. Use esta función para correos electrónicos, documentos o incluso chats con IA para maximizar la productividad.<br><br><strong>Consejo profesional:</strong> Experimente con diferentes patrones de voz y comandos (por ejemplo, "punto" para un punto, "coma" para la puntuación) para obtener los mejores resultados.</p><p></p><p>Para aquellos que quieran dictar en todas sus aplicaciones, tenemos una alternativa para ustedes más adelante en esta lección. (exclusiva para MacOS)</p><h3><strong>BetterDictation: paso a paso</strong></h3><p>Si desea una herramienta de dictado de voz a texto que funcione en todas las aplicaciones de su dispositivo MacOS, la más popular es " <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://betterdictation.com/"><strong>BetterDictation</strong></a> ".</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-94.png" alt="imagen-94.png" width="800" height="480"><p></p><h3><strong>1. Primeros pasos</strong></h3><p>Visita el sitio web de BetterDictation para descargar la aplicación exclusiva para macOS. Haz clic en "Descargar para macOS" para iniciar la instalación. La compatibilidad con Windows está prevista para el futuro.</p><h3><strong>2. Instalar y configurar preferencias</strong></h3><p>Instala la aplicación en tu Mac y abre el panel de preferencias mediante el icono de la barra de menú. Personaliza la configuración:</p><ul class="prose-bullet-list"><li><p>Idioma: seleccione su idioma de dictado preferido.</p></li><li><p>Modelo de IA: elige entre modelos como Medio rápido o Grande rápido, equilibrando precisión y velocidad.</p></li><li><p>Configuración general: ajuste las funciones de pulsar para hablar, los marcadores de posición de escucha y los atajos de dictado para adaptarlas a su flujo de trabajo.</p></li></ul><h3><strong>3. Empieza a dictar</strong></h3><p>Con la configuración configurada, abra cualquier aplicación de entrada de texto (p. ej., Notas, Slack), presione la tecla de acceso directo (p. ej., Ctrl + V) para activar el modo de escucha y comience a hablar. BetterDictation transcribirá su discurso a texto con gran precisión, gestionando la puntuación y el formato de forma intuitiva.</p><h3><strong>4. Probar y adaptar</strong></h3><p>Pruebe la herramienta en diferentes escenarios, comenzando con oraciones simples y avanzando a entradas más complejas. Si encuentra problemas, ajuste la configuración del modelo de IA o la velocidad del habla para una mayor precisión.</p><p><strong>Consejo:</strong> Combina BetterDictation con herramientas como Voice In para Chrome para una configuración de dictado completa en todas las aplicaciones, garantizando un rendimiento óptimo tanto en línea como sin conexión.<br><br><strong>Esto es lo que has aprendido.</strong><br>Aprendiste a trabajar tres veces más rápido transcribiendo tu voz a texto y a no perder tiempo escribiendo.</p>', 22, '2025-09-02 00:56:26.649117', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 00:56:26.649117', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('51bedbd8-80f6-448a-8c3a-ffe654e82a55', 'e432692a-7d0a-4e10-846f-ba57c041e96c', '¿Qué es la IA?', NULL, '<p>¿Alguna vez has entrado en una sala donde todos hablan en código? Así es como se siente a veces la IA.</p><p>¡Bienvenido a la lección de terminología de IA!</p><p>En esta lección, le presentaremos la terminología esencial de IA.</p><p>No te preocupes, no buscamos que domines el tema. Nuestro objetivo es simplemente familiarizarte con la jerga común que encontrarás en el mundo de la IA.<br><br>Guárdalo en tus favoritos. Tenlo a mano. Y cuando tengas dudas sobre algún concepto, sabrás exactamente dónde consultarlo.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Inteligencia artificial (IA)</p></li><li><p>Aprendizaje automático (ML)</p></li><li><p>Aprendizaje profundo</p></li><li><p>IA generativa</p></li><li><p>Modelos de lenguaje grandes (LLM)</p></li><li><p>IA de código abierto e IA de código cerrado</p></li><li><p>Redes neuronales</p></li><li><p>Envoltorio de IA</p></li><li><p>Agentes de IA</p></li><li><p>Inteligencia Artificial General (IAG)</p></li><li><p>Superinteligencia artificial (ASI)</p></li></ul><p></p><p><strong>La mala noticia:</strong><br>hay mucho que recordar si eres un principiante absoluto.</p><p><strong>La buena noticia:</strong><br>hemos creado hojas de trucos gratuitas que puedes imprimir o guardar en tu escritorio y tenerlas a mano hasta que ya no las necesites.</p><p>Al finalizar esta lección, tendrá mayor fluidez al analizar la IA y estará preparado para el material práctico que viene a continuación, así como para nuestro boletín The Rundown AI.</p><p>¡Vamos a saltar!</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/ai.png" alt="ai.png" width="800" height="600"><h2><strong><br>Inteligencia artificial (IA)</strong></h2><p>La inteligencia artificial (IA) permite a los sistemas informáticos realizar tareas que normalmente requieren inteligencia humana, como reconocer imágenes, comprender el lenguaje y hacer predicciones. La IA utiliza algoritmos que aprenden de los datos, mejorando así su rendimiento con el tiempo.</p><h3><strong>Usos comunes de la IA:</strong></h3><ul class="prose-bullet-list"><li><p><strong>Chatbots</strong> : la IA permite respuestas naturales de texto o voz.</p></li><li><p><strong>Coches autónomos</strong> : la IA procesa datos de los sensores para conducir de forma autónoma.</p></li><li><p><strong>Recomendaciones</strong> : La IA sugiere contenido según el historial del usuario. Por ejemplo, Netflix recomienda películas que podrían gustarte.&nbsp;</p></li><li><p><strong>Finanzas</strong> : la IA detecta patrones y automatiza el comercio.</p></li><li><p><strong>Creación de contenido</strong> : La IA genera texto, imágenes y música. Por ejemplo, convierte un texto en un video.&nbsp;</p></li></ul><p>La IA automatiza tareas que antes requerían cognición humana, haciendo posible reconocer patrones, predecir resultados e interactuar a través del lenguaje.</p><p>La IA se expande rápidamente, automatizando tareas que antes se consideraban imposibles. Manténgase al tanto de nuestros correos electrónicos diarios para conocer los últimos avances en IA.</p><h2><strong>Aprendizaje automático (ML)</strong></h2><p>El aprendizaje automático, un tipo de IA, permite que los sistemas aprendan y mejoren a partir de los datos sin necesidad de programación explícita. Por ejemplo, alimentar a un sistema con imágenes de gatos le enseña a reconocerlos.</p><p><strong>Puntos clave:</strong></p><ul class="prose-bullet-list"><li><p>Los sistemas aprenden patrones a partir de datos, no de reglas preprogramadas.</p></li><li><p>Más datos de calidad mejoran el rendimiento de la tarea.</p></li><li><p>A diferencia de la programación tradicional basada en reglas, el aprendizaje automático se basa en datos y es probabilístico.</p></li></ul><p>El aprendizaje automático permite a la IA gestionar tareas complejas aprendiendo de los datos en lugar de depender de reglas predefinidas.</p><h3><strong>El aprendizaje automático tiene una amplia gama de usos, entre ellos:</strong></h3><ul class="prose-bullet-list"><li><p>Cómo identificar el correo no deseado</p></li><li><p>Detección de actividad de bots</p></li><li><p>Recomendar contenido a los usuarios en plataformas de streaming y aplicaciones de redes sociales</p></li><li><p>Proporcionar resultados de motores de búsqueda</p></li><li><p>Reconocimiento de voz e imágenes</p></li><li><p>Chatbots y traducción de idiomas</p></li><li><p>Investigación médica</p></li></ul><h2><strong>Aprendizaje profundo</strong></h2><p>El aprendizaje profundo, un tipo de aprendizaje automático, detecta patrones complejos e imita el pensamiento humano. Es la base de la IA, como los modelos de lenguaje, los generadores de imágenes y los coches autónomos.</p><h3><strong><br>El aprendizaje profundo es una técnica clave detrás de muchas innovaciones importantes en IA en la actualidad, entre ellas:</strong></h3><ul class="prose-bullet-list"><li><p>Modelos de lenguaje grandes (LLM) como <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://chat.openai.com/"><strong>ChatGPT</strong></a> que pueden generar texto conversacional.</p></li><li><p>Generadores de imágenes como <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://openai.com/dall-e-2"><strong>DALL-E</strong></a> que pueden crear imágenes realistas a partir de indicaciones de texto.</p></li><li><p>Sistemas de coches autónomos que interpretan datos visuales para conducir con seguridad.</p></li><li><p>Modelos predictivos que obtienen información de grandes conjuntos de datos históricos.</p></li></ul><h3><strong>Aplicaciones del aprendizaje profundo en el mundo real:</strong></h3><ul class="prose-bullet-list"><li><p>Asistentes de voz que entienden el habla natural.</p></li><li><p>Investigación médica que analiza conjuntos de datos de salud complejos.</p></li><li><p>Procesamiento del lenguaje natural para traducción y análisis de sentimientos.</p></li><li><p>Reconocimiento de imágenes para identificar objetos en fotografías.</p></li></ul><h3><strong>En resumen</strong></h3><p>El aprendizaje profundo permite que la IA realice tareas similares a las humanas al aprender de grandes cantidades de datos, lo que impulsa gran parte de los avances actuales de la IA.</p><h2><strong>IA generativa</strong></h2><p>La IA generativa utiliza aprendizaje profundo para crear texto, imágenes y audio a partir de indicaciones. Entrenada con conjuntos de datos masivos, genera resultados realistas y de alta calidad.</p><p>Un modelo de generación de texto aprende la estructura del lenguaje a partir de grandes conjuntos de datos, lo que le permite generar respuestas naturales. Si bien su creatividad es objeto de debate, estos modelos a menudo pueden igualar o superar a los humanos en algunas tareas creativas.</p><h3><strong>Algunos ejemplos conocidos de IA generativa incluyen:</strong></h3><ul class="prose-bullet-list"><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://chat.openai.com/"><strong>ChatGPT</strong></a> , <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://claude.ai/"><strong>Claude</strong></a> y <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://gemini.google.com/app"><strong>Gemini</strong></a> para la generación de texto conversacional.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://openai.com/dall-e-2"><strong>DALL-E</strong></a> , <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://midjourney.com/"><strong>Midjourney</strong></a> y Stable Diffusion para crear imágenes a partir de descripciones de texto.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://openai.com/research/musenet"><strong>MuseNet</strong></a> y <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://suno.ai/"><strong>Suno</strong></a> para componer música original a partir de texto. <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://elevenlabs.io/"><strong>ElevenLabs</strong></a> para crear voz a partir de texto.</p></li></ul><img class="prose-image" src="https://lh7-rt.googleusercontent.com/docsz/AD_4nXfvxU0PB7rJrccd0dGnfoeIsCIdq5zQW_gaPIHgTKSEaosJAuZkuBPu5ZuFGSwVlYpyxDFzdr5Q4kdsXHVR9C-rl7y05PHwLI2YtcR86BvBrmNAGDChk-58R--BkoHMCa6Tgc3Myw?key=whQNRL_GUd20THdzlF5GZA" width="1119" height="747"><p>Beneficios potenciales de la IA generativa:</p><ul class="prose-bullet-list"><li><p>Ideación de contenido más rápida para creativos</p></li><li><p>Conversaciones de chatbot más naturales</p></li><li><p>Procesamiento de datos de investigación para acelerar los descubrimientos</p></li><li><p>Mejorar las respuestas de los motores de búsqueda</p></li><li><p>Nuevas formas de entretenimiento</p></li></ul><p>Por supuesto, también existen riesgos de sesgo, desinformación y casos de uso inadecuados. Pero las capacidades de los modelos generativos siguen creciendo.</p><h2><strong>Modelos de lenguaje grandes (LLM)</strong></h2><p>Los LLM son sistemas de IA entrenados con grandes cantidades de datos de texto para reconocer y generar texto con una apariencia similar a la humana. Por ejemplo, <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://openai.com/research/gpt-4"><strong>GPT-4</strong></a> , que impulsa ChatGPT, se entrenó con más de 45 GB de datos. La calidad de los datos es crucial para la eficacia, no solo la cantidad.</p><h3><strong>Algunos otros LLM populares incluyen:</strong></h3><img class="prose-image" src="https://app.therundown.ai/api/media/file/llm.png" alt="llm.png" width="1920" height="436"><ul class="prose-bullet-list"><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://gemini.google.com/"><strong>Géminis</strong></a> (Google)</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://www.llama.com/"><strong>Llama</strong></a> (Meta)</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://claude.ai/"><strong>Claude</strong></a> (Antrópico)</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://copilot.microsoft.com/"><strong>Copiloto</strong></a> (Microsoft)</p></li></ul><h2><strong>IA de código abierto</strong></h2><p>La IA de código abierto tiene código público, lo que permite transparencia, personalización e innovación impulsada por la comunidad. Reduce las barreras para las startups y fomenta la creatividad. Aunque actualmente está rezagada respecto a la IA de código cerrado, está progresando rápidamente.</p><p></p><h3><strong>Proyectos populares de IA de código abierto:</strong></h3><img class="prose-image" src="https://app.therundown.ai/api/media/file/popular.png" alt="popular.png" width="1920" height="444"><ul class="prose-bullet-list"><li><p><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://openai.com/index/introducing-gpt-oss/"><strong>GPT-oss</strong></a> : OpenAI lanzó sus modelos de código abierto: gpt-oss-120b y gpt-oss-20b, dos modelos de lenguaje de última generación y peso abierto que ofrecen un sólido rendimiento en el mundo real a bajo costo.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://tensorflow.org/"><strong>TensorFlow</strong></a> : un marco de aprendizaje automático de código abierto creado por Google que permite construir y entrenar redes neuronales.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://pytorch.org/"><strong>PyTorch</strong></a> : Una biblioteca creada por Facebook para el aprendizaje profundo y el desarrollo de IA. El código fuente se puede personalizar.</p></li><li><p>La familia de modelos de lenguaje grandes (LLM) preentrenados y ajustados de código abierto de <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://www.llama.com/"><strong>Llama 4 Meta, lanzada en 2024 (última versión)</strong></a></p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://huggingface.co/"><strong>Hugging Face</strong></a> : proporciona acceso a muchos modelos de procesamiento de lenguaje natural de código abierto para el análisis de texto.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://stability.ai/"><strong>Difusión estable</strong></a> : un modelo de IA de texto a imagen de código abierto de Stability AI.</p></li></ul><h3><strong>Los beneficios de la IA de código abierto:</strong></h3><ul class="prose-bullet-list"><li><p><strong>Transparencia</strong> : Otros pueden auditar y mejorar los algoritmos.</p></li><li><p><strong>Personalización</strong> : el código se puede adaptar a diferentes necesidades.</p></li><li><p><strong>Colaboración comunitaria</strong> : los proyectos públicos permiten la innovación colaborativa e impulsan el progreso de la IA.</p></li><li><p><strong>Barreras de entrada más bajas</strong> : las empresas emergentes o los desarrolladores pueden basarse en modelos abiertos en lugar de desarrollar sistemas propietarios.</p></li></ul><h2><strong>IA de código cerrado</strong></h2><p>La IA de código cerrado mantiene la privacidad de su código para preservar las ventajas competitivas, la comercialización y la seguridad. Si bien ofrece confidencialidad, carece de transparencia y personalización, y puede frenar la innovación.</p><h3><strong>Los principales modelos de IA de código cerrado incluyen:</strong></h3><img class="prose-image" src="https://app.therundown.ai/api/media/file/major.png" alt="mayor.png" width="1920" height="342"><p></p><ul class="prose-bullet-list"><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://openai.com/index/hello-gpt-4o/"><strong>GPT-4o</strong></a> de OpenAI</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://gemini.google.com/"><strong>Géminis</strong></a> de Google</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://claude.ai/"><strong>Claude</strong></a> por Anthropic</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://coral.cohere.com/"><strong>Comando R+</strong></a> de Cohere</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://www.ibm.com/watsonx"><strong>Watson</strong></a> de IBM</p></li></ul><h3><strong><br>Razones por las que algunas empresas mantienen una IA de código cerrado:</strong></h3><ul class="prose-bullet-list"><li><p><strong>Ventaja competitiva&nbsp;</strong> : mantener los modelos en secreto evita la copia.</p></li><li><p><strong>Comercialización</strong> : Los sistemas cerrados pueden monetizarse en lugar de compartirse libremente.</p></li><li><p><strong>Preocupaciones legales</strong> : cómo evitar problemas con licencias abiertas.</p></li><li><p><strong>Seguridad</strong> que no expone vulnerabilidades potenciales.</p></li></ul><h3><strong><br>Las ventajas y desventajas del código abierto incluyen:</strong></h3><ul class="prose-bullet-list"><li><p><strong>Menos transparencia</strong> : no se pueden inspeccionar para detectar sesgos o fallas.</p></li><li><p><strong>Personalización limitada</strong> : los usuarios no pueden adaptar el código para nuevos casos de uso.</p></li><li><p><strong>Slowerinnovation</strong> – El progreso depende únicamente de las empresas privadas.</p></li></ul><h2><strong><br>Redes neuronales</strong></h2><p>Las redes neuronales son la base del aprendizaje profundo, imitando la estructura del cerebro. Procesan datos a través de capas de nodos, aprendiendo patrones y tomando decisiones. Se utilizan en el reconocimiento de imágenes, el procesamiento del lenguaje y los vehículos autónomos.</p><p>En el reconocimiento de imágenes, una red neuronal tiene nodos de entrada activados por píxeles. Las capas ocultas extraen características como curvas o bordes, y la capa de salida predice la clase de imagen. Al ajustar los pesos durante el entrenamiento, las redes neuronales aprenden patrones complejos. Más datos significan mayor precisión.</p><h3><strong>Ventajas clave de las redes neuronales:</strong></h3><ul class="prose-bullet-list"><li><p>Capacidad para manejar datos diversos y no estructurados, como imágenes, texto o lecturas de sensores.</p></li><li><p>Descubrir patrones latentes que son demasiado complejos para las reglas codificadas por humanos</p></li><li><p>Mejorar continuamente a través de la experiencia sin reprogramar</p></li></ul><h3><strong>Aplicaciones de las redes neuronales:</strong></h3><ul class="prose-bullet-list"><li><p>Tareas de visión artificial como el reconocimiento facial</p></li><li><p>Procesamiento del lenguaje natural para chatbots o traducción</p></li><li><p>Vehículos autónomos que analizan datos de sensores en tiempo real</p></li></ul><h2><strong>Envoltorio de IA</strong></h2><p>Un contenedor de IA es una herramienta que optimiza un modelo de IA existente para tareas específicas, como optimizar GPT-4 para la redacción de textos de marketing. Los contenedores simplifican su uso, mejoran el rendimiento e integran la IA en los flujos de trabajo.</p><p>Un contenedor de IA puede optimizar GPT-4 para tareas como la redacción de textos de marketing. Ajusta el modelo para que sea excelente en la creación de textos publicitarios, descripciones de productos y más.</p><h3><strong>Beneficios clave de los envoltorios de IA:</strong></h3><ul class="prose-bullet-list"><li><p><strong>Especialización</strong> : los wrappers permiten adaptar modelos de IA amplios para aplicaciones específicas.</p></li><li><p><strong>Simplificación</strong> : Pueden proporcionar interfaces fáciles de usar para interactuar con IA compleja.</p></li><li><p><strong>Mejora</strong> : datos adicionales y ajustes pueden mejorar el rendimiento de tareas específicas.</p></li><li><p><strong>Integración</strong> : los wrappers pueden ayudar a incorporar capacidades de IA en software y flujos de trabajo existentes.</p></li></ul><p>Muchas de las herramientas y servicios basados en IA que utilizamos hoy en día son, en realidad, envoltorios basados en modelos fundamentales de organizaciones como OpenAI, Google y Meta. El envoltorio añade una capa de personalización y usabilidad.</p><h3><strong>Algunos ejemplos de envoltorios de IA incluyen:</strong></h3><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-8.png" alt="imagen-8.png" width="1920" height="548"><p></p><ul class="prose-bullet-list"><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://midjourney.com/"><strong>Midjourney</strong></a> Un generador de arte de IA que afina los modelos de imágenes para crear elementos visuales artísticos a partir de indicaciones de texto.</p></li><li><p><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="http://Copy.ai"><strong>Copy.ai</strong></a> Un asistente de escritura que adapta modelos de lenguaje para crear contenidos y textos de marketing.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://speechify.com/"><strong>Speechify</strong></a> : una aplicación que aprovecha los modelos de voz de IA para lograr una narración de texto a voz realista.</p></li><li><p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://replika.com/"><strong>Replika</strong></a> : un compañero de IA que afina los modelos conversacionales para participar en chats.</p></li></ul><h2><strong><br>Agentes de IA (Agentic AI)</strong></h2><p>La IA agentica (agentes de IA) puede <strong>planificar, actuar y adaptarse</strong> en múltiples pasos sin necesidad de intervención humana en cada etapa.</p><p>Pueden:</p><ul class="prose-bullet-list"><li><p>Divida los objetivos grandes en pasos más pequeños</p></li><li><p>Herramientas de llamada y API</p></li><li><p>Recuperar datos</p></li><li><p>Realizar acciones en otras aplicaciones automáticamente</p></li></ul><p>Piense en ellos como <strong>trabajadores autónomos de IA</strong> a los que puede asignar proyectos.</p><h2><strong>Inteligencia Artificial General (IAG)</strong></h2><p>La IAG es una IA futura capaz de realizar cualquier tarea intelectual que un humano pueda realizar, con razonamiento, aprendizaje y creatividad similares a los humanos. A diferencia de la IA limitada actual (ANI), la IAG sigue siendo teórica, y su viabilidad y plazos aún son objeto de debate.</p><h3><strong>Capacidades de la IAG</strong></h3><ul class="prose-bullet-list"><li><p><strong>Inteligencia:</strong> La IA general podría igualar o superar la inteligencia humana en todos los dominios.</p></li><li><p><strong>Conciencia:</strong> Existe debate sobre si la IA general necesita conciencia de la máquina o autoconciencia.</p></li><li><p><strong>Razonamiento y sentido común:</strong> las opiniones varían en cuanto a hasta qué punto la IA general debe reflejar el razonamiento y el sentido común humanos.</p></li><li><p><strong>Encarnación:</strong> Algunos creen que la IA general requiere una forma física para interactuar como los humanos, mientras que otros piensan que podría existir en software.</p></li></ul><p>A pesar de estas diferentes perspectivas, hay algunas características generalmente aceptadas que un sistema AGI probablemente poseería, tales como:</p><ul class="prose-bullet-list"><li><p><strong>Razonamiento:</strong> Capacidad de pensar de forma abstracta y resolver nuevos problemas.</p></li><li><p><strong>Aprendizaje:</strong> Capacidad de adquirir nuevos conocimientos a través de la experiencia.</p></li><li><p><strong>Creatividad:</strong> Capacidad de generar ideas y soluciones originales.</p></li><li><p><strong>Adaptabilidad:</strong> Ajuste efectivo a nuevos entornos y desafíos.</p></li><li><p><strong>Inteligencia general:</strong> inteligencia amplia en diversos dominios, no solo tareas especializadas.</p></li></ul><p>La IA general (IAG) aún es teórica y aún no existe. La IA actual, incluyendo ChatGPT, sigue siendo limitada, destacando en tareas específicas, pero careciendo de una inteligencia general comparable a la humana.</p><h3><strong>Diferencia entre AGI y ANI</strong></h3><p>Empresas como Google y Meta trabajan en la IA general, pero, a fecha de 2024, no se ha logrado. Mientras tanto, los sistemas ANI destacan en tareas específicas y su uso está muy extendido.</p><h3><strong>Debate sobre la IAG</strong></h3><p>El camino hacia la IAG, si es que es posible, sigue siendo incierto y objeto de intensos debates. Investigadores y filósofos comparten diversas opiniones sobre cuestiones clave como:</p><ul class="prose-bullet-list"><li><p><strong>Viabilidad:</strong> ¿Es posible lograr la IAG y en qué plazo?</p></li><li><p><strong>Enfoques:</strong> ¿Qué métodos científicos son más prometedores para el desarrollo de la IAG?</p></li><li><p><strong>Riesgos:</strong> ¿Cuáles son los desafíos potenciales y cómo pueden mitigarse?</p></li><li><p><strong>Implicaciones:</strong> ¿Qué impacto tendría la IAG en la sociedad, la economía y el futuro?</p></li></ul><p>El futuro de la IAG es incierto y objeto de debate entre los expertos. A medida que la IAG avanza, la pregunta de si la IAG surgirá o no, y cuándo, sigue impulsando la investigación.</p><h2><strong>Superinteligencia artificial (ASI)</strong></h2><p>La superinteligencia artificial (ISA) supera la inteligencia humana, capaz de razonar y resolver problemas de forma independiente. A diferencia de la IA actual, la ISA superaría a los humanos, rivalizando incluso con genios históricos como Einstein.</p><h3><strong><br>Capacidades similares a las humanas de ASI</strong></h3><p>La ASI desarrollaría sus propias creencias, deseos y emociones. Podría analizar y procesar información mucho más allá de los límites humanos, realizando tareas complejas como la exploración espacial y comprendiendo las emociones con mayor precisión y eficiencia que los humanos.</p><h3><strong><br>Estado actual de ASI</strong></h3><p>ASI desarrollaría sus propias creencias y deseos, analizando datos que superan con creces la capacidad humana. Podría gestionar tareas complejas, desde la exploración espacial hasta la comprensión de las emociones, con mayor precisión y eficiencia.</p><h3><strong><br>Características de ASI</strong></h3><p>Actualmente, la IAS es teórica, y la mayor parte de la IA se limita a tareas específicas. Los investigadores creen que la inteligencia artificial general (IAG) es un paso necesario hacia la IAS.</p><h3><strong><br>Amenazas potenciales de ASI</strong></h3><p>La ASI podría revolucionar la tecnología, impulsando el progreso en campos como la medicina y la exploración espacial. Sin embargo, presenta riesgos, como la pérdida de control, la militarización o la falta de alineamiento de objetivos que podrían perjudicar a la humanidad.</p><h3><strong>Ventajas de ASI</strong></h3><p>La ASI ofrece beneficios potenciales al reducir errores, gestionar tareas riesgosas y acelerar los avances científicos, particularmente en la exploración espacial y la medicina.</p><h2><strong>Enfoques para el entrenamiento de programas de aprendizaje automático</strong></h2><p>El aprendizaje automático, un subconjunto de la IA, crea programas que analizan datos para tomar decisiones. A diferencia de los sistemas basados en reglas, el aprendizaje automático es más flexible.</p><p>Existen tres enfoques comunes para entrenar programas de ML:</p><ul class="prose-bullet-list"><li><p><strong>Aprendizaje supervisado:</strong> El programa de aprendizaje automático aprende de datos etiquetados. Por ejemplo, un filtro de spam se entrena con correos electrónicos etiquetados como "spam" o "no spam" para lograr un resultado específico.</p></li><li><p><strong>Aprendizaje no supervisado:</strong> el programa ML aprende a partir de datos no etiquetados y encuentra patrones como temas o palabras clave en correos electrónicos sin clasificar y sin un objetivo específico.</p></li><li><p><strong>Aprendizaje por refuerzo:</strong> El programa de aprendizaje automático aprende mediante ensayo y error, mejorando con la retroalimentación. Por ejemplo, una herramienta de IA conversacional mejora con la retroalimentación positiva sobre las respuestas correctas.</p></li></ul><p>Cada técnica de ML tiene sus puntos fuertes y los diseñadores de IA eligen en función de los datos disponibles y el problema a resolver.</p><h2><strong><br>¿Qué es la IA generativa?</strong></h2><p>La IA generativa crea contenido nuevo, como texto, imágenes o medios, aprovechando técnicas de aprendizaje automático, incluido el aprendizaje supervisado, no supervisado y de refuerzo.</p><p>Por ejemplo, las herramientas de IA conversacional utilizan:</p><ul class="prose-bullet-list"><li><p><strong>Aprendizaje supervisado</strong> para datos de diálogo fundamentales.</p></li><li><p><strong>Aprendizaje no supervisado</strong> para comprender los matices del lenguaje, como los coloquialismos.</p></li><li><p><strong>Aprendizaje por refuerzo</strong> para mejorar las respuestas en tiempo real.</p></li></ul><p>La IA generativa aporta beneficios a muchos campos, incluidos el marketing, el desarrollo de productos, la ingeniería, la educación, la fabricación y la I+D.</p><p>Estos beneficios incluyen:</p><ul class="prose-bullet-list"><li><p><strong>Eficiencia:</strong> Automatiza tareas rutinarias.</p></li><li><p><strong>Personalización:</strong> adapta las interacciones a las necesidades individuales.</p></li><li><p><strong>Mejores decisiones:</strong> analiza datos para obtener información valiosa.</p></li></ul><p>La IA generativa es potente, pero debe usarse con responsabilidad, teniendo en cuenta riesgos como el sesgo y la desinformación.<br><br><strong>Esto es lo que has aprendido:</strong><br>Ahora que comprendes los conceptos básicos de la IA, la IA generativa y también una posible IA general futura, veamos por qué es importante.&nbsp;</p>', 3, '2025-08-20 22:50:47.669074', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-08-20 22:50:47.669074', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('275b4e39-c4ab-48d5-9341-008c70b941dd', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Automatiza borradores de correo electrónico con Zapier', NULL, '<p>La automatización es donde la IA realmente destaca para impulsar la productividad. Ya no se trata de simples indicaciones, sino de automatizar un flujo de trabajo de principio a fin.</p><p>En esta lección, cubriremos cómo usar Zapier para automatizar sus tareas diarias como principiante total.&nbsp;</p><p>Al final, sabrás qué es Zapier, cómo acceder a él y cómo crear tu primer zap que redacta correos electrónicos para clientes potenciales que se suscriben a un boletín informativo a través de un formulario de Google.&nbsp;</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>¿Qué es Zapier?</p></li><li><p>Cómo acceder a Zapier</p></li><li><p>Cómo usar Zapier para crear tu primer zap</p></li></ul><p>¡Vamos!</p><h3><strong>1. ¿Qué es Zapier?</strong></h3><p>Zapier es una herramienta de automatización que conecta tus aplicaciones favoritas, como Gmail, Slack, Mailchimp y más de 6000. Al configurar flujos de trabajo automatizados, conocidos como Zaps, puedes ahorrar tiempo y reducir el trabajo manual.</p><p>Un <strong><u>Zap</u></strong> es un plan para una tarea que quieres repetir. Cada Zap consta de:</p><ul class="prose-bullet-list"><li><p><strong>Desencadenante</strong> : Un evento que inicia tu Zap. Por ejemplo, recibir una nueva respuesta en Formularios de Google.</p></li><li><p><strong>Acción</strong> : Un evento que un Zap realiza tras su activación. Por ejemplo, enviar un correo electrónico por Gmail.</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-95.png" alt="imagen-95.png" width="800" height="480"><p></p><h3><strong>2. Cómo acceder a Zapier</strong></h3><p>Para comenzar a utilizar Zapier:</p><ul class="prose-bullet-list"><li><p><strong>Regístrate o inicia sesión</strong> : Visita el <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://zapier.com/"><strong>sitio web de Zapier</strong></a> y haz clic en el botón "Registrarse" para registrarte gratis. Si ya tienes una cuenta, haz clic en "Iniciar sesión". Hay planes de pago, pero la versión gratuita ya te permite usar casi todas las funciones de Zapier. Aquí tienes los detalles de precios:</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-96.png" alt="imagen-96.png" width="800" height="480"><p></p><ul class="prose-bullet-list"><li><p><strong>Panel de control</strong> : después de iniciar sesión, se le dirigirá a su panel de control de Zapier, donde podrá crear y administrar sus Zaps.</p></li></ul><p></p><h3><strong>3. Cómo usar Zapier para crear un Zap</strong></h3><p><strong>a) Primeros pasos</strong></p><p>Crea un nuevo Zap mediante:</p><ul class="prose-bullet-list"><li><p>Haga clic en el botón "+ Crear" en la barra lateral izquierda y presione "Zap" para iniciar un nuevo Zap.</p></li><li><p>Verá una pantalla que le preguntará: "¿Qué le gustaría automatizar?", lo que puede ayudarle a configurar el disparador y la acción o puede hacerlo manualmente.</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-97.png" alt="imagen-97.png" width="800" height="480"><p></p><p><strong>b) Definir el disparador</strong></p><ul class="prose-bullet-list"><li><p><strong>Elige una aplicación de activación</strong> : Selecciona "Formularios de Google" como tu aplicación de activación. Esto significa que el Zap se iniciará cuando haya una nueva respuesta en tu formulario de Google.</p></li><li><p><strong>Seleccionar evento de activación</strong> : Elija "Nueva respuesta de formulario" como evento de activación. Esto especifica que el Zap se activará al enviar un nuevo formulario.</p></li><li><p><strong>Conecta tu cuenta de Google</strong> : Zapier te pedirá que conectes tu cuenta de Google. Sigue las instrucciones para que Zapier acceda a tus Formularios de Google.</p></li><li><p><strong>Configurar disparador</strong> : elija el formulario de Google específico que desea utilizar para este Zap.</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-98.png" alt="imagen-98.png" width="800" height="480"><p></p><p><strong>c) Definir la acción</strong></p><ul class="prose-bullet-list"><li><p><strong>Elige una aplicación de acción</strong> : Selecciona "Gmail" como tu aplicación de acción. Esto significa que el Zap realizará una acción en Gmail al activarse.</p></li><li><p><strong>Seleccionar evento de acción</strong> : Elija "Enviar correo electrónico" como evento de acción. Esto especifica que la acción enviará un correo electrónico.</p></li><li><p><strong>Conecta tu cuenta de Gmail</strong> : Zapier te pedirá que conectes tu cuenta de Gmail. Sigue las instrucciones para que Zapier acceda a tu cuenta de Gmail.</p></li><li><p><strong>Acción de configuración</strong> : Complete los campos de la plantilla de correo electrónico, incluyendo el destinatario, el asunto y el cuerpo. Puede usar los datos de la respuesta del formulario para personalizar el contenido del correo electrónico.</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-99.png" alt="imagen-99.png" width="800" height="480"><p></p><h3><strong>4. Finalizar y probar</strong></h3><ul class="prose-bullet-list"><li><p><strong>Prueba tu Zap</strong> : Zapier te pedirá que pruebes el Zap. Envía una respuesta de prueba a tu formulario de Google para asegurarte de que el Zap envíe el correo electrónico como se espera.</p></li><li><p><strong>Activa tu Zap</strong> : Una vez que la prueba sea exitosa, activa tu Zap. Ahora se ejecutará automáticamente al enviar una nueva respuesta de formulario.</p></li></ul><p>¡Felicitaciones! Has creado un Zap que envía un correo electrónico cada vez que alguien completa tu formulario de Google.</p><p><strong>Consejo útil:&nbsp;</strong> si te quedas atascado al crear tu zap, utiliza el <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://chatgpt.com/g/g-ERKZdxC6D-automation-consultant-by-zapier"><strong>Consultor de automatización&nbsp;</strong></a><strong> GPT&nbsp;</strong> y pide asesoramiento.</p><p><strong>Esto es lo que has aprendido.</strong><br>Has aprendido a usar Zapier para crear tu primera automatización (zap).&nbsp;</p>', 23, '2025-09-02 15:58:18.730672', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 15:58:18.730672', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('07276ccd-6155-40d7-a38e-cdcf6e57260a', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Añade atractivos videos de avatares de IA a tu contenido con HeyGen', NULL, '<p>Ahora que hemos creado algunas imágenes de IA para nuestros proyectos, vamos a ir un paso más allá creando videos y avatares de IA. Así, podremos centrarnos en las partes más importantes de nuestro trabajo.</p><p>Esto nos permite escalar nuestro marketing mediante el uso de avatares de video de IA personalizados para conectarnos con clientes potenciales e interactuar con ellos, sin necesidad de dedicar tiempo extra en ello.</p><p>Hoy te guiaremos para que comiences a usar HeyGen. Aprenderás qué es, cómo acceder a él y cómo sacarle el máximo provecho.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Registrarse en HeyGen</p></li><li><p>Acceda al estudio de IA</p></li><li><p>Personaliza, previsualiza y envía tu video</p></li></ul><p>Al final, podrás crear videos de IA personalizados, con avatares que los narrarán exactamente como quieras.</p><p>¡Vamos!</p><p></p><h3><strong>1. Regístrate en HeyGen</strong></h3><p>Dirígete al <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://heygen.com/"><strong>sitio web</strong></a> de HeyGen y haz clic en “Comience gratis”.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-115.png" alt="imagen-115.png" width="936" height="524"><p></p><p>Completa la información requerida para crear tu cuenta y recibirás algunos créditos gratuitos para explorar las capacidades de la plataforma y crear tu video de avatar de IA personalizado.</p><h3><strong>2. Accede a AI Studio</strong></h3><p>Después de registrarte e iniciar sesión, accederás al Panel de Control. Usa el menú lateral izquierdo para empezar.</p><p>Haz clic en AI Studio para acceder al centro creativo. Para un enfoque guiado, selecciona "Plantillas" para usar plantillas prediseñadas que puedes personalizar.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-116.png" alt="imagen-116.png" width="936" height="488"><p></p><p>Si tienes una visión específica, selecciona “Crear con AI Studio” para comenzar desde cero y personalizar completamente tu video.</p><h3><strong>3. Personaliza tu vídeo en el estudio</strong></h3><p>Tras seleccionar una plantilla o empezar desde cero, accederás a AI Studio, que cuenta con todas las herramientas necesarias para crear tu video de avatar de IA. Aquí tienes algunos elementos clave que puedes personalizar:</p><p>a. <strong><em>Texto e imágenes:</em></strong> agregue contenido de texto a su video agregando un cuadro de texto simple o eligiendo un cuadro de texto preformateado.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-117.png" alt="imagen-117.png" width="936" height="490"><p></p><p>b. <strong><em>Imágenes:</em></strong> agregue imágenes o videos cargándolas en “Recursos” o eligiendo entre las opciones en “Elementos”, como imágenes, objetos, formas y videos.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-118.png" alt="imagen-118.png" width="936" height="490"><p></p><p>c. <strong><em>Selección de avatares de IA:</em></strong> Elige entre varios avatares de IA, incluyendo algunos realistas en Studio Avatars, para representar tu marca. También puedes añadir tu propio avatar, pero ten en cuenta que esta función no está disponible en la prueba gratuita.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-119.png" alt="imagen-119.png" width="936" height="490"><p></p><p>d. <strong><em>Generación de scripts de IA:</em></strong> Agrega un script. Ve a "Scripts" y escribe lo que quieres que diga tu avatar de IA. Si te quedas atascado, haz clic en el logotipo de "OpenAI" para generar un script que puedes refinar.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-120.png" alt="imagen-120.png" width="936" height="490"><p></p><p>e. <strong><em>Selección de voz de IA:</em></strong> elija entre la gama de voces de IA de HeyGen en la pestaña Guiones para que coincida con su marca, audiencia o tono de mensaje.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-121.png" alt="imagen-121.png" width="936" height="490"><p></p><p>f. <strong><em>Música de fondo:</em></strong> Elige entre una biblioteca de pistas musicales de diferentes géneros. Ve a "Elementos", desplázate hasta "Música" y selecciona una pista que se adapte a tu contenido.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-122.png" alt="imagen-122.png" width="936" height="490"><p></p><h3><strong>4. Obtenga una vista previa y envíe su video</strong></h3><p>Una vez que estés satisfecho con tu video, haz clic en "Enviar" y deja que HeyGen cree tu video personalizado. En un instante, tu video de avatar de IA estará listo para compartir. 🎉</p><p><strong>Consejo útil:&nbsp;</strong> HeyGen tiene una función avanzada de clonación de avatares que te enseña cómo clonarte a ti mismo como un avatar de IA para optimizar videos personalizados a escala.</p><p><strong>Has aprendido</strong> sobre HeyGen y cómo crear tu propio avatar de IA.</p>', 24, '2025-09-02 16:04:24.54221', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 16:04:24.54221', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('90a49f78-bbd8-437b-8856-9c27307fec53', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Componga música rápidamente con Suno AI', NULL, '<p>Además de crear imágenes, vídeos e incluso juegos a partir de texto, la IA ahora puede ayudarte a crear música simplemente describiendo lo que quieres.&nbsp;</p><p>Ya sea que estés creando una canción divertida para un miembro de tu familia o usándola para impulsar tu carrera musical, la IA hace que la creación de música sea más fácil para todos.</p><p>Hoy te mostraremos cómo empezar a usar Suno AI, incluso si nunca lo has usado. Aprenderás qué es, cómo acceder a él y las mejores maneras de aprovecharlo al máximo. Al final, podrás crear tus propias canciones con solo escribir algunas ideas.</p><p>¡Vamos!</p><h3><strong>1. ¿Qué es Suno?</strong></h3><p>Suno es una plataforma basada en IA que te permite crear música de todo tipo de géneros y estilos. Te ayuda con todo, desde la composición hasta los arreglos y la producción de pistas, todo según tus preferencias.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-123.png" alt="imagen-123.png" width="936" height="486"><p></p><h3><strong>2. Cómo acceder a Suno</strong></h3><p>Para empezar a usar Suno, visita <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://suno.com"><strong>https://suno.com</strong></a> y haz clic en el botón "Registrarse" para registrarte gratis. Si ya tienes una cuenta, inicia sesión con tus credenciales. Suno ofrece diferentes planes de suscripción, incluyendo un plan gratuito que te permite generar unas 10 canciones al día.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-124.png" alt="imagen-124.png" width="936" height="478"><p></p><p>Después de iniciar sesión, serás redirigido a tu panel de Suno, donde podrás escuchar las canciones más populares de Suno y crear/administrar tus proyectos musicales.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-125.png" alt="imagen-125.png" width="936" height="486"><p></p><h3><strong>3. Cómo usar Suno para crear una canción</strong></h3><h3><strong>a) Primeros pasos</strong></h3><ul class="prose-bullet-list"><li><p><strong>Accede a la pestaña "Crear"</strong> : Desde el panel de control, haz clic en la pestaña "Crear" en la barra lateral izquierda. Esto te llevará a la interfaz de creación de canciones.</p></li><li><p><strong>Descripción de la canción</strong> : Introduce una breve descripción de la canción que quieres crear en el campo "Descripción de la canción". Por ejemplo, "Una canción de trap melódica sobre bailar contigo por última vez".</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-126.png" alt="imagen-126.png" width="936" height="486"><p></p><h3><strong>b) Opciones de personalización</strong></h3><ul class="prose-bullet-list"><li><p><strong>Elegir modelo de IA</strong> : Selecciona la versión del modelo de IA que quieres usar para crear tus canciones. La versión predeterminada y mejor disponible actualmente es la 3.5.</p></li><li><p><strong>Indicación:</strong> Describe el tipo de canción que quieres donde dice “Descripción de la canción”.</p></li><li><p><strong>Opción instrumental</strong> : si desea una pista instrumental, active el interruptor "Instrumental".</p></li><li><p><strong>Opciones personalizadas:&nbsp;</strong> si quieres tener más control sobre tu canción, puedes activar el control deslizante “Personalizado” y podrás agregar tu propia letra y título.</p></li><li><p><strong>Subir audio</strong> : también puedes subir un archivo de audio si tienes una muestra específica, pero debes ser un suscriptor Pro.</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-127.png" alt="imagen-127.png" width="800" height="480"><p></p><h3><strong>c) Creando tu canción</strong></h3><p>Una vez que hayas configurado la descripción y las opciones de tu canción, haz clic en el botón "Crear". Suno generará tu canción basándose en la información proporcionada.</p><h3><strong>4. Administrar tus canciones</strong></h3><p>Después de crear tu canción, aparecerá en la lista de canciones a la derecha de la pantalla. Allí podrás ver los detalles.</p><p>Selecciona una canción para previsualizarla. Puedes ampliarla, editar detalles, añadirla a una lista de reproducción o compartirla directamente desde este menú.</p><p>Activa la opción "Público" si quieres que tu canción sea pública. También puedes usar el menú de tres puntos para acceder a opciones adicionales como reutilizar el mensaje, compartir o descargar.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-128.png" alt="imagen-128.png" width="1974" height="1098"><p></p><p>¡Buen trabajo! Acabas de crear tu primera canción con Suno.</p><p>Suno facilita la experimentación con diferentes estilos y la creación de pistas con un sonido excepcional. Tanto si eres un músico experimentado como si estás empezando, la interfaz intuitiva y las potentes funciones de Suno te ayudarán a dar vida a tus ideas musicales.</p><p><strong>Consejo:&nbsp;</strong> Al recrear una canción popular de una celebridad, tenga cuidado al publicarla, ya que el marco regulatorio para las canciones con IA aún no se ha establecido. Además, Suno V4 se lanzó hace poco; aquí tiene una <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://x.com/sunomusic/status/1854961069300613176"><strong>publicación</strong></a> que muestra su potencial.<br><br><strong>Ya ha aprendido</strong> sobre Suno AI y cómo crear música increíble con IA.</p>', 25, '2025-09-02 16:09:01.56929', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 16:09:01.56929', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('f50923fe-84bc-4629-833c-837870018b68', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Desarrolle aplicaciones sin escribir código usando Cursor AI', NULL, '<p>Aprender a codificar solía parecer intimidante, pero ahora la IA ha hecho que el proceso sea mucho más fácil, de modo que puedes tomar una idea para una aplicación y ponerla en funcionamiento en poco tiempo.</p><p>Quedarse atascado es parte del proceso de codificación, pero Cursor AI puede ayudar ofreciendo sugerencias, completando su código e incluso corrigiendo errores en el camino.</p><p>Cursor es un editor de código inteligente que usa IA para que tu programación sea más fluida y eficiente. En esta guía, exploráremos sus tres funciones principales: Tabulador, Chat y Redactor.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>¿Qué es Cursor AI?</p></li><li><p>Cómo acceder</p></li><li><p>Explorando las funciones de IA: Pestaña, Chat y Redactor.</p></li></ul><h3><strong>¿Qué es Cursor AI?</strong></h3><p>Cursor AI mejora Visual Studio Code con IA, comprendiendo tu código, sugiriendo mejoras e incluso escribiendo por ti. Es como tener un compañero de programación, útil tanto para profesionales como para principiantes.</p><h3><strong>Cómo acceder</strong></h3><h3><strong>1. Descargue e instale Cursor</strong></h3><p>Para empezar, visita <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://www.cursor.com/"><strong>el sitio web</strong></a> de Cursor y descarga la aplicación Cursor para tu sistema operativo. Una vez descargada, sigue las instrucciones de instalación para configurar Cursor en tu equipo.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-129.png" alt="imagen-129.png" width="800" height="480"><p></p><h3><strong>2. Explorando la función de pestañas</strong></h3><p>La función Tabulador de Cursor proporciona autocompletado inteligente de código y sugerencias mientras escribes. Así se usa:</p><ol class="prose-ordered-list"><li><p>Abra Cursor y cree un nuevo archivo (por ejemplo, snake.py).</p></li><li><p>Comience a escribir su código, por ejemplo: "importar"</p></li><li><p>Cursor proporcionará predicciones inmediatamente. Presione Tab para aceptar una sugerencia.</p></li><li><p>La función Tabulación puede completar no sólo líneas individuales, sino bloques enteros de código.</p></li></ol><p>Por ejemplo, si estás creando un juego de serpientes, Cursor podría sugerirte importar bibliotecas aleatorias y de pygame, ahorrándote tiempo y reduciendo errores.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-130.png" alt="imagen-130.png" width="800" height="480"><p></p><h3><strong>3. Uso de la función de chat</strong></h3><p>La función Chat de Cursor es un asistente con IA que te ayuda a programar preguntas y tareas. Para usarla:</p><ol class="prose-ordered-list"><li><p>Alterne el panel de chat haciendo clic en el ícono de chat o utilizando el atajo Cmd/Ctrl + L.</p></li><li><p>Agregue contexto a su chat escribiendo "@" y eligiendo el archivo actual o su base de código completa.</p></li><li><p>Escribe tu pregunta o solicitud en el chat. Por ejemplo: "Estoy intentando crear un juego de la serpiente, dame el código".</p></li><li><p>Revise la respuesta de la IA y haga clic en "Aplicar" para insertar el código sugerido en su archivo.</p></li></ol><p>Puedes continuar la conversación, pidiendo modificaciones o explicaciones según sea necesario.&nbsp;</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-131.png" alt="imagen-131.png" width="800" height="480"><p></p><h3><strong>4. Poner en funcionamiento la función de compositor</strong></h3><p>Composer es la función de IA más potente de Cursor, capaz de generar y modificar archivos completos según tus instrucciones. Así se usa:</p><ol class="prose-ordered-list"><li><p>Invoque Composer presionando Cmd/Ctrl + I.</p></li><li><p>Describe lo que quieres crear. Por ejemplo: "Crea un juego de la serpiente con Pygame con dos archivos: uno para la página de inicio, donde podrás elegir la dificultad, y otro para el juego en sí".</p></li><li><p>Composer generará los archivos y el código solicitados sin que usted tenga que crear o editar nada manualmente.</p></li><li><p>Revise los archivos generados y haga clic en "Aceptar todo" para conservar los cambios.</p></li></ol><p>Puedes refinar aún más el código dándole a Composer instrucciones adicionales, como "No recogió la fruta, arréglalo".</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-132.png" alt="imagen-132.png" width="800" height="480"><p></p><h3><strong>5. Poniéndolo todo junto</strong></h3><p>Ahora que está familiarizado con las funciones de inteligencia artificial de Cursor, puede combinarlas para disfrutar de una excelente experiencia de codificación:</p><ol class="prose-ordered-list"><li><p>Utilice la tecla Tab para completar rápidamente el código y obtener sugerencias.</p></li><li><p>Cuando necesite ayuda o explicaciones más detalladas, cambie al chat.</p></li><li><p>Para tareas complejas o proyectos de múltiples archivos, utilice Composer para generar bases de código completas.</p></li><li><p>Itere su código utilizando una combinación de edición manual y asistencia de IA.</p></li></ol><p>Recuerde, si bien la IA de Cursor es poderosa, siempre revise y pruebe el código generado para asegurarse de que cumpla con sus requisitos específicos.</p><p><strong>Consejo profesional</strong> : Experimenta con diferentes comandos y estilos dentro de Cursor AI para comprender mejor todas sus funciones. No dudes en usar modelos de IA como <strong>ChatGPT</strong> para solucionar cualquier problema que surja.</p><p><strong>Esto es lo que has aprendido.</strong><br>Aprendiste a usar Cursor para crear tu propia aplicación sin escribir ni una sola línea de código.</p>', 26, '2025-09-02 16:13:05.169162', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 16:13:05.169162', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('35f76800-f164-4d07-8946-242c1c653ee7', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Imita tu estilo de escritura con ChatGPT', NULL, '<p>¿Alguna vez has sentido que las respuestas de ChatGPT eran demasiado... robóticas? ¡Prepárate para cambiar eso!</p><p>Como creadores de contenido, es increíblemente importante para nosotros mantener el mismo estilo de escritura, estructura y tono consistentes en la variedad de materiales sobre los que escribimos.&nbsp;</p><p>El problema es que, si no le damos las indicaciones correctas a la IA o esta no conoce nuestro estilo de escritura, volverá a utilizar un galimatías típico de la IA que a nadie le gusta leer.</p><p>Te enseñaremos a configurar ChatGPT para que escriba como tú (o con el estilo que elijas). Incluso te enseñaremos un truco ingenioso para que ChatGPT recuerde tu estilo para siempre.&nbsp;</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Recopilación de muestras de escritura&nbsp;</p></li><li><p>Introduciendo el mensaje mágico&nbsp;</p></li><li><p>Alimenta a la IA con tus materiales</p></li><li><p>Nombra tu estilo de escritura</p></li><li><p>Produce material nuevo con tu estilo único.&nbsp;</p></li></ul><p>¡Vamos!</p><p><strong>Puntos problemáticos resueltos:</strong></p><ul class="prose-bullet-list"><li><p>Tiempo dedicado a escribir o editar comunicaciones.</p></li><li><p>Tono inconsistente en documentos escritos y correos electrónicos.</p></li></ul><h2><strong>1. Reúne tus muestras de escritura</strong></h2><p>Si estás tomando este curso, probablemente leas nuestro boletín diario sobre inteligencia artificial, por lo que usaremos los "últimos desarrollos" de nuestros boletines como muestra de escritura.</p><p>Pero si no tienes tu propio boletín informativo, no te preocupes. Aquí tienes otros ejemplos que puedes usar:</p><ul class="prose-bullet-list"><li><p>Correos electrónicos personales</p></li><li><p>Entradas de blog o artículos</p></li><li><p>Copia del sitio web</p></li><li><p>Ensayos o informes</p></li></ul><p>La clave es usar tus mejores textos, que reflejen eficazmente tu tono, estructura, gramática y demás. ChatGPT lo aprenderá.</p><h2><strong>2. El mensaje mágico</strong></h2><p>El siguiente mensaje le indica a ChatGPT que le proporcionaremos algunas muestras de nuestro texto para que las replique. Puedes copiar y pegar el mensaje completo a continuación.</p><p><strong>Indicación:</strong><br>Les proporcionaré mi propio material escrito y su tarea será comprender e imitar su estilo. Comenzarán este ejercicio diciendo "COMIENZA". Después, les presentaré un texto de ejemplo, al que responderán "CONTINÚAN". El proceso continuará de forma similar con otro <em>texto y luego con más ejemplos. Les daré una cantidad ilimitada de ejemplos. Su respuesta será solo "CONTINÚAN". Solo podrán cambiar su respuesta cuando les diga "TERMINADO". Después, explorarán y comprenderán el tono, el estilo y las características de mi escritura basándose en los ejemplos que les he dado. Finalmente, les pediré que redacten un nuevo texto sobre un tema específico, imitando mi estilo distintivo.</em></p><img class="prose-image" src="/api/lesson-resources/28cb2888-034b-4b77-b70c-708d3d5f35db/image-1756830563121-vbvsvv.jpg"><h2><strong>3. Alimenta a la bestia de la IA</strong></h2><p>Ahora, empieza a pegar tus ejemplos de escritura uno por uno. Espera a que ChatGPT diga "CONTINUAR" antes de añadir el siguiente. Intenta pegar al menos 5 ejemplos para obtener los mejores resultados.</p><h2><strong>4. Escribe "TERMINADO" cuando hayas terminado.</strong></h2><p>Una vez que hayas compartido todas tus muestras, escribe "TERMINADO" para avisarle a ChatGPT que has terminado.</p><img class="prose-image" src="/api/lesson-resources/133fa7f0-7973-4131-ad70-937bc8e39b61/image-1756830612375-tlvea.jpg"><img class="prose-image" src="/api/lesson-resources/12c39800-c0bf-49fd-87d2-4834b87eebba/image-1756830657011-enwsm.jpg"><h2><strong>5. Nombra tu estilo</strong></h2><p>Dado que utilizamos mis textos de mi boletín, vamos a optar por "El estilo Resumen".</p><h2><strong>6. Pon a prueba tu chat recién entrenado</strong></h2><p>¡Es hora de ver si ChatGPT realmente escribe como tú! Prueba con un mensaje como este:</p><p>"Escribe un párrafo sobre [noticias recientes sobre IA] usando [nombre de tu estilo]"</p><p>Recuerda: La IA a veces puede alucinar o generar información falsa. ¡Siempre revisa y verifica los datos antes de publicar!</p><img class="prose-image" src="/api/lesson-resources/34b1a571-681b-4080-9ca5-1a31a7ad5a5c/image-1756830846481-it2gq.jpg"><p>Otra cosa importante a mencionar es que no usamos IA para ninguno de nuestros escritos, pero esto ayuda a resolver el problema de la "pizarra en blanco" si alguna vez nos quedamos atascados.</p><p>Todavía no es tan bueno como la escritura humana, pero imita el estilo con una precisión de aproximadamente el 90 %.</p><h2><strong>Haz que ChatGPT recuerde tu estilo para siempre</strong></h2><p>Una vez que haya terminado de entrenar a ChatGPT sobre su estilo de escritura, simplemente pregúntele cómo escribe para que podamos ingresarlo en Instrucciones personalizadas para ayudarlo a recordar su estilo de escritura.&nbsp;</p><p><strong>Utilice el siguiente mensaje:</strong></p><p><em>Basándome en el estilo de escritura que has aprendido de mis escritos, quiero que me expliques cómo escribo para poder incorporar ese estilo a las Instrucciones Personalizadas. Por favor, explica con detalle los siguientes aspectos de mi estilo de escritura: tono (formal, informal, amigable, profesional), vocabulario (simple, complejo, técnico, coloquial), estructura de las oraciones (cortas, largas, variadas), preferencias de puntuación y gramática, uso de lenguaje figurado, modismos y expresiones idiomáticas, y cualquier otro aspecto que pueda ser útil para futuros trabajos.</em></p><h2><strong>Acceda a instrucciones personalizadas</strong></h2><p>Después de ingresar el mensaje, ChatGPT le dará una respuesta para copiar y pegar en la función de instrucciones personalizadas de ChatGPT.</p><p>Querrás hacer clic en tu perfil, luego en Instrucciones personalizadas y luego en ¿ <em>Cómo te gustaría que ChatGPT responda?</em> ingresa tu guía de estilo de escritura.</p><img class="prose-image" src="/api/lesson-resources/70c143ed-3bf0-4056-8057-3c43f73fcd21/image-1756831055736-9yzg4h.jpg"><h2><strong>Cómo perfeccionar tu clon de escritura de IA</strong></h2><p>Recuerda, la perfección requiere práctica, ¡incluso para la IA! Si los primeros intentos de ChatGPT no te convencen lo suficiente, no te preocupes. Simplemente envía comentarios y pídele que refine el resultado. Con cada iteración, estarás más cerca de encontrar tu voz única.</p><p><strong>Consejo:</strong> Recuerda siempre usar tu palabra clave para activar tu estilo de escritura. Por ejemplo, usa el estilo " <strong>Resumen</strong> " para reescribir lo siguiente:&nbsp;</p><p>Has aprendido a introducir tus materiales de escritura en ChatGPT y a emular tu estilo de escritura. Luego, usa ese estilo único para producir contenido novedoso y diverso.</p>', 27, '2025-09-02 16:37:52.238772', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 16:37:52.238772', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('c785b41d-848b-4b1e-8b7d-706600c0ebbc', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Analice acciones y recopile información financiera utilizando el contexto largo de Gemini', NULL, '<p>Existe una enorme demanda de buscar y encontrar información específica en documentos grandes sin alucinaciones.&nbsp;</p><p>El contexto extenso de Gemini es excelente para este caso de uso, especialmente si usted es un inversor que busca analizar informes y presentaciones financieras para identificar información específica.</p><p>Ahora puede utilizar Gemini para analizar documentos financieros de gran tamaño para tomar mejores decisiones de inversión.</p><p><strong>En esta lección, cubriremos:&nbsp;</strong></p><ul class="prose-bullet-list"><li><p>Entender el problema en cuestión y por qué Géminis es el más adecuado&nbsp;</p></li><li><p>Introducción a Google AI Studio</p></li><li><p>Cargando sus presentaciones financieras&nbsp;</p></li><li><p>Elaboración de su mensaje específico</p></li><li><p>Ejecución y perfeccionamiento de su análisis&nbsp;</p></li></ul><p>¡Vamos!&nbsp;</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-137.png" alt="imagen-137.png" width="800" height="480"><p></p><h3><strong>1. Comprender el desafío</strong></h3><p>Al analizar archivos de la empresa, como informes trimestrales o formularios 10-K, el tamaño de estos documentos suele superar los límites de la ventana de contexto de herramientas de IA tradicionales como ChatGPT o Claude. Por ejemplo:</p><ul class="prose-bullet-list"><li><p>ChatGPT: ~128.000 tokens (aprox. 118.000 palabras)</p></li><li><p>Claude: ~200.000 tokens (aproximadamente 160.000 palabras)</p></li></ul><p>Para archivos más grandes, necesita una herramienta que pueda manejar muchos más datos.</p><h3><strong><br>2. Por qué Géminis es la solución</strong></h3><p><strong>Gemini 1.5 Pro 002</strong> de Google ofrece una <strong>ventana de contexto de 2 millones de tokens</strong> , capaz de procesar casi <strong>1,4 millones de palabras</strong> a la vez. Esto es ideal para analizar varios documentos grandes simultáneamente, como varios informes 10-K.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-138.png" alt="imagen-138.png" width="800" height="480"><p></p><h3><strong>3. Introducción a Google AI Studio</strong></h3><p>Ve a <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://aistudio.google.com/">aistudio.google&nbsp;</a>e inicia sesión en tu cuenta de Google. Aquí crearás tu mensaje.</p><ul class="prose-bullet-list"><li><p>Nombre su proyecto: p. ej., <strong>Analizador de stock</strong> .</p></li><li><p>Seleccione el modelo: elija <strong>Gemini 1.5 Pro 002</strong> para un análisis más profundo, o <strong>Flash Model</strong> para obtener respuestas más rápidas y centradas en las matemáticas.</p></li><li><p>Configure preferencias como la temperatura y asegúrese de no necesitar <strong>ejecución de código</strong> , <strong>llamada de función</strong> o <strong>modo JSON&nbsp;</strong> para esta tarea.</p></li></ul><h3><strong>4. Carga de informes financieros</strong></h3><p>Para iniciar el análisis, cargue los informes financieros de las empresas que desea analizar:</p><ul class="prose-bullet-list"><li><p>Vaya a <strong>Cargar a Drive</strong> .</p></li><li><p>Arrastre y suelte los archivos (por ejemplo, presentaciones anuales 10-K de TSMC, NVIDIA y AMD).</p></li></ul><h3><strong>5. Elaboración del mensaje</strong></h3><p>Crea un mensaje completo para que Gemini analice las presentaciones:</p><ul class="prose-bullet-list"><li><p>Ejemplo de pregunta:<br><em>«Usted es un analista bursátil experto. Analice los informes 10-K de TSMC, NVIDIA y AMD, centrándose en su salud financiera, balances y pronóstico de crecimiento. Clasifique las empresas según su potencial de inversión y proporcione información sobre sus estrategias para construir una ventaja competitiva</em> » .</p></li></ul><h3><strong>6. Ejecución del análisis</strong></h3><p>Una vez que el mensaje esté listo, ejecute el análisis y monitoree el <strong>tiempo de inferencia en tiempo real</strong> . Gemini tardará un tiempo en procesar el gran conjunto de datos y generar un informe detallado.</p><ul class="prose-bullet-list"><li><p>Si se utilizan otras herramientas como ChatGPT, no podría manejar todo el contexto debido a las limitaciones de tokens, pero Gemini está equipado para procesar todo dentro de la ventana de 2 millones de tokens.</p></li></ul><h3><strong>7. Resultados y perspectivas</strong></h3><p>Tras el procesamiento, Gemini presentará una clasificación basada en la salud financiera y el potencial de inversión. Por ejemplo:</p><ul class="prose-bullet-list"><li><p><strong>NVIDIA</strong> : la mejor inversión, con un fuerte liderazgo en IA y un ingreso neto de 29,76 mil millones de dólares.</p></li><li><p><strong>TSMC</strong> : Fuerte capacidad de fabricación, aunque reciente caída de ingresos del -5%.</p></li><li><p><strong>AMD</strong> : Resultados financieros mejorados, pero aún está por detrás de NVIDIA en crecimiento de ingresos.</p></li></ul><h3><strong>8. Ajuste del análisis</strong></h3><p>Puedes refinar tu solicitud para obtener información más específica. Por ejemplo, si el modelo malinterpretó tu consulta, como al confundir <strong>"moat"</strong> con <strong>"boat"</strong> , simplemente corrige el término y vuelve a ejecutar la consulta:</p><ul class="prose-bullet-list"><li><p><em>"¿Cómo están construyendo estas empresas su foso y por qué clasificaron a TSMC por encima de AMD?"</em></p></li><li><p>También puedes pedirle a Gemini recomendaciones <strong>de asignación de cartera</strong> basadas en una estrategia de asignación del 100%.</p></li></ul><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-139.png" alt="imagen-139.png" width="800" height="480"><p></p><h3><strong>9. Solicitud de datos adicionales</strong></h3><p>Para obtener información más detallada, puedes pedirle a Géminis que:</p><ul class="prose-bullet-list"><li><p>Crear comparaciones de ratios financieros (por ejemplo, <strong>márgenes brutos</strong> , <strong>ratios de rentabilidad</strong> , <strong>liquidez</strong> , <strong>eficiencia de apalancamiento</strong> ).</p></li><li><p>Generar gráficos o resúmenes para comparar visualmente la salud financiera de las empresas.</p></li></ul><p><strong>Consejo profesional:</strong> siga experimentando con diferentes indicaciones de análisis, como métricas financieras o pronósticos específicos, para maximizar el valor de Gemini para fines de inversión.</p><p>Con la poderosa ventana de contexto y las capacidades de análisis detalladas de Gemini, ahora puede analizar grandes informes financieros de manera efectiva, tomar decisiones de inversión informadas y extraer información relevante de conjuntos de datos masivos que abrumarían otras herramientas de IA.</p>', 28, '2025-09-02 16:43:39.196652', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 16:43:39.196652', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('92ca11da-9f73-4f4f-a828-83fd7c2add84', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Simplifique los diagramas con ChatGPT', NULL, '<p>La IA puede ayudarnos a aprender de más maneras que nunca.&nbsp;</p><p>Podemos tomar datos visuales, como gráficos, diagramas o tablas, y convertirlos en texto para facilitar su comprensión. Esto mejorará la comprensión y la velocidad de aprendizaje, especialmente en temas complejos. Es una herramienta muy valiosa tanto para estudiantes como para profesores.</p><p>A medida que herramientas como ChatGPT y Gemini mejoran en la interpretación de imágenes, ahora puedes resumir y explicar fácilmente diagramas o gráficos complejos.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Accediendo a ChatGPT Vision</p></li><li><p>Subir un diagrama complejo&nbsp;</p></li><li><p>Hacer preguntas sobre el diagrama dado</p></li></ul><p>¡Vamos!</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-144.png" alt="imagen-144.png" width="1616" height="910"><p></p><p><em>Fuente de la imagen: Cameron R. Wolfe</em></p><h3><strong>1. Elige la herramienta adecuada</strong></h3><p>Hazte premium con <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://chat.openai.com/"><strong>ChatGPT</strong></a> o <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://gemini.google.com/"><strong>Gemini</strong></a> . Ambas herramientas son geniales, pero la visión de ChatGPT podría ser un poco mejor. No te preocupes, Gemini ofrece dos meses de prueba gratis.</p><h3><strong>2. Sube tu diagrama</strong></h3><p>¿Tienes un gráfico complejo, un diagrama complejo o un diagrama complejo? ¿Quizás un problema de tarea que te deja perplejo? Súbelo a ChatGPT.</p><h3><strong>3. Pide una explicación</strong></h3><p>Proporciona una instrucción sencilla solicitando una explicación de la imagen subida. Algo como: "Esta es una foto de mi [inserta tu artículo aquí]. ¿Podrías resumirme los puntos clave?"</p><h3><strong>4. Sigue preguntando</strong></h3><p>No te quedes con la primera respuesta. Sigue haciendo preguntas hasta que comprendas bien el material.</p><p><strong>Consejo útil:</strong> también puedes pedirle a ChatGPT que reescriba el texto exactamente como aparece en el diagrama, y ​​lo hará.</p><p>Ahora puedes convertir fácilmente diagramas en texto, lo que facilita el aprendizaje. Desglosa imágenes complejas, comprende los puntos clave más rápido y aborda ideas difíciles con mayor claridad. Pon en práctica estas habilidades y asegúrate de que los diagramas complejos nunca vuelvan a frenarte.</p><p><em>Ejemplo de tarea:</em></p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-145.png" alt="imagen-145.png" width="800" height="480"><p></p><h3><strong>1. Sube tu tarea</strong></h3><p>El primer paso es subir una foto de tu tarea a ChatGPT</p><ul class="prose-bullet-list"><li><p>Dirígete a ChatGPT.</p></li><li><p>Haga clic en el icono <strong>del clip&nbsp;</strong> a la izquierda del cuadro de texto. Esto le permite subir archivos directamente a ChatGPT.</p></li><li><p>Seleccione una imagen de su tarea y haga clic en <strong>Cargar</strong></p></li></ul><h3><strong>2. Transforma ChatGPT en un tutor</strong></h3><ul class="prose-bullet-list"><li><p>Introduce un mensaje para pedirle a ChatGPT que analice tu tarea. Por ejemplo:</p></li></ul><p><em>Quiero entender la tarea de esta imagen. Pregúntame y, si me equivoco, por favor, aclárame.</em></p><p>ChatGPT revisará tu tarea y te brindará sugerencias y desgloses útiles.</p><p><br>¡Así de simple! No dudes en preguntarle a ChatGPT cualquier duda sobre tu tarea.</p><p>Has aprendido a convertir cualquier diagrama o gráfico en material de aprendizaje sencillo para una fácil comprensión.</p>', 29, '2025-09-02 17:05:57.703445', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 17:05:57.703445', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('e1445915-3f50-418e-8ddd-fb02221e25c4', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Analice videos para obtener información con Gemini', NULL, '<p>La inteligencia artificial Gemini de Google puede analizar tus videos para proporcionar transcripciones, ideas de títulos, etiquetas, mejoras y sugerencias promocionales para simplificar tu flujo de trabajo de contenido.</p><p>En marketing, es importante medir la efectividad de cada campaña. Esta es una excelente manera de analizar y recopilar información sobre qué contenido de video funciona y cuál no, y cómo implementar los cambios necesarios en tu estrategia de contenido de marketing.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Cómo acceder y configurar su espacio de trabajo Gemini</p></li><li><p>Sube un vídeo para analizarlo</p></li><li><p>Recopilar información sobre ideas de mejora</p></li><li><p>Implemente estos conocimientos para futuras mejoras</p></li></ul><p>¡Vamos!</p><h3><strong><br>1. Configuración de su espacio de trabajo Gemini</strong></h3><p>Para empezar a usar Gemini para el análisis de video, deberás acceder a <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://aistudio.google.com/"><strong>Google AI Studio</strong></a> . Inicia sesión con tus credenciales de Google. Si no tienes una cuenta de Google, deberás crear una.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-146.png" alt="imagen-146.png" width="800" height="480"><p></p><p>Una vez iniciada la sesión, localice el menú desplegable "Modelos" en la esquina superior derecha de la interfaz. Haga clic en el menú y seleccione "Gemini 2.5 Pro o el nuevo Nano Banana" de la lista de modelos disponibles. Esta versión de Gemini ofrece las funciones de análisis de video más avanzadas.</p><h3><strong>2. Subir y analizar tu vídeo</strong></h3><p>Ahora que tienes configurado el modelo Gemini correcto, es hora de subir y analizar tu contenido de video. En la interfaz de Gemini, busca el botón de subir. Sube o selecciona el archivo de video que quieres analizar desde tu Google Drive.</p><img class="prose-image" src="/api/lesson-resources/1a76fd69-646a-4e92-a5ef-766590b01100/image-1756838325640-kxs8g.jpg"><img class="prose-image" src="/api/lesson-resources/1c659d98-69cc-466c-bbae-541ec79fec79/image-1756838357786-i4wmjg.jpg"><p>Una vez subido el video, verás una miniatura o vista previa en la interfaz de chat. Ahora, escribamos un mensaje completo para aprovechar al máximo el análisis de Gemini:</p><blockquote><p><em>Analice a fondo el vídeo subido y proporcione lo siguiente:</em></p><ul class="prose-bullet-list"><li><p><em>Una transcripción detallada de todo el contenido hablado, incluidas las marcas de tiempo de cada cambio de hablante.&nbsp;</em></p></li><li><p><em>Una lista completa de etiquetas relevantes que describen el contenido, los temas y los elementos visuales del vídeo.&nbsp;</em></p></li><li><p><em>Categorice estas etiquetas (por ejemplo, temas, objetos, emociones, acciones).</em></p></li></ul></blockquote><img class="prose-image" src="/api/lesson-resources/35af5f7f-3fc1-4f4b-a67a-fbfdc2ef8447/image-1756838536308-z1n3oj.jpg"><img class="prose-image" src="/api/lesson-resources/81fc4467-b0fd-4b12-bb73-35ff29b1e54e/image-1756838760370-x2a9vf.jpg"><p></p><h3><strong>3. Recopilación de mejoras e ideas promocionales</strong></h3><p>Ahora, profundicemos en la mejora y promoción del contenido. Utilice esta sugerencia de seguimiento:</p><blockquote><p><em>Con base en el análisis del video, proporcione:&nbsp;</em></p><ul class="prose-bullet-list"><li><p><em>5 sugerencias específicas para mejorar el contenido, la estructura o el factor de engagement del video</em></p></li><li><p><em>Ideas para clips promocionales o avances, incluidas marcas de tiempo para las secciones relevantes</em></p></li><li><p><em>Recomendaciones para ampliar el alcance del vídeo (por ejemplo, plataformas, segmentación de audiencia).</em></p></li></ul></blockquote><img class="prose-image" src="/api/lesson-resources/0824b4cd-b6a2-4a89-a541-958322ed197f/image-1756838895424-e8lx29.jpg"><h3><strong>4. Implementación de los conocimientos</strong></h3><p>Con el análisis de Gemini en la mano, es hora de mejorar tu estrategia de video general:</p><ul class="prose-bullet-list"><li><p>Optimización de contenido: Usa las etiquetas generadas y las ideas de título para mejorar el SEO. Implementa sugerencias de mejora en futuros videos.</p></li><li><p>Interacción con la audiencia: Crea elementos interactivos (p. ej., capítulos, tarjetas) basados ​​en las marcas de tiempo de la transcripción. Usa las ideas de clips promocionales para crear avances en redes sociales.</p></li><li><p>Expansión y alcance: Considere crear versiones localizadas basadas en las sugerencias de segmentación de audiencia de Gemini. Reutilice la transcripción para publicaciones de blog o artículos que complementen su contenido de video.</p></li></ul><p><strong>Consejo útil</strong> : analice periódicamente sus videos con Gemini para realizar un seguimiento de las mejoras e identificar tendencias en el rendimiento de su contenido a lo largo del tiempo.</p><p>Ha aprendido a analizar sus materiales de marketing y a decidir qué contenido funciona y cuál no, para poder optimizar futuras campañas de marketing y obtener un mayor retorno de la inversión.</p>', 30, '2025-09-02 18:48:24.269173', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 18:48:24.269173', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('824d987a-7baa-4ae0-a39e-a22d4a2648c8', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Convierte videos de YouTube en podcasts de IA con NotebookLM', NULL, '<p>La última actualización de NotebookLM permite a los usuarios transformar videos largos de YouTube en podcasts concisos generados por IA, ahorrando tiempo y aumentando la eficiencia del estudio.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Cómo acceder y utilizar NotebookLM</p></li><li><p>Subiendo tu video de YouTube&nbsp;</p></li><li><p>Generando tu podcast con Audio Overviews&nbsp;</p></li><li><p>Interactuando con tu podcast de IA</p></li></ul><p>¡Vamos!</p><h3><strong>1. Acceso a NotebookLM</strong></h3><p>Para empezar, visita el <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://notebooklm.google/"><strong>sitio web</strong></a> de NotebookLM . Si eres nuevo en la plataforma, deberás iniciar sesión con tus credenciales de Google. Una vez iniciada la sesión, haz clic en el botón "Probar NotebookLM" para acceder a la interfaz principal.</p><img class="prose-image" src="/api/lesson-resources/c9f461f7-6064-4bff-a3de-87040e910c27/image-1756839079223-xlbiw.jpg"><h3><strong>2. Cómo agregar tu video de YouTube</strong></h3><p>En tu nuevo cuaderno, busca la opción "Enlace" en el área de selección de fuente. Haz clic en el botón "YouTube" para especificar que vas a agregar un video de YouTube como fuente.</p><img class="prose-image" src="/api/lesson-resources/13a045b7-82df-46da-8757-03991b50ca6a/image-1756839147937-ce32d.jpg"><p>Ahora, ve a YouTube y busca el video que quieres convertir en podcast. Haz clic en el botón "Compartir" debajo del video y copia la URL.</p><p>Regrese a NotebookLM y pegue la URL copiada en el campo correspondiente. La plataforma procesará el video inmediatamente y generará un resumen completo.</p><h3><strong>3. Generando el podcast de IA</strong></h3><p>Una vez que NotebookLM haya procesado tu video, verás la sección "Resumen de audio". Haz clic en el botón "Generar" dentro de esta sección para crear tu podcast con IA.</p><img class="prose-image" src="/api/lesson-resources/10825c67-6ed8-457a-9266-db92793f57d9/image-1756840007542-qnkqwd.jpg"><p>El proceso de generación puede tardar unos minutos, dependiendo de la duración del vídeo original. Una vez finalizado, tendrás acceso a una versión de audio condensada del contenido, que normalmente reduce horas de vídeo a un formato de podcast manejable.</p><h3><strong>4. Interactuando con tu podcast de IA</strong></h3><p>NotebookLM ofrece varias formas de interactuar con su podcast recién creado:</p><ol class="prose-ordered-list"><li><p>Reproduzca el audio directamente dentro de la plataforma utilizando el reproductor integrado.</p></li><li><p>Haz preguntas sobre el contenido mediante el chat. Por ejemplo, podrías preguntar: <span style="font-family: Inter;">"¿</span><span style="font-family: Inter; font-size: 14px; color: rgb(232, 234, 237);">Cómo la integración de Gemini con Make revoluciona la automatización de procesos para usuarios sin conocimientos técnicos</span><span style="font-family: Inter;">?".</span></p></li><li><p>Genere materiales de estudio adicionales, como preguntas frecuentes, guías de estudio o cronogramas según el contenido.&nbsp;</p></li></ol><img class="prose-image" src="/api/lesson-resources/5847f221-42ca-44b7-906b-dac9b83d614e/image-1756840323623-d80doi.jpg"><h3><strong>5. Compartir y descargar</strong></h3><p>Para compartir tu podcast de IA o guardarlo para más tarde, haz clic en el menú de tres puntos junto al reproductor de audio. Tienes varias opciones:</p><ul class="prose-bullet-list"><li><p>Generar un enlace de acceso público para compartir con otros</p></li><li><p>Descargue el archivo de audio para escuchar sin conexión</p></li><li><p>Ajuste la velocidad de reproducción para una experiencia auditiva personalizada</p></li></ul><img class="prose-image" src="/api/lesson-resources/0e2e654b-ea78-4c21-843a-641e373cf065/image-1756840377026-v9q7y5.jpg"><p><strong>Consejo útil:&nbsp;</strong> Al hacer clic en "compartir" en la esquina superior derecha, puedes compartir el podcast que creaste con cualquier persona para que lo escuche.&nbsp;</p><p>Siguiendo estos pasos, puedes transformar videos largos de YouTube en podcasts concisos generados por IA, lo que facilita el estudio, la investigación o el consumo de contenido sobre la marcha.</p><p>Has aprendido a tomar cualquier video de YouTube y convertirlo en un podcast inmersivo para una experiencia de aprendizaje más divertida e inmersiva.</p>', 31, '2025-09-02 19:13:06.955359', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 19:13:06.955359', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('eced3d6d-78d4-4625-bde9-7a22e925056a', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Aprenda cualquier idioma con facilidad utilizando la voz avanzada de ChatGPT', NULL, '<p>La forma en que aprendemos idiomas nunca volverá a ser la misma. Ahora puedes aprender un nuevo idioma de forma rápida y cómoda con la nueva función de voz avanzada de ChatGPT.&nbsp;</p><p><em>¿Por qué?</em></p><ol class="prose-ordered-list"><li><p>La latencia es muy baja y la conversación es casi en tiempo real. &nbsp;</p></li><li><p>Se siente como si estuvieras hablando con otro ser humano y no con una IA.&nbsp;</p></li></ol><p>La mejor parte es que está disponible las 24 horas, los 7 días de la semana y no necesitas otro compañero de idioma.&nbsp;</p><p><strong>En esta lección, cubriremos:&nbsp;</strong></p><ul class="prose-bullet-list"><li><p>Cómo acceder y activar la Voz Avanzada de ChatGPT</p></li><li><p>Establezca sus instrucciones personalizadas para evitar interrupciones</p></li><li><p>Practica con tus propias conversaciones personalizadas</p></li><li><p>Solicitar ayuda con la pronunciación</p></li></ul><p>¡Vamos!</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-155.png" alt="imagen-155.png" width="800" height="480"><p></p><h3><strong>1. Configure su entorno de chat de voz</strong></h3><p>Para comenzar con el aprendizaje de idiomas mediante inteligencia artificial, deberá descargar la aplicación ChatGPT.</p><p>Una vez que tengas la aplicación instalada y el modo de voz activado, estarás listo para empezar. Ten en cuenta que también puedes seguir este tutorial con la voz estándar.</p><h3><strong>2. Introducción a la voz avanzada de ChatGPT</strong></h3><p>Para empezar a usar la función de voz de ChatGPT para aprender idiomas, inicia sesión en tu cuenta de ChatGPT y accede a tu configuración personalizada. En la página de inicio, haz clic en la pestaña <strong>"ChatGPT personalizado"</strong> . A continuación, ve a la segunda instrucción: <strong>"¿Cómo quieres que ChatGPT responda?".</strong></p><p>Cambie la configuración aquí a:</p><ul class="prose-bullet-list"><li><p><strong><em>En las conversaciones de voz, quiero que reconozcas lo que digo simplemente respondiendo con ''mhm'' y nada más hasta que diga explícitamente GPT.</em></strong></p></li></ul><p>Esto evita interrupciones y le permite mantener el flujo de pensamiento mientras practica el habla.</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-156.png" alt="imagen-156.png" width="800" height="480"><p></p><h3><strong>3. Prepare su mensaje&nbsp;</strong></h3><p>En tu app móvil, localiza el <strong>botón de sonido</strong> en la esquina inferior derecha. Presionalo para empezar a hablar directamente con ChatGPT.</p><p>La clave para un aprendizaje de idiomas eficaz con IA es crear una guía detallada que guíe a la IA para que te proporcione el tipo de práctica que necesitas. Aquí tienes una plantilla que puedes usar y personalizar:</p><p><em>Eres hablante nativo de [idioma meta]. Yo soy un estudiante [principiante/intermedio/avanzado]. Por favor, conversar conmigo sobre [tema], usando vocabulario y gramática sencillos, adecuados a mi nivel. Corrige mis errores, ofrece frases alternativas y proporciona explicaciones tanto en [idioma meta] como en inglés cuando sea necesario. Si tengo dificultades, por favor, habla más despacio y ofrece alternativas más sencillas.</em></p><p>&nbsp;Por ejemplo, si eres un principiante que está aprendiendo español, tu mensaje podría verse así:</p><p><em>Eres hablante nativo de español. Yo soy principiante. Por favor, conversa conmigo sobre cómo pedir comida en un restaurante, usando vocabulario y gramática sencillos, adecuados a mi nivel. Corrige mis errores, ofrece frases alternativas y da explicaciones tanto en español como en inglés cuando sea necesario. Si tengo dificultades, por favor, habla más despacio y ofrece alternativas más sencillas.</em></p><h3><strong>4. Comienza tu sesión de aprendizaje de idiomas</strong></h3><p>Con el mensaje listo, es hora de comenzar tu sesión:</p><p>1. Abra la aplicación ChatGPT y navegue hasta la interfaz de chat.</p><p>2. Toque el icono del micrófono para activar el modo de voz.</p><p>3. Diga claramente el mensaje preparado a través del micrófono.</p><p>4. Espere a que la IA procese su solicitud y responda.</p><p>ChatGPT responderá en tiempo real, ayudándote con la pronunciación y la comprensión.</p><p>Puedes seguir pidiéndole que repita la palabra rápido o lento, o hacerle algunas preguntas o frases para practicar.&nbsp;</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-157.png" alt="imagen-157.png" width="460" height="886"><p></p><h3><strong>5. Participe en una conversación interactiva</strong></h3><p>Una vez que la IA responda, podrás participar en una conversación de ida y vuelta:</p><ul class="prose-bullet-list"><li><p>Escucha atentamente la respuesta de la IA. Si es demasiado rápida, puedes decir "Más despacio, por favor" o "¿Puedes repetir eso?".</p></li><li><p>Responda a las preguntas o comentarios de la IA en el idioma de destino lo mejor que pueda.</p></li><li><p>Preste atención a cualquier corrección o sugerencia que proporcione la IA.</p></li></ul><p>A medida que se sienta más cómodo con las conversaciones básicas, podrá explorar técnicas de aprendizaje más avanzadas:</p><ol class="prose-ordered-list"><li><p><strong><em>Escenarios de juego de roles:&nbsp;</em></strong> utilice indicaciones como la del video para practicar situaciones específicas, como pedir direcciones o hacer un pedido en un restaurante.</p></li><li><p><strong><em>Enfoque gramatical:</em></strong> pídale a la IA que se concentre en puntos gramaticales específicos con los que tiene dificultades.</p></li><li><p><strong><em>Desarrollo de vocabulario:</em></strong> solicita conversaciones sobre temas específicos para ampliar tu vocabulario en áreas de interés.</p></li><li><p><strong><em>Práctica de pronunciación:</em></strong> pídale a la IA que se concentre en su pronunciación y le brinde comentarios detallados.</p></li></ol><p><strong>Consejo</strong> : Guarda indicaciones efectivas en tus notas para acceder rápidamente a ellas en futuras sesiones. También puedes añadirlas a tus instrucciones personalizadas en la configuración de la app para practicar de forma consistente en varias conversaciones.</p><p>Aprendió cómo utilizar mejor la función de voz avanzada de ChatGPT para aprender o retener cualquier idioma de su elección.</p>', 32, '2025-09-02 19:15:53.708577', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 19:15:53.708577', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('f60058d5-e519-41f1-b07d-b59de5df80e9', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Muestra tus datos usando gráficos impulsados ​​por IA', NULL, '<p>ChatGPT y Claude te permiten visualizar tus datos y crear gráficos, pero los datos a menudo no están disponibles en tiempo real ni en vivo desde la web.&nbsp;</p><p>Sin embargo, Perplexity obtiene datos financieros en tiempo real y cualquier otra información y puede crear gráficos visualmente atractivos directamente dentro de la plataforma.</p><p>La nueva función de interpretación de código de Perplexity logra esto al permitir a los usuarios instalar bibliotecas de Python.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Introducción a Perplexity</p></li><li><p>Formula tu consulta&nbsp;</p></li><li><p>Observa cómo funciona la IA</p></li><li><p>Analiza tus resultados<strong>&nbsp;</strong></p></li></ul><p>&nbsp;¡Vamos!</p><p><strong>Puntos problemáticos resueltos:</strong></p><ul class="prose-bullet-list"><li><p>Dificultad para presentar datos en un formato claro y visual.</p></li><li><p>Tiempo dedicado a crear manualmente gráficos y cuadros.</p></li></ul><p></p><h3><strong>1. Primeros pasos</strong></h3><p>Para utilizar la función de interpretación de código de Perplexity, visite <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://perplexity.ai/"><strong>Perplexity</strong></a> y cree una cuenta gratuita si aún no tiene una.&nbsp;</p><p>Tenga en cuenta que si bien esta función está disponible en cuentas gratuitas y profesionales, los usuarios gratuitos están limitados a cinco búsquedas por día.&nbsp;</p><img class="prose-image" src="https://app.therundown.ai/api/media/file/image-161.png" alt="imagen-161.png" width="800" height="480"><p></p><h3><strong>2. Formula tu consulta</strong></h3><p>En la barra de búsqueda, introduzca una solicitud que requiera la recuperación y visualización de datos. Por ejemplo:</p><blockquote><p><em>Instalar una biblioteca para obtener la rentabilidad bursátil del índice DAX de los últimos 20 años. Luego, usarla para crear un gráfico.</em></p></blockquote><p>Esta consulta implica instalar una biblioteca de Python, obtener datos financieros y crear una representación visual.</p><img class="prose-image" src="/api/lesson-resources/24c4375e-a27c-4f8a-8d6a-038ba850003e/image-1756842080913-ytdilq.jpg"><h3><strong>3. Observa cómo funciona la IA</strong></h3><p>Después de enviar su solicitud, Perplexity dividirá la tarea en varios pasos:</p><ol class="prose-ordered-list"><li><p>Busque bibliotecas apropiadas</p></li><li><p>Instalar la biblioteca necesaria (por ejemplo, Yahoo Finance)</p></li><li><p>Obtenga los datos bursátiles requeridos</p></li><li><p>Crear y mostrar el gráfico</p></li></ol><p>Puede expandir cada paso para ver el código Python ejecutándose en tiempo real.</p><img class="prose-image" src="/api/lesson-resources/9f5743b9-5425-46dc-80c1-ce6b7a78af58/image-1756842012803-zyeuch.jpg"><h3><strong>4. Analizar los resultados</strong></h3><p>Una vez que Perplexity complete la tarea, verá el resultado final. Con el gráfico disponible, puede hacer preguntas adicionales o solicitar modificaciones. Por ejemplo:</p><p>- "¿Puedes agregar una línea de tendencia al gráfico?"</p><p>- "¿Cuál fue el mayor rendimiento durante este período?"</p><p>- "Compárelo con otro índice importante como el S&amp;P 500"</p><p>Perplexity utilizará los datos y el código existentes para responder estas preguntas, creando potencialmente nuevas visualizaciones según sea necesario.</p><img class="prose-image" src="/api/lesson-resources/09fa2bdc-c4e8-40d7-9ef6-849da71756a4/image-1756842627690-a89t0r.jpg"><p><strong>Consejo útil:&nbsp;</strong> Perplexity tiene una increíble <a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://apps.apple.com/us/app/perplexity-ask-anything/id1668000334"><strong>aplicación iOS</strong></a> para usar en cualquier lugar.<strong>&nbsp;</strong></p><p><strong>Aprendió</strong> cómo instalar bibliotecas de Python en Perplexity y hacer que genere gráficos financieros en tiempo real utilizando datos financieros en vivo.</p>', 34, '2025-09-02 19:37:06.226891', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 19:37:06.226891', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('38850ce8-300d-4fd4-8179-9d15009f1ff7', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Haz que el aprendizaje sea divertido con Claude Artifacts', NULL, '<p>La mayoría de las personas aprenden mejor divirtiéndose.</p><p>Lograr que el aprendizaje sea interactivo y atractivo es crucial para una educación eficaz. Este tutorial muestra cómo transformar cualquier texto en un juego, manteniendo a los estudiantes activamente involucrados.</p><p>Claude Sonnet 4 le permite transformar cualquier texto o documento en una experiencia de aprendizaje atractiva e interactiva utilizando artefactos.</p><p><strong>En esta lección, cubriremos:</strong></p><ul class="prose-bullet-list"><li><p>Preparando tu material de aprendizaje</p></li><li><p>Accediendo a Claude Sonnet 4</p></li><li><p>Ingresa tu contenido</p></li><li><p>Personaliza tu juego</p></li></ul><p>¡Vamos!<br>&nbsp;</p><h3><strong>1. Prepara tu material de aprendizaje</strong></h3><p>Primero, deberás elegir el texto que quieres convertir en un juego interactivo de aprendizaje. Puede ser un artículo, un capítulo de libro o cualquier contenido educativo. Copia todo el texto que quieras usar.<br><strong>&nbsp;</strong></p><h3><strong>2. Acceso a Claude 4 Sonnet y habilitación de artefactos</strong></h3><p>Visita Claude AI y crea una cuenta si aún no lo has hecho. Asegúrate de usar Claude 4 Sonnet o 4.1 seleccionandolo en el menú desplegable.</p><p>Ve a la configuración de tu perfil y busca la sección "Vista previa futura". Activa la función "Artefactos" si aún no está activada.</p><img class="prose-image" src="/api/object-proxy/objects/uploads/3eb94113-23b1-4f9a-b5fb-96a265ba6345"><h3><strong>3. Ingresa tu contenido</strong></h3><p>Inicia una nueva conversación con Claude. Pega el texto que copiaste en el chat y pídele que cree un juego interactivo de aprendizaje. Aquí tienes un ejemplo:</p><blockquote><p><em>Cree una aplicación web de juego de aprendizaje interactivo en forma de cuestionario, basada en el documento adjunto. Después de cada pregunta, explique por qué la respuesta es correcta, citando las partes relevantes del texto original.</em></p></blockquote><img class="prose-image" src="/api/lesson-resources/61c406f3-d2fa-4969-9718-96a17d6a9ee3/image-1756841099635-mlzgyl.jpg"><h3><strong>4. Revisa y personaliza tu juego</strong></h3><p>Revise el contenido para asegurarse de que refleje con precisión la información del texto original.</p><img class="prose-image" src="/api/lesson-resources/fa676cee-8054-4b36-81a0-8d0e70995079/image-1756841523824-aj29sv.jpg"><p>Si quieres modificar el juego, puedes pedirle a Claude que haga cambios específicos. Por ejemplo:</p><ul class="prose-bullet-list"><li><p>¿Puedes añadir más preguntas al cuestionario?</p></li><li><p>Incluya imágenes o diagramas para ilustrar los conceptos clave.</p></li><li><p>"¿Puedes hacer las preguntas más desafiantes?"</p></li></ul><p>Claude ajustará el juego basándose en tus comentarios.</p><p><strong>Consejo útil:&nbsp;</strong> Puedes crear juegos arcade divertidos con Claude y pedirle a Sonnet 3.5 que sea tu oponente en el juego que estás creando, para que tengas alguien contra quien jugar.&nbsp;</p><p>Has aprendido a crear un juego de preguntas divertido e interactivo con tu material de aprendizaje.</p>', 33, '2025-09-02 19:32:11.928005', 'text', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-09-02 19:32:11.928005', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('c17a1ac8-588e-4680-bf83-20795ff1ae76', 'bed9ee88-a19a-44ae-b667-694f1e630bf5', '2.1 - Creación de una cuenta en N8N', NULL, '<p>Regístrese en N8N y pruébelo gratis durante 14 días:</p><p><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://n8n.partnerlinks.io/sxajetziak90">https://n8n.partnerlinks.io/sxajetziak90</a></p><p>---------------------------------------------------------------------------------------------------- --------------- </p><p>Chicos, os recomendamos seguir las clases aquí con n8n Cloud y luego os enseñaremos a instalarlo en servidores, ¿vale?</p><p>Facilita mucho el aprendizaje, aprovechad los 14 días gratis para aprender.</p><p>Después, en la FASE 5 del curso os enseñaremos a instalarlo en servidores como Railway, Hostinger o Hetzner.</p>', 9, '2025-11-17 20:56:44.254902', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-17 20:56:44.254902', NULL, '0cc0d766-f94d-4295-b6ca-9bcc2d26ee44') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('008bf607-0de6-4c2d-b3f8-1c22b15a5ee4', 'e432692a-7d0a-4e10-846f-ba57c041e96c', 'Comentarios sobre el curso del kit de inicio de IA', NULL, '<p><a target="_blank" rel="noopener noreferrer" class="prose-link" href="https://tally.so/r/w4MDNY"><strong><u>Formulario de comentarios para el Kit de inicio de IA</u></strong></a></p><p>Gracias por dedicar su tiempo a completar el curso del Kit de Inicio de IA. Está en el camino correcto para dominar el NoCode y IA y trabajar de forma más inteligente y recuperar su tiempo.<br><br>Nos esforzamos por mejorar constantemente la calidad de nuestros cursos, por lo que agradeceríamos sus comentarios para que podamos seguir brindándole una mejor formación en IA.</p><p>Atentamente, El equipo de Expertos NoCode IA</p>', 35, '2025-09-02 20:10:11.635634', 'text', 10, true, false, NULL, NULL, NULL, '2025-09-02 20:10:11.635634', NULL, NULL) ON CONFLICT DO NOTHING;
