INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('1151072e-761d-4b68-a90e-4435529a76db', '09ada3b5-0858-4944-b203-675d6c5708be', 'Introducción a la Formación de Agentes de IA', NULL, '<p><span><strong>Links Importantes</strong></span></p><p><span>1 - Faça seu Check In:</span><br><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://tally.so/r/nG1A7O"><span>https://tally.so/r/nG1A7O</span></a><span>&nbsp;</span><br><br><span>2 - Acesse a Comunidade:</span><br><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://open.nocodestartup.io"><span>https://open.nocodestartup.io</span></a></p><p><span>3- Materiais da Formação:</span><br><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://open.nocodestartup.io/c/materiais-aulas/"><span>https://open.nocodestartup.io/c/materiais-aulas/</span></a></p><p><span>4 - Grupo de Avisos WhatsApp - Exclusivo Alunos</span><br><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://go.nocodestartup.io/campaign/link-convite-alunos-grupo-whatsapp"><span>https://go.nocodestartup.io/campaign/link-convite-alunos-grupo-whatsapp</span></a><br><br><span>5 - Acesse o Plano de Estudos de 30 dias no Notion &nbsp;- Jornada Agentes de IA:&nbsp;</span><br><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://curved-leotard-8fa.notion.site/Plano-30D-Jornada-Agentes-de-IA-2883334c21ca818f9858c79b432ab81b?source=copy_link"><span>https://curved-leotard-8fa.notion.site/Plano-30D-Jornada-Agentes-de-IA-2883334c21ca818f9858c79b432ab81b?source=copy_link</span></a></p>', 1, '2025-11-12 19:26:39.333014', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-12 19:26:39.333014', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('11f5cb06-a3fd-4bb9-8a3e-0af0c2ff4ff5', '9cbee862-ffae-45c1-b3b5-a45ecbc0a043', ' Su Primer Agente IA en 30 min', NULL, '<p><strong>Crie sua conta no N8N aqui</strong>: <a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://n8n.partnerlinks.io/sxajetziak90">https://n8n.partnerlinks.io/sxajetziak90</a>&nbsp;</p><p>-</p><p>Esse módulo inicial tem objetivo de te dar um gostinho do que você conseguirá construir na Formação de Agentes IA<br>Ele é 100% prático e mão na massa, a ideia aqui é te levar pra prática o mais rápido possível!</p><p>Por enquanto não vamos falar muito de teoria, mas pode ficar tranquilo que depois você aprenderá tudo do zero passo a passo ok?</p><p>Bora criar o primeiro Agente IA!<br>&nbsp;</p><p>-</p><p>Planilha utilizada:&nbsp;<br><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://docs.google.com/spreadsheets/d/1-8NwVfFPRUK94iqZx8w57VMTyFtg1HW2a9F2GKjoomM/edit?gid=0#gid=0">https://docs.google.com/spreadsheets/d/1-8NwVfFPRUK94iqZx8w57VMTyFtg1HW2a9F2GKjoomM/edit?gid=0#gid=0</a></p><p>-</p><p>Prompt utilizado na aula:</p><p># Objetivo<br>Você é um assistente financeiro pessoal. Seu papel é ajudar o usuário a visualizar e registrar seus gastos, usando uma planilha do Google Sheets conectada.&nbsp;<br><br># Ferramentas disponíveis:&nbsp;<br><br>1. Visualizar Gastos Acessa a planilha do Google Sheets e traz a lista completa de gastos.&nbsp;<br>• Você pode fazer cálculos sobre os dados, como somar valores por categoria ou filtrar por nome.&nbsp;<br><br>2. Criar Gasto Registra um novo gasto na planilha.&nbsp;<br>• Para isso, o usuário deve informar:&nbsp;<br>• Nome do gasto&nbsp;<br>• Categoria: deve ser uma das seguintes — Comida, Estudos, ou Lazer (não são permitidas outras categorias)&nbsp;<br>• Valor (em reais)&nbsp;<br><br># Instruções gerais:&nbsp;<br>• Seja direto, claro e amigável.&nbsp;<br>• Sempre que possível, confirme com o usuário antes de criar um gasto.&nbsp;<br>• Se o usuário pedir uma categoria inválida, informe que só existem as três permitidas. • Ao exibir dados, organize de forma clara, podendo usar tabelas simples. • Ao realizar cálculos, explique brevemente o que foi feito.&nbsp;<br><br># Exemplos de Comandos:&nbsp;<br>• “Me mostra meus gastos da semana.”&nbsp;<br>• “Quero saber quanto gastei com comida.”&nbsp;<br>• “Adiciona um gasto de R$45 em lazer chamado ‘Cinema’.”&nbsp;<br>• “Registrar um gasto de R$120 em estudos chamado ‘Curso de Excel’.”</p><p>&nbsp;</p>', 1, '2025-11-12 19:30:22.888246', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-12 19:30:22.888246', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('24453b47-3a7b-433a-a790-f0f2b731557f', '050c5ea2-ab9b-40c2-a7c1-99b544feb945', '3.1 - El poder de los agentes IA', NULL, NULL, 8, '2025-11-13 16:13:02.276099', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-13 16:13:02.276099', NULL, '175f32d2-2beb-41d7-9d92-1d9c0d79c3ec') ON CONFLICT DO NOTHING;
