INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('379c1d33-18ac-4eda-83d2-4d2481a7c662', 'bed9ee88-a19a-44ae-b667-694f1e630bf5', '1.4 - Comunicado sobre Self Host, Serverless y Cloud', NULL, '<p>Chicos, os recomendamos seguir las clases aquí con n8n Cloud y luego os enseñaremos a instalarlo en servidores, ¿vale?</p><p>Facilita mucho el aprendizaje, aprovechad los 14 días gratis para aprender.</p><p>Después, en la FASE 5 del curso os enseñaremos a instalarla en servidores como Railway, Hostinger o Hetzner.</p>', 6, '2025-11-17 20:27:01.937581', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-17 20:27:01.937581', NULL, '5b98a980-7927-4f2c-9fb6-993b1ca8f483') ON CONFLICT DO NOTHING;
