INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('db025d7a-f666-4bd4-8f24-820f0e7f8556', '93349ddd-1dd9-44be-88ae-9ec62919d8b8', '7.1 - Resumen y conclusiones', NULL, NULL, 33, '2025-11-26 22:27:56.927432', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-26 22:27:56.927432', NULL, '9a4134b1-e8e3-4980-a3d6-0495df10922f') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('658e9082-765b-4760-912a-eeb989edf629', '93349ddd-1dd9-44be-88ae-9ec62919d8b8', '7.2 - Cómo utilizar plantillas y convenciones', NULL, NULL, 34, '2025-11-26 22:29:11.824667', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-26 22:29:11.824667', NULL, '9a4134b1-e8e3-4980-a3d6-0495df10922f') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('751025e8-a2a9-4a52-804f-da3ed39c3598', '93349ddd-1dd9-44be-88ae-9ec62919d8b8', '6.2 - Desactivando el Agente a petición del usuario', NULL, '<p>Prompt</p><p># Instrucciones</p><p>- Utilice siempre esta herramienta para transferir la conversación a un agente humano.</p><p>- ¡Atención! Antes de activar esta función y transferir la conversación a un humano, recuerde al cliente en qué asuntos puede ayudarle y confirme si, aun así, desea continuar con la atención humana.</p><p>- Confirme siempre con el cliente antes de activar esta función.</p><p></p><p># Respuesta correcta:</p><p>Después de activar esta función, responda al usuario que la conversación ha sido transferida a un asesor especializado que se pondrá en contacto con él en breve y continuará con la atención.</p>', 30, '2025-11-18 23:32:31.281', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-18 23:32:31.281', NULL, '1a3bc9fd-0af7-47c7-b243-574f9489f0f1') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('850e42cf-aa31-49f3-afa0-07e814832bca', '93349ddd-1dd9-44be-88ae-9ec62919d8b8', '6.3 - Detener el flujo para agentes desactivados', NULL, NULL, 31, '2025-11-18 23:36:36.322305', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-18 23:36:36.322305', NULL, '1a3bc9fd-0af7-47c7-b243-574f9489f0f1') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('c849c48a-0836-4e67-986e-6bb30e8b8c1e', '93349ddd-1dd9-44be-88ae-9ec62919d8b8', '8 - Mejoras en la plantilla maestra', NULL, NULL, 35, '2025-11-26 22:29:46.523566', 'text', 10, true, false, NULL, NULL, NULL, '2025-11-26 22:29:46.523566', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('67620802-d890-4d8a-a21c-e586d72ee858', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '1.1 - Introducción a los agentes con herramientas', NULL, '<p>En este módulo, aprenderás a crear agentes inteligentes capaces de acceder e interactuar con diversos servicios en Internet, como bases de datos y API. Desarrollaremos dos proyectos prácticos que demostrarán estas habilidades.</p><p></p><p>El primer proyecto será un agente que puede consultar información sobre superhéroes en una base de datos, proporcionando detalles como poderes, orígenes y afiliaciones. El segundo proyecto será un asistente financiero personal, que podrá gestionar tus gastos, permitiéndote visualizar, crear y actualizar registros en una base de datos.</p><p></p><p>A lo largo de las clases, comprenderá los fundamentos necesarios para que su agente pueda comunicarse con diferentes sistemas, accediendo y manipulando datos en tiempo real. Prepárese para ampliar las posibilidades de automatización y personalización de tareas, creando asistentes virtuales versátiles y potentes.</p>', 2, '2025-11-27 01:39:19.908754', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-27 01:39:19.908754', NULL, '0dac2ad1-5780-4b77-90d9-9f5f1e883b5c') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('ab33e9e6-b6e2-483b-93d2-272cfc0c3f2e', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '1.2 - Explicación de herramientas y llamada de funciones', NULL, '<p>En este módulo, aprenderás a crear agentes inteligentes capaces de acceder e interactuar con diversos servicios en Internet, como bases de datos y API. Desarrollaremos dos proyectos prácticos que demostrarán estas habilidades.</p><p></p><p>El primer proyecto será un agente que puede consultar información sobre superhéroes en una base de datos, proporcionando detalles como poderes, orígenes y afiliaciones. El segundo proyecto será un asistente financiero personal, que podrá gestionar tus gastos, permitiéndote visualizar, crear y actualizar registros en una base de datos.</p><p></p><p>A lo largo de las clases, comprenderá los fundamentos necesarios para que su agente pueda comunicarse con diferentes sistemas, accediendo y manipulando datos en tiempo real. Prepárese para ampliar las posibilidades de automatización y personalización de tareas, creando asistentes virtuales versátiles y potentes.</p>', 3, '2025-11-27 01:41:03.327766', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-27 01:41:03.327766', NULL, '0dac2ad1-5780-4b77-90d9-9f5f1e883b5c') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('87050dcd-cd9c-44c6-8250-296d01db8b33', '93349ddd-1dd9-44be-88ae-9ec62919d8b8', '5.4 - Clase extra: Método 2 para descifrar mensajes', NULL, '<p>En esta lección, presentamos un segundo método, más sencillo y directo, para transformar la respuesta del agente de IA en mensajes cortos y humanizados.</p><p></p><p>A diferencia de los enfoques enseñados en las clases 5.2 (Analizador de salida) y 5.3 (Bucle de respuestas), aquí mostramos cómo sustituir el nodo Analizador de salida por una solución más ágil, utilizando el nodo Editar campos en matriz con división por saltos de línea.</p><p></p><p>Esta técnica reduce la complejidad del flujo y facilita la lectura de la respuesta por parte del usuario final.</p>', 27, '2025-11-18 23:25:19.705443', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-18 23:25:19.705443', NULL, 'f81508e0-2a5b-4c1b-b93c-6cabce5bcb19') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('a4a6eaa3-53f1-49de-9dc6-bc3649ebe065', '93349ddd-1dd9-44be-88ae-9ec62919d8b8', '8.1 - Desactivación activa del agente', NULL, '<p>En esta lección, enseñamos cómo hacer que la plantilla maestra detecte de forma inteligente el momento adecuado para desactivarse automáticamente cuando un humano entra activamente en la conversación.</p><p>Esto permite un control más eficiente y natural en la alternancia entre la IA y los operadores humanos.</p>', 36, '2025-11-26 22:31:09.873392', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-26 22:31:09.873392', NULL, 'c849c48a-0836-4e67-986e-6bb30e8b8c1e') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('46f3ceb5-34db-407c-a61b-15599868c78c', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '2 - Primer caso con herramientas', NULL, NULL, 4, '2025-11-27 01:42:44.405284', 'text', 10, true, false, NULL, NULL, NULL, '2025-11-27 01:42:44.405284', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('5833a29c-3cac-485b-877d-f8e61524278a', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '2.1 - Herramientas en la práctica', NULL, '<p>En esta lección, exploraremos aún más las potentes herramientas de integración de N8N. Aprenderemos cómo conectar nuestro agente inteligente a diversas API y servicios externos, ampliando sus capacidades y permitiéndole realizar tareas cada vez más complejas.</p><p></p><p>Veremos cómo activar las herramientas adecuadas en el momento oportuno, convirtiendo a nuestro agente en un verdadero trabajador autónomo, capaz de comprender el contexto de la conversación y activar los recursos necesarios para proporcionar respuestas precisas y útiles.</p><p></p><p>¡Prepárate para ampliar aún más las posibilidades de tu asistente virtual!</p>', 5, '2025-11-27 01:43:47.935081', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-27 01:43:47.935081', NULL, '46f3ceb5-34db-407c-a61b-15599868c78c') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('c368c1d1-271a-40b1-8dc6-2b8cdf4e5049', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '3 - Agente que interactúa con la base de datos', NULL, NULL, 7, '2025-12-03 20:00:35.448173', 'text', 10, true, false, NULL, NULL, NULL, '2025-12-03 20:00:35.448173', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('4192bc5f-7572-4194-8c16-c104413279a0', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '2.2 - Caso Superhéroes', NULL, '<p>Prompt:</p><p></p><p>Eres un experto en superhéroes. Cada vez que el usuario pregunte por un héroe, activa la herramienta datos_heroi, enviando la variable nombre_heroi. Importante: envía siempre el nombre del héroe en su versión inglesa, por ejemplo, en lugar de enviar «homem aranha», envía «spider man».</p><p></p><p>Al recibir los datos, responde de forma atractiva:</p><ol class="prose-ordered-list"><li><p>Presenta al héroe con su nombre real y un detalle destacado.</p></li><li><p>Destaca sus puntos fuertes basándote en sus atributos más destacados.</p></li><li><p>Resume brevemente su origen e historia.</p></li><li><p>Menciona grupos y conexiones relevantes.</p></li><li><p>Muestra la imagen del héroe al final.</p></li></ol><p></p><p>Ejemplo de respuesta para Wolverine:</p><p></p><p>¡Wolverine (Logan) es un mutante implacable con factor de curación y garras de adamantio!</p><p></p><p>Puntos fuertes:</p><p>• Durabilidad 100 → ¡Casi indestructible!</p><p>• Combate 100 → Maestro en el combate cuerpo a cuerpo.</p><p>• Poder 89 → Habilidades mutantes y resistencia fuera de lo común.</p><p></p><p>Origen: Nacido en Canadá, debutó en Incredible Hulk #180. Fue soldado, mercenario y espía antes de convertirse en un X-Men.</p><p></p><p>Afiliaciones: X-Men, Vengadores, Alpha Flight.</p><p></p><p>¡Míralo en acción!</p><p><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://www.superherodb.com/pictures2/portraits/10/100/161.jpg">https://www.superherodb.com/pictures2/portraits/10/100/161.jpg</a></p>', 6, '2025-11-27 01:46:04.485642', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-11-27 01:46:04.485642', NULL, '46f3ceb5-34db-407c-a61b-15599868c78c') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('e10dc4ed-894b-4bbf-8371-c73c21401f73', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '3.1 - Configuración de N8N y Supabase', NULL, '<p>En esta lección, explorará las potentes herramientas de integración de N8N y aprenderá a conectar su agente inteligente a diversas API y servicios externos. Descubrirá cómo activar los recursos adecuados en el momento oportuno, convirtiendo a su asistente virtual en un verdadero trabajador autónomo, capaz de comprender el contexto de la conversación y activar los medios necesarios para proporcionar respuestas precisas y útiles. </p><p>Prepárate para ampliar aún más las posibilidades de tu agente, llevándolo a nuevos niveles de funcionalidad y abriendo un mundo de nuevas aplicaciones.</p>', 8, '2025-12-03 22:48:00.872382', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-03 22:48:00.872382', NULL, 'c368c1d1-271a-40b1-8dc6-2b8cdf4e5049') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('b13732fd-143f-45c9-8a7d-3fa3fcd2edba', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '3.2 - Visualizar datos', NULL, '<p>Prompt:</p><p></p><p>Eres un asistente financiero capaz de gestionar registros de gastos en Supabase. Tu función es interactuar con la tabla gastos, ayudando al usuario a visualizar sus gastos.</p><p></p><p>Siempre que el usuario lo solicite, activa la herramienta:</p><p></p><p>1️⃣ Visualizar gastos (tool_visualizar_gastos)</p><p>• Muestra los registros de la tabla con el nombre, el tipo y el valor.</p><p>• Si el usuario desea filtrar por tipo o período, pregúntale los criterios antes de llamar a la herramienta.</p><p></p>', 9, '2025-12-06 00:49:30.617262', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-06 00:49:30.617262', NULL, 'c368c1d1-271a-40b1-8dc6-2b8cdf4e5049') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('134c8521-3de9-47cc-8e56-f0164dedd309', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '3.3 - Crear datos', NULL, '<p>Prompt</p><p></p><p>Eres un asistente financiero capaz de gestionar registros de gastos en Supabase. Tu función es interactuar con la tabla gastos, ayudando al usuario a visualizar y añadir sus gastos.</p><p></p><p>Siempre que el usuario lo solicite, activa la herramienta:</p><p></p><p>1️⃣ Visualizar gastos (tool_visualizar_gastos)</p><p>• Muestra los registros de la tabla con el nombre, el tipo y el valor.</p><p>• Si el usuario desea filtrar por tipo o período, pregúntale los criterios antes de llamar a la herramienta.</p><p></p><p>2️⃣ Añadir gasto (tool_crear_gasto)</p><p>Para activar la herramienta es necesario tener:</p><p>- nombre_gasto (nombre del gasto);</p><p>- valor_gasto (valor del gasto);</p><p>- tipo_gasto (debe categorizar el tipo según el mensaje del usuario, solo hay 4 tipos de gastos: Supermercado, Ocio, Salud y Educación)</p><p>Confirme el registro antes de enviarlo.</p>', 10, '2025-12-06 00:50:45.80358', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-06 00:50:45.80358', NULL, 'c368c1d1-271a-40b1-8dc6-2b8cdf4e5049') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('153ed02d-90dc-4698-b67e-0e44ffb0ecd5', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '3.4 - Actualizar datos y finalización', NULL, '<p>Prompt completo</p><p></p><p>Eres un asistente financiero capaz de gestionar registros de gastos en Supabase. Tu función es interactuar con la tabla de gastos, ayudando al usuario a visualizar, añadir y editar sus gastos.</p><p></p><p>Siempre que el usuario lo solicite, activa la herramienta:</p><p></p><p>1️⃣ Visualizar gastos (tool_visualizar_gastos)</p><p>• Muestra los registros de la tabla con nombre, tipo y valor.</p><p>• Si el usuario desea filtrar por tipo o período, pregúntale los criterios antes de llamar a la herramienta.</p><p></p><p>2️⃣ Añadir gasto (tool_crear_gasto)</p><p>Para activar la herramienta es necesario tener:</p><p>- nombre_gasto (nombre del gasto);</p><p>- valor_gasto (valor del gasto);</p><p>- tipo_gasto (debe categorizar el tipo según el mensaje del usuario, solo hay 4 tipos de gastos: Supermercado, Ocio, Salud y Educación)</p><p>Confirme el registro antes de enviarlo.</p><p></p><p>3️⃣ Editar gasto (tool_atualizar_gasto), siga los pasos:</p><p>- Pregunte qué registro editar (nombre).</p><p>- Para ello, active la herramienta visualizar gasto para confirmar el nombre exacto del gasto</p><p>- Confirme con el usuario qué gasto va a actualizar</p><p>- Con el nombre_gasto del gasto, active la herramienta tool_atualizar_gasto y realice el cambio</p><p>- Después de la edición, muestre la actualización realizada.</p>', 11, '2025-12-06 00:52:04.10129', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-06 00:52:04.10129', NULL, 'c368c1d1-271a-40b1-8dc6-2b8cdf4e5049') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('0c1aa461-8613-4de2-85c1-4947ee6b47eb', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '4 - MCP - Protocolo de contexto de modelo', NULL, NULL, 12, '2025-12-06 00:53:16.587665', 'text', 10, true, false, NULL, NULL, NULL, '2025-12-06 00:53:16.587665', NULL, NULL) ON CONFLICT DO NOTHING;
