INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('5f7d7321-c4dd-48ac-acaf-978a1f80b656', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '4.5 - Finalización', NULL, NULL, 17, '2025-12-06 12:36:38.507648', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-06 12:36:38.507648', NULL, '0c1aa461-8613-4de2-85c1-4947ee6b47eb') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('3f179ae7-47b5-4d8a-af7f-10b5e6b36e31', '5dfdeacd-6626-4106-bd92-3d4f336cca20', '1. Introducción', NULL, NULL, 1, '2025-12-06 12:55:11.234179', 'text', 10, true, false, NULL, NULL, NULL, '2025-12-06 12:55:11.234179', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('9bfc496b-4266-4d20-a5d9-3118c9cb4bf8', 'd47d6bb6-fd94-497e-b84d-704c96a82780', '4.4 - Optimización del agente', NULL, '<p><strong>Prompts utilizados:</strong></p><p></p><p style="margin-bottom: 4px;">GET EVENT</p><p style="text-align: left; margin-bottom: 4px;">Utilice esta herramienta para buscar un evento (consulta) específico.</p><p style="margin-bottom: 4px;"></p><p style="margin-bottom: 4px;">Flujo sugerido</p><p style="margin-bottom: 4px;">- En primer lugar, ejecute Get All Events para los próximos 7 días, así sabrá todos los próximos eventos.</p><p style="margin-bottom: 4px;">- Busque el evento seleccionado, para ello es necesario que el usuario indique el día y la hora.</p><p style="margin-bottom: 4px;">- Según la fecha y la hora que haya introducido el usuario, busque el evento, su ID y otros detalles.</p><p style="margin-bottom: 4px;">Importante: Día actual {{ $now }}</p><p style="margin-bottom: 4px;"></p><p></p><p>GET ALL EVENTS</p><p></p><p>Utilice esta herramienta para enumerar todos los eventos.</p><p></p><p>Flujo sugerido</p><p>- Recopile el periodo inicial y final. Si el usuario no lo indica, utilice la fecha de hoy más 7 días hacia adelante.</p><p>- Ejecute Get All Events para el período seleccionado.</p><p></p><p>Importante: Día actual {{ $now }}</p><p></p><p></p><p>CREATE EVENTS</p><p></p><p>Utilice esta herramienta para crear una consulta en el calendario.</p><p></p><p>Flujo sugerido:</p><p>- Pregunte el nombre de la persona, el día y la hora deseados.</p><p>- Llame a Get All Events. Si no hay conflicto de eventos, llame a Create Event. Todas las consultas tienen 1 hora y rellene el campo «Summary» con [Nombre de la persona];</p><p>- Confirme al usuario: «Su cita se ha programado para [fecha/hora]».</p><p></p><p>Importante: Día actual {{ $now }}</p><p></p><p></p><p>DELETE EVENTOS</p><p></p><p>Utilice esta herramienta para eliminar un evento específico.</p><p></p><p>Flujo sugerido</p><p>- Busque el evento seleccionado. Para ello, el usuario debe indicar el día y la hora.</p><p>- En primer lugar, ejecute Get All Events para los próximos 7 días, de modo que conozca todos los próximos eventos.</p><p>- Según la hora y el día que haya indicado el usuario, busque el evento, su ID y otros detalles.</p><p>- Elimine ese evento con Delete Event.</p><p></p><p>Importante: Día actual {{ $now }}</p>', 16, '2025-12-06 12:21:44.559421', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-06 12:21:44.559421', NULL, '0c1aa461-8613-4de2-85c1-4947ee6b47eb') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('16ba16a0-cc49-4b81-9535-34aae3291134', '5dfdeacd-6626-4106-bd92-3d4f336cca20', '1.1 - Introducción RAG y bancos vectoriales', NULL, '<p>Ejemplos de materiales para descargar:<br><a target="_blank" rel="noopener noreferrer nofollow" class="prose-link" href="https://drive.google.com/drive/u/1/folders/1WiqvYBwMPRCyQiFsuBdfOW1iOMf5k1nW">https://drive.google.com/drive/u/1/folders/1WiqvYBwMPRCyQiFsuBdfOW1iOMf5k1nW</a><span style="font-family: __productSans_1af375, __productSans_Fallback_1af375; font-size: 16px; color: rgb(222, 226, 230);">&nbsp;</span></p>', 2, '2025-12-06 12:56:57.618512', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-06 12:56:57.618512', NULL, '3f179ae7-47b5-4d8a-af7f-10b5e6b36e31') ON CONFLICT DO NOTHING;
