INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('599ab212-45b1-4868-a016-ef7c152703f0', '5dfdeacd-6626-4106-bd92-3d4f336cca20', '2.1 - Subir archivos al Drive', NULL, NULL, 6, '2025-12-06 13:05:02.384062', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-06 13:05:02.384062', NULL, 'd4855ca5-1505-4060-a79c-5430a0c40fad') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('51af12bf-d829-40b2-871e-2ff2ec297b75', '5dfdeacd-6626-4106-bd92-3d4f336cca20', '3.1 - Creación del agente integrado RAG', NULL, '<p>Prompt:</p><p></p><p>## Instrucciones generales para el agente</p><p></p><p>Usted es un especialista en servicios de IA, responsable de proporcionar información detallada y personalizada sobre los servicios ofrecidos por un gestor de agentes de IA.</p><p>Su objetivo es aclarar dudas y ayudar a los clientes potenciales a elegir el servicio ideal para sus necesidades.</p><p></p><p>## Público objetivo</p><p>Su usuario es un cliente potencial, que puede ser un empresario, propietario de una startup, gestor de tecnología o cualquier profesional interesado en integrar agentes de IA en su negocio.</p><p></p><p>## Fuentes de información</p><p>Para responder a las preguntas, puede consultar una base de datos vectorial para recuperar información sobre los tipos de servicios ofrecidos, descripciones, precios, plazos e integraciones disponibles.</p><p></p><p>## Reglas de atención</p><p>1. Sea claro y objetivo: responda con un lenguaje accesible, evitando jerga técnica innecesaria.</p><p>2. Comprenda las necesidades del cliente: pregunte sobre el contexto del usuario antes de recomendar un servicio.</p><p>3. Utilice la base de datos vectorial: si necesita información más detallada, consulte la base de datos antes de responder.</p><p>4. Explique los beneficios y las diferencias: al describir un servicio, destaque cómo puede generar valor para el cliente.</p><p>5. Proporcione los siguientes pasos: si el usuario muestra interés, sugiérele que se ponga en contacto para obtener más información o un presupuesto.</p>', 10, '2025-12-06 13:27:28.510802', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-06 13:27:28.510802', NULL, '8febd8d9-90be-4dbb-a220-74b8a58583f2') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('a452fab8-2e63-4258-b59c-3cb57387b179', '5dfdeacd-6626-4106-bd92-3d4f336cca20', '2.2 - Configuración de Vector Store', NULL, '<p></p><p><strong>Observación sobre Data Loader:</strong></p><p>Si tu Data Loader aparece con un formato diferente al mostrado en la lección (icono circular), ajusta la configuración de división de texto. Ve a la sección Text Splitting y selecciona la opción Simple. Esto activa el divisor predeterminado (1000 caracteres con 200 de superposición) y hace que el nodo tenga el mismo formato que en la lección (icono cilíndrico).</p><p></p><p><strong>Script:</strong></p><p>Para ejecutar este script, abra el Editor SQL de Supabase y pegue el código completo que aparece a continuación. A continuación, haga clic en Run para crear la tabla de documentos, habilitar pgvector y registrar la función de búsqueda.</p><p></p><pre><code>\n-- Habilita la extensión pgvector\nCREATE EXTENSION IF NOT EXISTS vector;\n-- Crea la tabla\nCREATE TABLE documents (\nid bigserial PRIMARY KEY,\ncontent text,\nmetadata jsonb,\nembedding vector(1536) -- 1536 funciona para embeddings de OpenAI\n);\n-- Crea la función de búsqueda\nCREATE FUNCTION match_documents (\nquery_embedding vector(1536),\nmatch_count int DEFAULT NULL,\nfilter jsonb DEFAULT “{}”\n)\nRETURNS TABLE (\nid bigint,\ncontent text,\nmetadata jsonb,\nsimilarity float\n)\nAS $$\nBEGIN\nRETURN QUERY\nSELECT\nd.id,\nd.content,\nd.metadata,\n1 - (d.embedding &lt;=&gt; query_embedding) AS similarity\nFROM documents d\nWHERE d.metadata @&gt; filter\nORDER BY d.embedding &lt;=&gt; query_embedding\nLIMIT match_count;\nEND;\n$$ LANGUAGE plpgsql;</code></pre><p></p>', 7, '2025-12-06 13:13:35.10236', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-06 13:13:35.10236', NULL, 'd4855ca5-1505-4060-a79c-5430a0c40fad') ON CONFLICT DO NOTHING;
INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('a7d6d856-c567-4ac2-950b-b0fcccbb5778', '5dfdeacd-6626-4106-bd92-3d4f336cca20', '2.3 - Adaptando el flujo a hojas de cálculo', NULL, NULL, 8, '2025-12-06 13:26:06.251492', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-06 13:26:06.251492', NULL, 'd4855ca5-1505-4060-a79c-5430a0c40fad') ON CONFLICT DO NOTHING;
