INSERT INTO lessons (id, course_id, title, description, content, "order", created_at, type, duration, is_published, is_free, video_url, attachments, objectives, updated_at, image_url, parent_lesson_id) VALUES ('6bc9b7dd-68fe-4e79-8dc5-bc406dfa908e', '5dfdeacd-6626-4106-bd92-3d4f336cca20', '3.2 - Pruebas finales', NULL, NULL, 11, '2025-12-06 13:29:26.452896', 'video', 10, true, false, 'https://youtu.be/Q8IjAFXuV-Y?list=PLv0-mlXD9ES3OnFoPGmmrbgHF5H9H5DCh', NULL, NULL, '2025-12-06 13:29:26.452896', NULL, '8febd8d9-90be-4dbb-a220-74b8a58583f2') ON CONFLICT DO NOTHING;
INSERT INTO live_events (id, title, description, host_name, host_avatar, host_role, start_time, end_time, timezone, is_active, is_live, join_url, room_name, event_type, created_at, updated_at, event_image, category) VALUES ('564797f3-7d2d-4e9f-a59e-9f3a934ecf1a', 'Nano Banana Pro para presentaciones', '<p></p><p></p><p>La mayoría de los modelos de imagen han tenido problemas de consistencia, texto desordenado, detalles omitido y un estilo que cambia de diapositiva en diapositiva. Nano Banana Pro cambia eso. Sigue las instrucciones, mantiene un lenguaje de diseño coherente y maneja información real sin fallar. Apenas estamos empezando a ver lo que puede hacer, pero los primeros resultados justifican la expectativa.<br></p><hr><p><br><strong>Aprenderás a:</strong></p><p><strong>Bloquee un sistema de estilo de diapositivas reutilizable</strong><br>Primero cree una plantilla de estilo simple, de modo que cada gráfico en su presentación parezca que pertenece junto.</p><p><strong>Vaya del esquema → ideas visuales → imágenes finales.</strong><br>Utilice un flujo de dos pasos: haga que el modelo revise su contenido y presente instrucciones visuales, <em>luego</em> convierta las mejores en indicaciones visuales.</p><p><strong>Diseñe diapositivas que expliquen, no que decoren.</strong><br>Cree diagramas, infografías y diapositivas de título con texto y diseño precisos.</p><hr><p></p><h3><strong>Este taller es para ti si…</strong></h3><ul class="prose-bullet-list"><li><p>Construyes terrazas y quieres que se vean mejor</p></li><li><p>Estás cansado de luchar con fotos de archivo e íconos desordenados.</p></li><li><p>Ha probado herramientas de imágenes con IA y ha obtenido resultados inconsistentes y ruidosos.</p></li><li><p>Quiere un flujo de trabajo repetible, no un "truco puntual" único.</p></li></ul><p></p>', 'Fabian  Segura', 'https://ehmihfufuufthefwrnrb.supabase.co/storage/v1/object/public/attached-assets/events/event-1764972745255.png', 'Founder', '2025-12-08 09:00:00', '2025-12-08 10:00:00', 'America/Bogota', true, false, NULL, NULL, 'workshop', '2025-11-26 18:13:20.281724', '2025-12-06 00:47:19.813', NULL, 'Creación de contenido') ON CONFLICT DO NOTHING;
